insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:riz pilaf', 'Rice pilaf', array['en:rice pilaf', 'en:pilaf', 'en:pilau rice', 'en:pilaf rice']::text[], 'dish', $r$[{"title":"Rice pilaf","intro":"Rice toasted with onion, then cooked in stock, with nicely separate grains.","minutes":30,"calories":280,"difficulty":"Facile","imageSearch":"rice pilaf","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rice","plural":"rice","qty":300,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false}],"steps":[{"text":"Soften the sliced onion in the butter.","timer":null},{"text":"Add the rice and stir for 2 minutes until it turns pearly.","timer":null},{"text":"Pour in 60 cl of hot stock and add the thyme.","timer":null},{"text":"Cover and cook for 17 minutes over a low heat without stirring.","timer":{"label":"Cooking","min":17}}],"kids":true,"variant":"The classic","change":""},{"title":"Vegetable rice pilaf","intro":"A colourful rice pilaf, a full meal with its vegetables.","minutes":30,"calories":300,"difficulty":"Facile","imageSearch":"vegetable rice pilaf","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rice","plural":"rice","qty":300,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":1,"unit":"","have":false},{"name":"frozen pea","plural":"frozen peas","qty":100,"unit":"g","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Fry the onion, and the carrot and pepper (diced), in the oil.","timer":null},{"text":"Add the rice and stir for 2 minutes.","timer":null},{"text":"Pour in 60 cl of hot stock and cook for 12 minutes with the lid on.","timer":{"label":"Cooking","min":12}},{"text":"Add the peas and cook for 5 minutes.","timer":{"label":"Cooking","min":5}}],"kids":true,"variant":"With vegetables","change":"With carrots, peas and pepper."},{"title":"Spiced rice pilaf","intro":"A golden rice pilaf, Middle Eastern style.","minutes":30,"calories":310,"difficulty":"Facile","imageSearch":"spiced rice pilaf","veg":true,"oven":false,"cold":false,"missing":"","origin":"Middle Eastern-inspired","serves":4,"items":[{"name":"basmati rice","plural":"basmati rice","qty":300,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"turmeric","plural":"turmeric","qty":1,"unit":"tsp","have":false},{"name":"cinnamon stick","plural":"cinnamon sticks","qty":1,"unit":"","have":false},{"name":"raisin","plural":"raisins","qty":40,"unit":"g","have":false},{"name":"flaked almond","plural":"flaked almonds","qty":30,"unit":"g","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false}],"steps":[{"text":"Fry the onion with the turmeric and cinnamon.","timer":null},{"text":"Add the rice and stir for 2 minutes.","timer":null},{"text":"Pour in 55 cl of hot stock, add the raisins and cook for 15 minutes with the lid on.","timer":{"label":"Cooking","min":15}},{"text":"Sprinkle with toasted almonds.","timer":null}],"variant":"Spiced","change":"Flavoured with turmeric, cinnamon and raisins."}]$r$::jsonb, 'claude')
