insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:porridge', 'Porridge', array['en:oatmeal', 'en:overnight oat']::text[], 'dish', $r$[{"title":"Porridge","intro":"Creamy oats cooked in milk, with banana and honey.","minutes":10,"calories":320,"difficulty":"Facile","imageSearch":"oatmeal porridge banana","veg":true,"oven":false,"cold":false,"missing":"","origin":"British breakfast","serves":4,"items":[{"name":"rolled oat","plural":"rolled oats","qty":200,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":80,"unit":"cl","have":false},{"name":"banana","plural":"bananas","qty":2,"unit":"","have":false},{"name":"honey","plural":"honey","qty":2,"unit":"tbsp","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Pour the oats and the milk into a saucepan.","timer":null},{"text":"Cook for 5 minutes over a low heat, stirring, until creamy.","timer":{"label":"Cooking","min":5}},{"text":"Add the cinnamon.","timer":null},{"text":"Serve in bowls with sliced banana and a drizzle of honey.","timer":null}],"kids":true,"dessert":true,"variant":"The classic","change":""},{"title":"Overnight oats","intro":"Cold porridge made the night before, ready when you wake up.","minutes":10,"calories":330,"difficulty":"Facile","imageSearch":"overnight oats jar","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"rolled oat","plural":"rolled oats","qty":200,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":40,"unit":"cl","have":false},{"name":"plain yoghurt","plural":"plain yoghurts","qty":2,"unit":"","have":false},{"name":"chia seed","plural":"chia seeds","qty":2,"unit":"tbsp","have":false},{"name":"mixed berries","plural":"mixed berries","qty":200,"unit":"g","have":false},{"name":"honey","plural":"honey","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Mix the oats, milk, yoghurts, chia and honey.","timer":null},{"text":"Divide between 4 jars.","timer":null},{"text":"Close the jars and leave in the fridge overnight.","timer":null},{"text":"Add the berries just before serving.","timer":null}],"kids":true,"dessert":true,"variant":"No cooking","change":"The oats soak overnight in the fridge."},{"title":"Apple and cinnamon porridge","intro":"A winter porridge with caramelised apples.","minutes":15,"calories":340,"difficulty":"Facile","imageSearch":"apple cinnamon oatmeal","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rolled oat","plural":"rolled oats","qty":200,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":80,"unit":"cl","have":false},{"name":"apple","plural":"apples","qty":2,"unit":"","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false},{"name":"brown sugar","plural":"brown sugar","qty":2,"unit":"tbsp","have":false},{"name":"butter","plural":"butter","qty":10,"unit":"g","have":false}],"steps":[{"text":"Cook the oats in the milk for 5 minutes, stirring.","timer":{"label":"Cooking","min":5}},{"text":"Dice the apples.","timer":null},{"text":"Brown them for 5 minutes in the butter with the sugar and cinnamon.","timer":{"label":"Pan","min":5}},{"text":"Serve the porridge with the apples on top.","timer":null}],"kids":true,"dessert":true,"variant":"Apple","change":"With pan-fried apples and cinnamon."}]$r$::jsonb, 'claude')
