insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:granola', 'Granola', array['en:homemade granola', 'en:muesli']::text[], 'dish', $r$[{"title":"Homemade granola","intro":"Oats, nuts and honey roasted in the oven into crunchy clusters.","minutes":40,"calories":250,"difficulty":"Facile","imageSearch":"homemade granola","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rolled oat","plural":"rolled oats","qty":300,"unit":"g","have":false},{"name":"almond","plural":"almonds","qty":80,"unit":"g","have":false},{"name":"hazelnut","plural":"hazelnuts","qty":50,"unit":"g","have":false},{"name":"honey","plural":"honey","qty":5,"unit":"tbsp","have":false},{"name":"coconut oil","plural":"coconut oil","qty":4,"unit":"tbsp","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 160 °C.","timer":null},{"text":"Mix the oats, the almonds, the crushed hazelnuts and the cinnamon.","timer":null},{"text":"Add the honey and the melted oil and mix well.","timer":null},{"text":"Spread on a baking tray and bake for 25 minutes, stirring every 10 minutes.","timer":{"label":"Oven","min":25}},{"text":"Leave to cool before putting in a jar.","timer":null}],"dessert":true,"variant":"The classic","change":""},{"title":"Chocolate granola","intro":"A chocolatey granola for those with a sweet tooth.","minutes":40,"calories":280,"difficulty":"Facile","imageSearch":"chocolate granola","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rolled oat","plural":"rolled oats","qty":300,"unit":"g","have":false},{"name":"hazelnut","plural":"hazelnuts","qty":80,"unit":"g","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":3,"unit":"tbsp","have":false},{"name":"honey","plural":"honey","qty":5,"unit":"tbsp","have":false},{"name":"coconut oil","plural":"coconut oil","qty":4,"unit":"tbsp","have":false},{"name":"chocolate chip","plural":"chocolate chips","qty":60,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 160 °C.","timer":null},{"text":"Mix the oats, the crushed hazelnuts and the cocoa, then the honey and the melted oil.","timer":null},{"text":"Spread on a baking tray and bake for 25 minutes, stirring.","timer":{"label":"Oven","min":25}},{"text":"Leave to cool and add the chocolate chips.","timer":null}],"kids":true,"dessert":true,"variant":"Chocolate","change":"With cocoa and chocolate chips."},{"title":"Coconut and dried fruit granola","intro":"A tropical granola with coconut and dried apricots.","minutes":40,"calories":260,"difficulty":"Facile","imageSearch":"coconut granola","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rolled oat","plural":"rolled oats","qty":300,"unit":"g","have":false},{"name":"desiccated coconut","plural":"desiccated coconut","qty":50,"unit":"g","have":false},{"name":"almond","plural":"almonds","qty":60,"unit":"g","have":false},{"name":"dried apricot","plural":"dried apricots","qty":80,"unit":"g","have":false},{"name":"maple syrup","plural":"maple syrup","qty":5,"unit":"tbsp","have":false},{"name":"coconut oil","plural":"coconut oil","qty":3,"unit":"tbsp","have":false}],"steps":[{"text":"Preheat the oven to 160 °C.","timer":null},{"text":"Mix the oats, the coconut and the almonds, then the maple syrup and the melted oil.","timer":null},{"text":"Spread on a baking tray and bake for 25 minutes, stirring.","timer":{"label":"Oven","min":25}},{"text":"Leave to cool and add the chopped apricots.","timer":null}],"dessert":true,"variant":"Coconut","change":"With coconut and dried fruit."}]$r$::jsonb, 'claude')
