insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:smoothie', 'Smoothie', array['en:fruit smoothie', 'en:smoothie bowl', 'en:milkshake']::text[], 'dish', $r$[{"title":"Banana and strawberry smoothie","intro":"A smooth banana and strawberry smoothie, made with yoghurt.","minutes":5,"calories":180,"difficulty":"Facile","imageSearch":"strawberry banana smoothie","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"banana","plural":"bananas","qty":2,"unit":"","have":false},{"name":"strawberry","plural":"strawberries","qty":300,"unit":"g","have":false},{"name":"plain yoghurt","plural":"plain yoghurts","qty":2,"unit":"","have":false},{"name":"milk","plural":"milk","qty":30,"unit":"cl","have":false},{"name":"honey","plural":"honey","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Hull the strawberries and cut the bananas into chunks.","timer":null},{"text":"Put everything in the blender with the yoghurt, the milk and the honey.","timer":null},{"text":"Blend until completely smooth.","timer":null},{"text":"Serve straight away, nice and cold.","timer":null}],"kids":true,"dessert":true,"variant":"The classic","change":""},{"title":"Green smoothie","intro":"A fresh, vitamin-packed smoothie, all green.","minutes":5,"calories":140,"difficulty":"Facile","imageSearch":"green smoothie","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"baby spinach","plural":"baby spinach","qty":60,"unit":"g","have":false},{"name":"kiwi","plural":"kiwis","qty":2,"unit":"","have":false},{"name":"apple","plural":"apples","qty":1,"unit":"","have":false},{"name":"banana","plural":"bananas","qty":1,"unit":"","have":false},{"name":"orange juice","plural":"orange juice","qty":30,"unit":"cl","have":false}],"steps":[{"text":"Peel the kiwis and the banana, and cut up the apple.","timer":null},{"text":"Put everything in the blender with the spinach and the orange juice.","timer":null},{"text":"Blend until smooth.","timer":null},{"text":"Serve straight away.","timer":null}],"dessert":true,"variant":"Green","change":"With spinach, kiwi and apple."},{"title":"Smoothie bowl","intro":"The smoothie you eat with a spoon, topped with fruit and granola.","minutes":10,"calories":320,"difficulty":"Facile","imageSearch":"acai smoothie bowl","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"frozen banana","plural":"frozen bananas","qty":2,"unit":"","have":false},{"name":"frozen mixed berries","plural":"frozen mixed berries","qty":300,"unit":"g","have":false},{"name":"greek yoghurt","plural":"greek yoghurts","qty":2,"unit":"","have":false},{"name":"granola","plural":"granola","qty":60,"unit":"g","have":false},{"name":"kiwi","plural":"kiwis","qty":1,"unit":"","have":false}],"steps":[{"text":"Blend the frozen bananas, the berries and the yoghurt with no liquid, for a thick texture.","timer":null},{"text":"Pour into bowls.","timer":null},{"text":"Top with granola and sliced kiwi.","timer":null},{"text":"Serve right away.","timer":null}],"dessert":true,"variant":"Bowl","change":"Thicker, served in a bowl with toppings."}]$r$::jsonb, 'claude')
