insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:bowl cake', 'Bowl cake', array['en:bowlcake', 'en:microwave bowl cake', 'en:mug cake']::text[], 'dish', $r$[{"title":"Bowl cake","intro":"The breakfast cake made with oats and banana, cooked in 2 minutes in the microwave.","minutes":5,"calories":300,"difficulty":"Facile","imageSearch":"oatmeal bowl cake","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rolled oat","plural":"rolled oats","qty":160,"unit":"g","have":false},{"name":"banana","plural":"bananas","qty":2,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Mash the bananas in 4 bowls.","timer":null},{"text":"Add 40 g of oats, 1 egg, 5 cl of milk and a pinch of baking powder to each bowl.","timer":null},{"text":"Mix well.","timer":null},{"text":"Cook each bowl for 2 minutes in the microwave.","timer":{"label":"Microwave","min":2}}],"dessert":true,"variant":"The classic","change":""},{"title":"Chocolate bowl cake","intro":"A bowl cake with a gooey chocolate centre.","minutes":5,"calories":350,"difficulty":"Facile","imageSearch":"chocolate bowl cake","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rolled oat","plural":"rolled oats","qty":160,"unit":"g","have":false},{"name":"banana","plural":"bananas","qty":2,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":2,"unit":"tbsp","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":40,"unit":"g","have":false}],"steps":[{"text":"Mash the bananas in 4 bowls and add the oats, the eggs, the milk and the cocoa.","timer":null},{"text":"Mix well.","timer":null},{"text":"Push a square of chocolate into the middle of each bowl.","timer":null},{"text":"Cook each bowl for 2 minutes in the microwave.","timer":{"label":"Microwave","min":2}}],"kids":true,"dessert":true,"variant":"Chocolate","change":"With cocoa and a square of chocolate in the middle."},{"title":"Cocoa mug cake","intro":"The quick cake for a chocolate craving.","minutes":5,"calories":380,"difficulty":"Facile","imageSearch":"chocolate mug cake","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":100,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":4,"unit":"tbsp","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"milk","plural":"milk","qty":12,"unit":"cl","have":false},{"name":"sunflower oil","plural":"sunflower oil","qty":6,"unit":"tbsp","have":false}],"steps":[{"text":"Mix the flour, the sugar and the cocoa.","timer":null},{"text":"Add the eggs, the milk and the oil and mix.","timer":null},{"text":"Divide between 4 mugs.","timer":null},{"text":"Cook each mug for 1 minute 30 in the microwave.","timer":{"label":"Microwave","min":2}}],"kids":true,"dessert":true,"makes":{"n":4,"one":"mug cake","many":"mug cakes"},"variant":"Mug cake","change":"A proper little chocolate cake, cooked in a mug."}]$r$::jsonb, 'claude')
