insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:chia pudding', 'Chia pudding', array['en:chia seed pudding', 'en:chia']::text[], 'dish', $r$[{"title":"Chia pudding","intro":"Chia seeds soaked in coconut milk, served with fresh fruit.","minutes":10,"calories":250,"difficulty":"Facile","imageSearch":"chia pudding","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"chia seed","plural":"chia seeds","qty":80,"unit":"g","have":false},{"name":"coconut milk","plural":"coconut milk","qty":40,"unit":"cl","have":false},{"name":"maple syrup","plural":"maple syrup","qty":2,"unit":"tbsp","have":false},{"name":"mango","plural":"mangoes","qty":1,"unit":"","have":false}],"steps":[{"text":"Mix the chia seeds, the coconut milk and the maple syrup.","timer":null},{"text":"Stir again after 10 minutes to avoid lumps.","timer":null},{"text":"Leave to set for at least 4 hours in the fridge.","timer":null},{"text":"Serve with the diced mango.","timer":null}],"dessert":true,"variant":"The classic","change":""},{"title":"Chocolate chia pudding","intro":"A chia pudding that tastes like chocolate cream.","minutes":10,"calories":260,"difficulty":"Facile","imageSearch":"chocolate chia pudding","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"chia seed","plural":"chia seeds","qty":80,"unit":"g","have":false},{"name":"almond milk","plural":"almond milk","qty":40,"unit":"cl","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":2,"unit":"tbsp","have":false},{"name":"maple syrup","plural":"maple syrup","qty":3,"unit":"tbsp","have":false},{"name":"banana","plural":"bananas","qty":1,"unit":"","have":false}],"steps":[{"text":"Mix the milk, the cocoa and the syrup, then the chia seeds.","timer":null},{"text":"Stir again after 10 minutes.","timer":null},{"text":"Leave to set for at least 4 hours in the fridge.","timer":null},{"text":"Serve with the sliced banana.","timer":null}],"dessert":true,"variant":"Cocoa","change":"With cocoa in the milk."},{"title":"Berry chia pudding","intro":"A fresh, tangy chia pudding.","minutes":10,"calories":220,"difficulty":"Facile","imageSearch":"berry chia pudding","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"chia seed","plural":"chia seeds","qty":80,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":40,"unit":"cl","have":false},{"name":"honey","plural":"honey","qty":2,"unit":"tbsp","have":false},{"name":"mixed berries","plural":"mixed berries","qty":250,"unit":"g","have":false}],"steps":[{"text":"Mix the chia, the milk and the honey, and stir after 10 minutes.","timer":null},{"text":"Leave to set for at least 4 hours in the fridge.","timer":null},{"text":"Crush half of the berries into a sauce.","timer":null},{"text":"Serve the pudding with the sauce and the rest of the berries.","timer":null}],"dessert":true,"variant":"Berries","change":"With a berry sauce."}]$r$::jsonb, 'claude')
