insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:oeuf benedicte', 'Eggs Benedict', array['en:egg benedict']::text[], 'dish', $r$[{"title":"Eggs Benedict","intro":"Poached eggs on toasted muffins and bacon, covered in hollandaise sauce.","minutes":30,"calories":520,"difficulty":"Difficile","imageSearch":"eggs benedict","veg":false,"oven":false,"cold":false,"missing":"","origin":"American brunch","serves":4,"items":[{"name":"egg","plural":"eggs","qty":7,"unit":"","have":false},{"name":"english muffin","plural":"english muffins","qty":2,"unit":"","have":false},{"name":"bacon","plural":"bacon","qty":4,"unit":"slices","have":false},{"name":"butter","plural":"butter","qty":100,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":0.5,"unit":"","have":false},{"name":"white vinegar","plural":"white vinegar","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Melt the butter. Whisk 3 egg yolks with 2 tbsp of water over a bain-marie until they thicken.","timer":null},{"text":"Add the melted butter little by little, whisking, then the lemon juice. This is the hollandaise.","timer":null},{"text":"Toast the halved muffins and brown the bacon.","timer":{"label":"Pan","min":4}},{"text":"Poach the 4 eggs for 3 minutes in simmering water with vinegar.","timer":{"label":"Cooking","min":3}},{"text":"Build it: muffin, bacon, poached egg, then the sauce.","timer":null}],"variant":"The classic","change":""},{"title":"Eggs Royale","intro":"The royal version, with smoked salmon.","minutes":30,"calories":500,"difficulty":"Difficile","imageSearch":"eggs royale salmon","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"egg","plural":"eggs","qty":7,"unit":"","have":false},{"name":"english muffin","plural":"english muffins","qty":2,"unit":"","have":false},{"name":"smoked salmon","plural":"smoked salmon","qty":4,"unit":"slices","have":false},{"name":"butter","plural":"butter","qty":100,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":0.5,"unit":"","have":false},{"name":"white vinegar","plural":"white vinegar","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Make the hollandaise over a bain-marie with 3 yolks, the melted butter and the lemon.","timer":null},{"text":"Toast the halved muffins.","timer":null},{"text":"Poach the 4 eggs for 3 minutes in water with vinegar.","timer":{"label":"Cooking","min":3}},{"text":"Build it: muffin, salmon, poached egg, then the sauce.","timer":null}],"variant":"With salmon","change":"With smoked salmon instead of bacon."},{"title":"Eggs Florentine","intro":"The Florentine version, with spinach.","minutes":30,"calories":450,"difficulty":"Difficile","imageSearch":"eggs florentine spinach","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"egg","plural":"eggs","qty":7,"unit":"","have":false},{"name":"english muffin","plural":"english muffins","qty":2,"unit":"","have":false},{"name":"baby spinach","plural":"baby spinach","qty":200,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":100,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":0.5,"unit":"","have":false},{"name":"white vinegar","plural":"white vinegar","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Make the hollandaise over a bain-marie with 3 yolks, the melted butter and the lemon.","timer":null},{"text":"Wilt the spinach for 2 minutes in a pan.","timer":{"label":"Pan","min":2}},{"text":"Toast the muffins and poach the 4 eggs for 3 minutes.","timer":{"label":"Cooking","min":3}},{"text":"Build it: muffin, spinach, poached egg, then the sauce.","timer":null}],"variant":"Vegetarian","change":"With wilted spinach."}]$r$::jsonb, 'claude')
