insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:oeuf cocotte', 'Baked eggs', array['en:baked egg', 'en:egg en cocotte', 'en:shirred egg']::text[], 'dish', $r$[{"title":"Baked eggs with cream","intro":"Eggs baked in ramekins, with cream and chives.","minutes":20,"calories":200,"difficulty":"Facile","imageSearch":"baked eggs ramekin cream","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":8,"unit":"tbsp","have":false},{"name":"chive","plural":"chives","qty":null,"unit":"","have":false},{"name":"butter","plural":"butter","qty":10,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C. Butter 4 ramekins.","timer":null},{"text":"Put 1 tbsp of cream in the bottom, break in an egg, then add another 1 tbsp of cream.","timer":null},{"text":"Stand the ramekins in a dish with hot water halfway up the sides.","timer":null},{"text":"Bake for 10 minutes: the white should be set and the yolk runny.","timer":{"label":"Oven","min":10}},{"text":"Sprinkle with chives, salt and pepper.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Baked eggs with ham","intro":"Hearty baked eggs with ham and Emmental.","minutes":20,"calories":260,"difficulty":"Facile","imageSearch":"baked eggs ham cheese","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"cooked ham","plural":"cooked ham","qty":2,"unit":"slices","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":4,"unit":"tbsp","have":false},{"name":"grated emmental","plural":"grated emmental","qty":40,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Put the diced ham and the cream into 4 buttered ramekins.","timer":null},{"text":"Break an egg into each and sprinkle with Emmental.","timer":null},{"text":"Bake for 12 minutes in a bain-marie.","timer":{"label":"Oven","min":12}}],"kids":true,"variant":"With ham","change":"With ham and cheese."},{"title":"Baked eggs with mushrooms","intro":"Woodland-style baked eggs, with mushrooms.","minutes":25,"calories":220,"difficulty":"Facile","imageSearch":"baked eggs mushrooms","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":200,"unit":"g","have":false},{"name":"shallot","plural":"shallots","qty":1,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":4,"unit":"tbsp","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Fry the sliced mushrooms and the shallot for 5 minutes.","timer":{"label":"Pan","min":5}},{"text":"Divide them between 4 ramekins with the cream and break an egg into each.","timer":null},{"text":"Bake for 12 minutes in a bain-marie and sprinkle with parsley.","timer":{"label":"Oven","min":12}}],"kids":true,"variant":"With mushrooms","change":"With pan-fried mushrooms."}]$r$::jsonb, 'claude')
