insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:pain maison', 'Homemade bread', array['en:homemade bread', 'en:bread', 'en:no machine bread', 'en:white loaf']::text[], 'dish', $r$[{"title":"Homemade bread","intro":"A crusty loaf made by hand, with no machine, baked in a casserole dish.","minutes":210,"calories":250,"difficulty":"Moyen","imageSearch":"homemade bread loaf","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":500,"unit":"g","have":false},{"name":"fresh yeast","plural":"fresh yeast","qty":5,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":10,"unit":"g","have":false}],"steps":[{"text":"Dissolve the yeast in 35 cl of lukewarm water.","timer":null},{"text":"Mix with the flour and the salt, and knead for 10 minutes.","timer":{"label":"Kneading","min":10}},{"text":"Leave to rise for 2 hours under a tea towel.","timer":{"label":"Rising","min":120}},{"text":"Preheat the oven to 240 °C with a cast-iron casserole dish inside.","timer":null},{"text":"Shape a ball, put it in the hot dish and bake for 30 minutes with the lid on, then 15 minutes with the lid off.","timer":{"label":"Oven","min":45}}],"variant":"The classic","change":""},{"title":"No-knead bread","intro":"The simplest bread, made the day before.","minutes":60,"calories":250,"difficulty":"Facile","imageSearch":"no knead bread","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":500,"unit":"g","have":false},{"name":"fresh yeast","plural":"fresh yeast","qty":2,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":10,"unit":"g","have":false}],"steps":[{"text":"Mix the flour, the salt, the yeast and 38 cl of lukewarm water, without kneading.","timer":null},{"text":"Cover and leave to rise for 12 to 18 hours at room temperature.","timer":null},{"text":"Preheat the oven to 240 °C with a cast-iron casserole dish inside.","timer":null},{"text":"Pour the dough into the hot dish and bake for 30 minutes with the lid on, then 15 minutes with the lid off.","timer":{"label":"Oven","min":45}}],"variant":"No kneading","change":"The dough rises overnight and is not kneaded."},{"title":"Seeded wholemeal bread","intro":"A wholemeal loaf packed with seeds, for breakfast.","minutes":210,"calories":270,"difficulty":"Moyen","imageSearch":"whole wheat seeded bread","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"wholemeal flour","plural":"wholemeal flour","qty":300,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"fresh yeast","plural":"fresh yeast","qty":5,"unit":"g","have":false},{"name":"mixed seeds","plural":"mixed seeds","qty":80,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":10,"unit":"g","have":false}],"steps":[{"text":"Dissolve the yeast in 37 cl of lukewarm water.","timer":null},{"text":"Mix with the flours, the salt and the seeds, and knead for 10 minutes.","timer":{"label":"Kneading","min":10}},{"text":"Leave to rise for 2 hours.","timer":{"label":"Rising","min":120}},{"text":"Shape and put in a loaf tin. Leave to rise for 45 minutes.","timer":{"label":"Rising","min":45}},{"text":"Bake for 40 minutes at 220 °C.","timer":{"label":"Oven","min":40}}],"variant":"Wholemeal","change":"With wholemeal flour and seeds."}]$r$::jsonb, 'claude')
