insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:frittata', 'Frittata', array['en:italian omelette', 'en:spanish tortilla', 'en:tortilla']::text[], 'dish', $r$[{"title":"Vegetable frittata","intro":"The thick Italian omelette, filled with vegetables and finished in the oven.","minutes":30,"calories":280,"difficulty":"Facile","imageSearch":"vegetable frittata","veg":true,"oven":true,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"egg","plural":"eggs","qty":8,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"parmesan","plural":"parmesan","qty":40,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Fry the onion, the pepper and the diced courgette for 8 minutes in an ovenproof frying pan.","timer":{"label":"Pan","min":8}},{"text":"Beat the eggs with the parmesan, add salt and pepper, and pour over the vegetables.","timer":null},{"text":"Cook for 3 minutes on the hob, then bake for 12 minutes.","timer":{"label":"Oven","min":12}}],"kids":true,"variant":"The classic","change":""},{"title":"Spanish tortilla","intro":"The thick Spanish omelette with potatoes.","minutes":45,"calories":350,"difficulty":"Moyen","imageSearch":"spanish tortilla","veg":true,"oven":false,"cold":false,"missing":"","origin":"Spanish recipe","serves":4,"items":[{"name":"egg","plural":"eggs","qty":6,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":600,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":10,"unit":"cl","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the potatoes into thin slices and the onion into strips.","timer":null},{"text":"Cook them for 20 minutes over a low heat in the oil, without browning them.","timer":{"label":"Pan","min":20}},{"text":"Drain them and mix with the beaten, salted eggs.","timer":null},{"text":"Put back in the pan and cook for 5 minutes, then flip with a plate and cook for 3 minutes.","timer":{"label":"Pan","min":8}}],"kids":true,"variant":"Tortilla","change":"With potatoes and onion."},{"title":"Spinach and feta frittata","intro":"A green, melting frittata.","minutes":25,"calories":290,"difficulty":"Facile","imageSearch":"spinach feta frittata","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"egg","plural":"eggs","qty":8,"unit":"","have":false},{"name":"baby spinach","plural":"baby spinach","qty":200,"unit":"g","have":false},{"name":"feta","plural":"feta","qty":150,"unit":"g","have":false},{"name":"spring onion","plural":"spring onions","qty":2,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Wilt the spinach with the spring onion for 3 minutes.","timer":{"label":"Pan","min":3}},{"text":"Pour in the beaten eggs and the crumbled feta.","timer":null},{"text":"Cook for 3 minutes, then bake for 12 minutes.","timer":{"label":"Oven","min":12}}],"variant":"Spinach and feta","change":"With spinach and feta."}]$r$::jsonb, 'claude')
