insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:welsh', 'Welsh rarebit', array['en:welsh rarebit', 'en:welsh rabbit', 'en:cheese on toast']::text[], 'dish', $r$[{"title":"Welsh","intro":"The dish from the north of France: bread and ham covered in cheddar melted with beer, topped with an egg.","minutes":30,"calories":850,"difficulty":"Facile","imageSearch":"welsh rarebit","veg":false,"oven":true,"cold":false,"missing":"","origin":"Speciality of northern France","serves":4,"items":[{"name":"cheddar","plural":"cheddar","qty":500,"unit":"g","have":false},{"name":"lager","plural":"lager","qty":20,"unit":"cl","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tbsp","have":false},{"name":"country bread","plural":"country bread","qty":4,"unit":"slices","have":false},{"name":"cooked ham","plural":"cooked ham","qty":4,"unit":"slices","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to the grill setting.","timer":null},{"text":"Melt the cheddar pieces with the beer and the mustard over a low heat, stirring.","timer":null},{"text":"Put a slice of bread in each individual dish and add the ham.","timer":null},{"text":"Cover with melted cheddar and grill for 8 minutes.","timer":{"label":"Oven","min":8}},{"text":"Top each welsh with a fried egg.","timer":null}],"variant":"The classic","change":""},{"title":"Welsh without beer","intro":"A milder welsh, for the whole family.","minutes":30,"calories":800,"difficulty":"Facile","imageSearch":"cheddar toast melted cheese","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cheddar","plural":"cheddar","qty":500,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":15,"unit":"cl","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tsp","have":false},{"name":"country bread","plural":"country bread","qty":4,"unit":"slices","have":false},{"name":"cooked ham","plural":"cooked ham","qty":4,"unit":"slices","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false}],"steps":[{"text":"Melt the cheddar with the milk and the mustard over a low heat.","timer":null},{"text":"Put the bread and the ham in individual dishes.","timer":null},{"text":"Cover with cheddar and grill for 8 minutes.","timer":{"label":"Oven","min":8}},{"text":"Add a fried egg.","timer":null}],"kids":true,"variant":"Alcohol-free","change":"The beer is replaced by milk."},{"title":"Vegetarian welsh","intro":"A meat-free welsh, with pan-fried mushrooms.","minutes":30,"calories":760,"difficulty":"Facile","imageSearch":"vegetarian welsh rarebit mushrooms","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cheddar","plural":"cheddar","qty":500,"unit":"g","have":false},{"name":"lager","plural":"lager","qty":20,"unit":"cl","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tbsp","have":false},{"name":"country bread","plural":"country bread","qty":4,"unit":"slices","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":250,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false}],"steps":[{"text":"Fry the sliced mushrooms for 8 minutes.","timer":{"label":"Pan","min":8}},{"text":"Melt the cheddar with the beer and the mustard.","timer":null},{"text":"Put the bread and the mushrooms in dishes and cover with cheddar.","timer":null},{"text":"Grill for 8 minutes and add a fried egg.","timer":{"label":"Oven","min":8}}],"variant":"Vegetarian","change":"No ham, with mushrooms."}]$r$::jsonb, 'claude')
