insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:bibimbap', 'Bibimbap', array['en:korean rice bowl']::text[], 'dish', $r$[{"title":"Bibimbap","intro":"The Korean bowl: rice, marinated beef, stir-fried vegetables, a fried egg and chilli sauce.","minutes":45,"calories":580,"difficulty":"Moyen","imageSearch":"bibimbap","veg":false,"oven":false,"cold":false,"missing":"","origin":"Korean recipe","serves":4,"items":[{"name":"rice","plural":"rice","qty":300,"unit":"g","have":false},{"name":"minced beef","plural":"minced beef","qty":300,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"baby spinach","plural":"baby spinach","qty":150,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false},{"name":"korean chilli paste","plural":"korean chilli paste","qty":2,"unit":"tbsp","have":false},{"name":"sesame oil","plural":"sesame oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Fry the beef with 2 tbsp of soy sauce and 1 tbsp of sesame oil.","timer":{"label":"Pan","min":6}},{"text":"Stir-fry the carrots and courgette sticks separately, then the spinach.","timer":{"label":"Pan","min":8}},{"text":"Fry the eggs.","timer":{"label":"Pan","min":4}},{"text":"Put the rice in bowls, arrange the vegetables and the beef in sections, and top with the egg.","timer":null},{"text":"Serve with the chilli paste mixed with the rest of the soy sauce.","timer":null}],"variant":"The classic","change":""},{"title":"Tofu bibimbap","intro":"The vegetarian bibimbap, with crispy tofu.","minutes":40,"calories":500,"difficulty":"Moyen","imageSearch":"tofu bibimbap","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rice","plural":"rice","qty":300,"unit":"g","have":false},{"name":"firm tofu","plural":"firm tofu","qty":300,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"baby spinach","plural":"baby spinach","qty":150,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false},{"name":"korean chilli paste","plural":"korean chilli paste","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Brown the diced tofu with 2 tbsp of soy sauce.","timer":{"label":"Pan","min":8}},{"text":"Stir-fry the carrots, the courgette and the spinach.","timer":{"label":"Pan","min":8}},{"text":"Assemble the bowls with the rice, the vegetables, the tofu and a fried egg.","timer":null},{"text":"Serve with the chilli sauce.","timer":null}],"variant":"Vegetarian","change":"Golden tofu instead of beef."},{"title":"Chicken bibimbap","intro":"A milder bibimbap, with chicken.","minutes":45,"calories":540,"difficulty":"Moyen","imageSearch":"chicken bibimbap bowl","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rice","plural":"rice","qty":300,"unit":"g","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":1,"unit":"","have":false},{"name":"baby spinach","plural":"baby spinach","qty":150,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false},{"name":"honey","plural":"honey","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Brown the chicken strips with the soy sauce and the honey.","timer":{"label":"Pan","min":8}},{"text":"Stir-fry the carrots and the spinach, and cut the cucumber into sticks.","timer":null},{"text":"Assemble the bowls and add a fried egg.","timer":null}],"variant":"With chicken","change":"With chicken marinated in soy sauce."}]$r$::jsonb, 'claude')
