insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:gyoza', 'Gyoza', array['en:japanese dumpling', 'en:potsticker', 'en:dumpling', 'en:steamed dumpling']::text[], 'dish', $r$[{"title":"Pork gyoza","intro":"Japanese dumplings fried on the bottom and steamed on top, filled with pork and cabbage.","minutes":60,"calories":320,"difficulty":"Difficile","imageSearch":"pork gyoza dumplings","veg":false,"oven":false,"cold":false,"missing":"","origin":"Japanese recipe","serves":4,"items":[{"name":"gyoza wrapper","plural":"gyoza wrappers","qty":30,"unit":"","have":false},{"name":"minced pork","plural":"minced pork","qty":300,"unit":"g","have":false},{"name":"chinese cabbage","plural":"chinese cabbages","qty":0.25,"unit":"","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false},{"name":"sesame oil","plural":"sesame oil","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Chop the cabbage finely, salt it and squeeze out the water.","timer":null},{"text":"Mix it with the pork, the garlic, the ginger, 1 tbsp of soy sauce and the sesame oil.","timer":null},{"text":"Put a spoonful of filling on each wrapper, wet the edge and pleat to seal.","timer":null},{"text":"Brown the gyoza for 3 minutes in an oiled frying pan.","timer":{"label":"Pan","min":3}},{"text":"Pour in 10 cl of water, cover and leave for 5 minutes.","timer":{"label":"Steam","min":5}},{"text":"Serve with the rest of the soy sauce.","timer":null}],"makes":{"n":30,"one":"gyoza","many":"gyozas"},"variant":"The classic","change":""},{"title":"Vegetable gyoza","intro":"Vegetarian gyoza with cabbage, carrot and tofu.","minutes":60,"calories":250,"difficulty":"Difficile","imageSearch":"vegetable gyoza","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"gyoza wrapper","plural":"gyoza wrappers","qty":30,"unit":"","have":false},{"name":"firm tofu","plural":"firm tofu","qty":150,"unit":"g","have":false},{"name":"chinese cabbage","plural":"chinese cabbages","qty":0.25,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":1,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":100,"unit":"g","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Chop the cabbage, the carrot and the mushrooms and fry them for 5 minutes.","timer":{"label":"Pan","min":5}},{"text":"Mix with the mashed tofu, the ginger and 1 tbsp of soy sauce.","timer":null},{"text":"Fill and seal the wrappers.","timer":null},{"text":"Brown for 3 minutes, then add 10 cl of water, cover and leave for 5 minutes.","timer":{"label":"Steam","min":5}}],"makes":{"n":30,"one":"gyoza","many":"gyozas"},"variant":"Vegetarian","change":"Filled with vegetables and tofu."},{"title":"Prawn gyoza","intro":"Delicate gyoza with prawns and chives.","minutes":60,"calories":260,"difficulty":"Difficile","imageSearch":"shrimp gyoza","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"gyoza wrapper","plural":"gyoza wrappers","qty":30,"unit":"","have":false},{"name":"peeled prawn","plural":"peeled prawns","qty":300,"unit":"g","have":false},{"name":"chive","plural":"chives","qty":null,"unit":"","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false},{"name":"sesame oil","plural":"sesame oil","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Chop the prawns and mix them with the chives, the ginger, the oil and 1 tbsp of soy sauce.","timer":null},{"text":"Fill and seal the wrappers.","timer":null},{"text":"Brown for 3 minutes in an oiled frying pan.","timer":{"label":"Pan","min":3}},{"text":"Add 10 cl of water, cover and leave for 5 minutes.","timer":{"label":"Steam","min":5}}],"makes":{"n":30,"one":"gyoza","many":"gyozas"},"variant":"Prawn","change":"Filled with prawns."}]$r$::jsonb, 'claude')
