insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:maki', 'Maki', array['en:sushi', 'en:homemade sushi', 'en:california roll']::text[], 'dish', $r$[{"title":"Salmon maki","intro":"Rolls of vinegared rice and nori seaweed, with salmon and cucumber.","minutes":70,"calories":350,"difficulty":"Difficile","imageSearch":"salmon maki sushi","veg":false,"oven":false,"cold":true,"missing":"","origin":"Japanese recipe","serves":4,"items":[{"name":"sushi rice","plural":"sushi rice","qty":300,"unit":"g","have":false},{"name":"rice vinegar","plural":"rice vinegar","qty":5,"unit":"tbsp","have":false},{"name":"sugar","plural":"sugar","qty":1,"unit":"tbsp","have":false},{"name":"nori sheet","plural":"nori sheets","qty":5,"unit":"","have":false},{"name":"fresh salmon","plural":"fresh salmon","qty":250,"unit":"g","have":false},{"name":"cucumber","plural":"cucumbers","qty":1,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false}],"steps":[{"text":"Rinse the rice until the water runs clear, then cook it for 12 minutes with 36 cl of water, covered.","timer":{"label":"Cooking","min":12}},{"text":"Leave to rest for 10 minutes, then mix with the vinegar, the sugar and a pinch of salt. Leave to cool.","timer":null},{"text":"Cut the salmon and the cucumber into sticks.","timer":null},{"text":"Spread a thin layer of rice on a nori sheet and lay the salmon and cucumber along one edge.","timer":null},{"text":"Roll up tightly with a bamboo mat, then cut into 6 with a wet knife.","timer":null},{"text":"Serve with the soy sauce.","timer":null}],"makes":{"n":40,"one":"maki roll","many":"maki rolls"},"variant":"The classic","change":""},{"title":"California rolls","intro":"Inside-out rolls with avocado and crab sticks, rolled in sesame seeds.","minutes":70,"calories":380,"difficulty":"Difficile","imageSearch":"california roll","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"sushi rice","plural":"sushi rice","qty":300,"unit":"g","have":false},{"name":"rice vinegar","plural":"rice vinegar","qty":5,"unit":"tbsp","have":false},{"name":"sugar","plural":"sugar","qty":1,"unit":"tbsp","have":false},{"name":"nori sheet","plural":"nori sheets","qty":4,"unit":"","have":false},{"name":"avocado","plural":"avocados","qty":2,"unit":"","have":false},{"name":"crab stick","plural":"crab sticks","qty":8,"unit":"","have":false},{"name":"sesame seed","plural":"sesame seeds","qty":3,"unit":"tbsp","have":false}],"steps":[{"text":"Make the vinegared rice and leave it to cool.","timer":{"label":"Cooking","min":12}},{"text":"Spread the rice on a nori sheet, sprinkle with sesame seeds and flip it over onto cling film.","timer":null},{"text":"Lay the avocado and the crab sticks, cut into sticks, on the nori.","timer":null},{"text":"Roll up tightly and cut into 8.","timer":null}],"makes":{"n":32,"one":"maki roll","many":"maki rolls"},"variant":"California","change":"Rice on the outside, with avocado and crab sticks."},{"title":"Vegetarian maki","intro":"All-vegetable maki, fresh and colourful.","minutes":60,"calories":280,"difficulty":"Difficile","imageSearch":"vegetable maki","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"sushi rice","plural":"sushi rice","qty":300,"unit":"g","have":false},{"name":"rice vinegar","plural":"rice vinegar","qty":5,"unit":"tbsp","have":false},{"name":"sugar","plural":"sugar","qty":1,"unit":"tbsp","have":false},{"name":"nori sheet","plural":"nori sheets","qty":5,"unit":"","have":false},{"name":"avocado","plural":"avocados","qty":1,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":1,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":1,"unit":"","have":false}],"steps":[{"text":"Make the vinegared rice and leave it to cool.","timer":{"label":"Cooking","min":12}},{"text":"Cut the avocado, the cucumber and the carrot into sticks.","timer":null},{"text":"Spread the rice on the nori, lay the vegetables along one edge and roll up tightly.","timer":null},{"text":"Cut into 6 and serve with soy sauce.","timer":null}],"makes":{"n":40,"one":"maki roll","many":"maki rolls"},"variant":"Vegetarian","change":"With avocado, cucumber and carrot."}]$r$::jsonb, 'claude')
