insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:pho', 'Pho', array['en:pho soup', 'en:beef pho', 'en:vietnamese noodle soup']::text[], 'dish', $r$[{"title":"Beef pho","intro":"The Vietnamese soup with a star anise broth, rice noodles and beef.","minutes":60,"calories":420,"difficulty":"Moyen","imageSearch":"pho bo beef noodle soup","veg":false,"oven":false,"cold":false,"missing":"","origin":"Vietnamese recipe","serves":4,"items":[{"name":"rice noodle","plural":"rice noodles","qty":250,"unit":"g","have":false},{"name":"thinly sliced beef","plural":"thinly sliced beef","qty":300,"unit":"g","have":false},{"name":"beef stock cube","plural":"beef stock cubes","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"fresh ginger","plural":"fresh ginger","qty":1,"unit":"","have":false},{"name":"star anise","plural":"star anise","qty":2,"unit":"","have":false},{"name":"fish sauce","plural":"fish sauce","qty":3,"unit":"tbsp","have":false},{"name":"bean sprout","plural":"bean sprouts","qty":150,"unit":"g","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false},{"name":"lime","plural":"limes","qty":1,"unit":"","have":false}],"steps":[{"text":"Dry-fry the halved onion and ginger in a pan until charred.","timer":{"label":"Pan","min":5}},{"text":"Put them in 1.5 litres of water with the stock cubes, the star anise and the fish sauce, and simmer for 40 minutes.","timer":{"label":"Simmer","min":40}},{"text":"Cook the noodles according to the packet.","timer":null},{"text":"Slice the raw beef very thinly.","timer":null},{"text":"Put the noodles and the beef in bowls and pour the boiling broth over them: it cooks the meat.","timer":null},{"text":"Serve with the bean sprouts, the coriander and the lime.","timer":null}],"variant":"The classic","change":""},{"title":"Chicken pho","intro":"The chicken version, which is milder.","minutes":50,"calories":380,"difficulty":"Moyen","imageSearch":"pho ga chicken noodle soup","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rice noodle","plural":"rice noodles","qty":250,"unit":"g","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"chicken stock cube","plural":"chicken stock cubes","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"fresh ginger","plural":"fresh ginger","qty":1,"unit":"","have":false},{"name":"star anise","plural":"star anise","qty":2,"unit":"","have":false},{"name":"fish sauce","plural":"fish sauce","qty":2,"unit":"tbsp","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false}],"steps":[{"text":"Dry-fry the onion and ginger until charred.","timer":{"label":"Pan","min":5}},{"text":"Put them in 1.5 litres of water with the stock cubes, the star anise and the fish sauce.","timer":null},{"text":"Poach the chicken for 20 minutes in this broth, then shred it.","timer":{"label":"Cooking","min":20}},{"text":"Cook the noodles and divide them between the bowls with the chicken.","timer":null},{"text":"Pour over the hot broth and sprinkle with coriander.","timer":null}],"variant":"With chicken","change":"With chicken poached in the broth."},{"title":"Vegetarian pho","intro":"A fragrant meat-free pho, with tofu.","minutes":45,"calories":330,"difficulty":"Moyen","imageSearch":"vegetarian pho","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rice noodle","plural":"rice noodles","qty":250,"unit":"g","have":false},{"name":"firm tofu","plural":"firm tofu","qty":200,"unit":"g","have":false},{"name":"shiitake mushroom","plural":"shiitake mushrooms","qty":150,"unit":"g","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":2,"unit":"","have":false},{"name":"fresh ginger","plural":"fresh ginger","qty":1,"unit":"","have":false},{"name":"star anise","plural":"star anise","qty":2,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false}],"steps":[{"text":"Dry-fry the ginger until charred, then put it in 1.5 litres of water with the stock cubes, the star anise and the soy sauce.","timer":null},{"text":"Simmer for 25 minutes with the mushrooms.","timer":{"label":"Simmer","min":25}},{"text":"Brown the diced tofu.","timer":{"label":"Pan","min":6}},{"text":"Cook the noodles, divide them between the bowls with the tofu and pour over the broth.","timer":null}],"variant":"Vegetarian","change":"A vegetable broth with tofu and mushrooms."}]$r$::jsonb, 'claude')
