insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:poulet satay', 'Chicken satay', array['en:chicken satay', 'en:satay', 'en:satay skewer', 'en:peanut chicken']::text[], 'dish', $r$[{"title":"Chicken satay skewers","intro":"Curry-marinated chicken skewers with a peanut sauce.","minutes":45,"calories":480,"difficulty":"Facile","imageSearch":"chicken satay skewers","veg":false,"oven":false,"cold":false,"missing":"","origin":"Indonesian recipe","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"peanut butter","plural":"peanut butter","qty":4,"unit":"tbsp","have":false},{"name":"coconut milk","plural":"coconut milk","qty":20,"unit":"cl","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false},{"name":"curry powder","plural":"curry powder","qty":2,"unit":"tsp","have":false},{"name":"lime","plural":"limes","qty":1,"unit":"","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Cut the chicken into strips and marinate for 20 minutes with 10 cl of coconut milk, the curry powder and 1 tbsp of soy sauce.","timer":{"label":"Rest","min":20}},{"text":"Thread the chicken onto skewers and grill for 10 minutes, turning them.","timer":{"label":"Pan","min":10}},{"text":"Heat the peanut butter with the rest of the coconut milk, the soy sauce and the lime juice.","timer":null},{"text":"Serve the skewers with the sauce and rice.","timer":null}],"makes":{"n":8,"one":"skewer","many":"skewers"},"variant":"The classic","change":""},{"title":"Chicken satay in sauce","intro":"A creamy peanut chicken, with rice.","minutes":30,"calories":520,"difficulty":"Facile","imageSearch":"peanut chicken curry","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"peanut butter","plural":"peanut butter","qty":4,"unit":"tbsp","have":false},{"name":"coconut milk","plural":"coconut milk","qty":40,"unit":"cl","have":false},{"name":"soy sauce","plural":"soy sauce","qty":2,"unit":"tbsp","have":false},{"name":"curry powder","plural":"curry powder","qty":2,"unit":"tsp","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Brown the diced chicken with the onion and the curry powder.","timer":{"label":"Pan","min":6}},{"text":"Add the coconut milk, the peanut butter and the soy sauce.","timer":null},{"text":"Leave to simmer for 10 minutes.","timer":{"label":"Cooking","min":10}}],"variant":"In a sauce","change":"The chicken simmers in the peanut sauce."},{"title":"Tofu satay","intro":"Tofu skewers with peanut sauce.","minutes":35,"calories":430,"difficulty":"Facile","imageSearch":"tofu satay","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"firm tofu","plural":"firm tofu","qty":400,"unit":"g","have":false},{"name":"peanut butter","plural":"peanut butter","qty":4,"unit":"tbsp","have":false},{"name":"coconut milk","plural":"coconut milk","qty":20,"unit":"cl","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false},{"name":"curry powder","plural":"curry powder","qty":1,"unit":"tsp","have":false},{"name":"lime","plural":"limes","qty":1,"unit":"","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Cut the tofu into cubes and marinate for 15 minutes with the soy sauce and the curry powder.","timer":{"label":"Rest","min":15}},{"text":"Brown it for 8 minutes in a pan.","timer":{"label":"Pan","min":8}},{"text":"Heat the peanut butter with the coconut milk and the lime juice.","timer":null},{"text":"Serve the tofu covered in sauce, with rice.","timer":null}],"variant":"Vegetarian","change":"Tofu instead of chicken."}]$r$::jsonb, 'claude')
