insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:chop suey', 'Chop suey', array['en:chicken chop suey', 'en:chinese stir fried vegetable', 'en:chinese chicken and vegetable']::text[], 'dish', $r$[{"title":"Chicken chop suey","intro":"The Chinese stir-fry of chicken and crunchy vegetables, with bean sprouts and soy sauce.","minutes":30,"calories":380,"difficulty":"Facile","imageSearch":"chicken chop suey","veg":false,"oven":false,"cold":false,"missing":"","origin":"Chinese-inspired","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":3,"unit":"","have":false},{"name":"bean sprout","plural":"bean sprouts","qty":200,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"chinese cabbage","plural":"chinese cabbages","qty":0.25,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":150,"unit":"g","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false},{"name":"cornflour","plural":"cornflour","qty":1,"unit":"tbsp","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Cut the chicken into strips and brown for 5 minutes over a high heat, then remove it.","timer":{"label":"Pan","min":5}},{"text":"Stir-fry the carrot sticks, the cabbage and the sliced mushrooms for 5 minutes.","timer":{"label":"Pan","min":5}},{"text":"Add the bean sprouts and the chicken.","timer":null},{"text":"Mix the cornflour with the soy sauce and 10 cl of water, pour it in and stir until it thickens.","timer":null}],"variant":"The classic","change":""},{"title":"Prawn chop suey","intro":"A light chop suey with prawns.","minutes":25,"calories":320,"difficulty":"Facile","imageSearch":"shrimp chop suey","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"peeled prawn","plural":"peeled prawns","qty":400,"unit":"g","have":false},{"name":"bean sprout","plural":"bean sprouts","qty":200,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false},{"name":"cornflour","plural":"cornflour","qty":1,"unit":"tbsp","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Stir-fry the carrots and the pepper strips for 5 minutes.","timer":{"label":"Pan","min":5}},{"text":"Add the prawns and the bean sprouts, and cook for 3 minutes.","timer":{"label":"Pan","min":3}},{"text":"Add the soy sauce mixed with the cornflour and 10 cl of water, and stir until it thickens.","timer":null}],"variant":"Prawn","change":"Prawns instead of chicken."},{"title":"Vegetarian chop suey","intro":"A stir-fry of crunchy vegetables with tofu.","minutes":25,"calories":300,"difficulty":"Facile","imageSearch":"vegetable chop suey tofu","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"firm tofu","plural":"firm tofu","qty":300,"unit":"g","have":false},{"name":"bean sprout","plural":"bean sprouts","qty":200,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"broccoli","plural":"broccoli","qty":1,"unit":"","have":false},{"name":"chinese cabbage","plural":"chinese cabbages","qty":0.25,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false},{"name":"cornflour","plural":"cornflour","qty":1,"unit":"tbsp","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Brown the diced tofu and remove it.","timer":{"label":"Pan","min":6}},{"text":"Stir-fry the carrots, the broccoli and the cabbage for 5 minutes.","timer":{"label":"Pan","min":5}},{"text":"Add the bean sprouts, the tofu and the soy sauce thickened with the cornflour.","timer":null}],"variant":"Vegetarian","change":"With tofu and more vegetables."}]$r$::jsonb, 'claude')
