insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:biryani', 'Biryani', array['en:biriyani', 'en:chicken biryani', 'en:indian rice']::text[], 'dish', $r$[{"title":"Chicken biryani","intro":"The spiced Indian rice dish cooked with chicken marinated in yoghurt.","minutes":75,"calories":560,"difficulty":"Moyen","imageSearch":"chicken biryani","veg":false,"oven":false,"cold":false,"missing":"","origin":"Indian recipe","serves":4,"items":[{"name":"basmati rice","plural":"basmati rice","qty":300,"unit":"g","have":false},{"name":"chicken thigh","plural":"chicken thighs","qty":4,"unit":"","have":false},{"name":"plain yoghurt","plural":"plain yoghurts","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"garam masala","plural":"garam masala","qty":2,"unit":"tsp","have":false},{"name":"turmeric","plural":"turmeric","qty":1,"unit":"tsp","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the chicken into pieces and marinate for 30 minutes with the yoghurt and the spices.","timer":{"label":"Rest","min":30}},{"text":"Brown the sliced onions in a casserole dish, then take out half of them.","timer":{"label":"Cooking","min":10}},{"text":"Add the chicken and its marinade and cook for 10 minutes.","timer":{"label":"Cooking","min":10}},{"text":"Cover with the rinsed rice and 55 cl of water, without stirring.","timer":null},{"text":"Cover and cook for 20 minutes over a low heat.","timer":{"label":"Cooking","min":20}},{"text":"Sprinkle with the reserved onions and coriander.","timer":null}],"variant":"The classic","change":""},{"title":"Vegetable biryani","intro":"A fragrant vegetarian biryani.","minutes":60,"calories":460,"difficulty":"Moyen","imageSearch":"vegetable biryani","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"basmati rice","plural":"basmati rice","qty":300,"unit":"g","have":false},{"name":"cauliflower","plural":"cauliflowers","qty":0.5,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"frozen pea","plural":"frozen peas","qty":100,"unit":"g","have":false},{"name":"chickpea","plural":"chickpeas","qty":250,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"garam masala","plural":"garam masala","qty":2,"unit":"tsp","have":false},{"name":"plain yoghurt","plural":"plain yoghurts","qty":1,"unit":"","have":false}],"steps":[{"text":"Brown the onions in a casserole dish.","timer":{"label":"Cooking","min":10}},{"text":"Add the carrots, the cauliflower, the spices and the yoghurt, and cook for 10 minutes.","timer":{"label":"Cooking","min":10}},{"text":"Add the chickpeas and the peas, then the rinsed rice and 55 cl of water.","timer":null},{"text":"Cover and cook for 20 minutes over a low heat.","timer":{"label":"Cooking","min":20}}],"variant":"Vegetarian","change":"With vegetables and chickpeas."},{"title":"Lamb biryani","intro":"The special-occasion biryani, with lamb.","minutes":120,"calories":620,"difficulty":"Difficile","imageSearch":"lamb biryani","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"basmati rice","plural":"basmati rice","qty":300,"unit":"g","have":false},{"name":"lamb shoulder","plural":"lamb shoulders","qty":700,"unit":"g","have":false},{"name":"plain yoghurt","plural":"plain yoghurts","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"garam masala","plural":"garam masala","qty":2,"unit":"tsp","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false}],"steps":[{"text":"Cut the lamb into cubes and marinate for 30 minutes with the yoghurt and the spices.","timer":{"label":"Rest","min":30}},{"text":"Brown the onions, add the lamb and the garlic, and leave to simmer for 50 minutes with 20 cl of water.","timer":{"label":"Cooking","min":50}},{"text":"Cover with the rinsed rice and 55 cl of water.","timer":null},{"text":"Cook for 20 minutes over a low heat, covered.","timer":{"label":"Cooking","min":20}}],"variant":"With lamb","change":"With slow-cooked lamb."}]$r$::jsonb, 'claude')
