insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:naan', 'Naan', array['en:cheese naan', 'en:indian bread', 'en:naan bread']::text[], 'dish', $r$[{"title":"Plain naan","intro":"Soft Indian breads cooked in a frying pan, to serve with a curry.","minutes":90,"calories":250,"difficulty":"Facile","imageSearch":"naan bread","veg":true,"oven":false,"cold":false,"missing":"","origin":"Indian recipe","serves":4,"items":[{"name":"flour","plural":"flour","qty":400,"unit":"g","have":false},{"name":"plain yoghurt","plural":"plain yoghurts","qty":1,"unit":"","have":false},{"name":"fresh yeast","plural":"fresh yeast","qty":7,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":10,"unit":"cl","have":false},{"name":"melted butter","plural":"melted butter","qty":30,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Dissolve the yeast in the lukewarm milk.","timer":null},{"text":"Mix with the flour, the yoghurt, a pinch of salt and 5 cl of water, and knead for 5 minutes.","timer":null},{"text":"Leave to rise for 1 hour.","timer":{"label":"Rising","min":60}},{"text":"Divide into 8 and roll each ball into an oval.","timer":null},{"text":"Cook for 2 minutes on each side in a very hot frying pan.","timer":{"label":"Pan","min":4}},{"text":"Brush with melted butter.","timer":null}],"kids":true,"makes":{"n":8,"one":"naan","many":"naans"},"variant":"The classic","change":""},{"title":"Cheese naan","intro":"Naans stuffed with cheese, ultra gooey.","minutes":90,"calories":340,"difficulty":"Moyen","imageSearch":"cheese naan","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":400,"unit":"g","have":false},{"name":"plain yoghurt","plural":"plain yoghurts","qty":1,"unit":"","have":false},{"name":"fresh yeast","plural":"fresh yeast","qty":7,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":10,"unit":"cl","have":false},{"name":"cheese portion","plural":"cheese portions","qty":8,"unit":"","have":false},{"name":"melted butter","plural":"melted butter","qty":30,"unit":"g","have":false}],"steps":[{"text":"Make the dough as for plain naans and leave to rise for 1 hour.","timer":{"label":"Rising","min":60}},{"text":"Roll out 8 discs and put a cheese portion in the middle of each.","timer":null},{"text":"Fold over to close and flatten gently.","timer":null},{"text":"Cook for 3 minutes on each side in a frying pan.","timer":{"label":"Pan","min":6}},{"text":"Brush with butter.","timer":null}],"kids":true,"makes":{"n":8,"one":"naan","many":"naans"},"variant":"Cheese","change":"Stuffed with melted cheese."},{"title":"Garlic naan","intro":"Naans flavoured with garlic and herbs.","minutes":90,"calories":260,"difficulty":"Facile","imageSearch":"garlic naan","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":400,"unit":"g","have":false},{"name":"plain yoghurt","plural":"plain yoghurts","qty":1,"unit":"","have":false},{"name":"fresh yeast","plural":"fresh yeast","qty":7,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":10,"unit":"cl","have":false},{"name":"melted butter","plural":"melted butter","qty":40,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false}],"steps":[{"text":"Make the dough and leave to rise for 1 hour.","timer":{"label":"Rising","min":60}},{"text":"Roll out 8 naans.","timer":null},{"text":"Cook them for 2 minutes on each side.","timer":{"label":"Pan","min":4}},{"text":"Brush with melted butter mixed with the crushed garlic and the coriander.","timer":null}],"kids":true,"makes":{"n":8,"one":"naan","many":"naans"},"variant":"Garlic","change":"Brushed with garlic and coriander butter."}]$r$::jsonb, 'claude')
