insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:chana masala', 'Chana masala', array['en:chickpea curry', 'en:chana', 'en:curried chickpea']::text[], 'dish', $r$[{"title":"Chickpea curry","intro":"Chickpeas simmered in a tomato sauce with Indian spices.","minutes":30,"calories":380,"difficulty":"Facile","imageSearch":"chana masala","veg":true,"oven":false,"cold":false,"missing":"","origin":"Indian-inspired","serves":4,"items":[{"name":"chickpea","plural":"chickpeas","qty":800,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"garam masala","plural":"garam masala","qty":2,"unit":"tsp","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"basmati rice","plural":"basmati rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Fry the onions, the garlic, the ginger and the spices.","timer":null},{"text":"Add the tomatoes and leave to simmer for 10 minutes.","timer":{"label":"Cooking","min":10}},{"text":"Add the drained chickpeas and leave for 10 minutes.","timer":{"label":"Cooking","min":10}}],"variant":"The classic","change":""},{"title":"Coconut chickpea curry","intro":"A creamy chickpea curry, mild enough for kids.","minutes":30,"calories":450,"difficulty":"Facile","imageSearch":"coconut chickpea curry","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chickpea","plural":"chickpeas","qty":800,"unit":"g","have":false},{"name":"coconut milk","plural":"coconut milk","qty":40,"unit":"cl","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":200,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"curry powder","plural":"curry powder","qty":2,"unit":"tsp","have":false},{"name":"baby spinach","plural":"baby spinach","qty":100,"unit":"g","have":false},{"name":"basmati rice","plural":"basmati rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Fry the onion with the curry powder.","timer":null},{"text":"Add the tomatoes, the coconut milk and the chickpeas, and leave to simmer for 15 minutes.","timer":{"label":"Cooking","min":15}},{"text":"Add the spinach 2 minutes before the end.","timer":null}],"kids":true,"variant":"Coconut","change":"With coconut milk for a milder sauce."},{"title":"Chickpea and sweet potato curry","intro":"A hearty, filling curry with sweet potato.","minutes":40,"calories":430,"difficulty":"Facile","imageSearch":"chickpea sweet potato curry","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chickpea","plural":"chickpeas","qty":400,"unit":"g","have":false},{"name":"sweet potato","plural":"sweet potatoes","qty":2,"unit":"","have":false},{"name":"coconut milk","plural":"coconut milk","qty":40,"unit":"cl","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"curry powder","plural":"curry powder","qty":2,"unit":"tsp","have":false},{"name":"basmati rice","plural":"basmati rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Fry the onion with the curry powder.","timer":null},{"text":"Add the diced sweet potato and the coconut milk.","timer":null},{"text":"Leave to simmer for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Add the chickpeas and leave for 5 minutes. Serve with the rice.","timer":{"label":"Cooking","min":5}}],"variant":"Sweet potato","change":"With diced sweet potato."}]$r$::jsonb, 'claude')
