insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:bulgogi', 'Bulgogi', array['en:beef bulgogi', 'en:korean beef']::text[], 'dish', $r$[{"title":"Beef bulgogi","intro":"Sweet and salty marinated Korean beef, seared and served with rice.","minutes":40,"calories":480,"difficulty":"Facile","imageSearch":"beef bulgogi","veg":false,"oven":false,"cold":false,"missing":"","origin":"Korean recipe","serves":4,"items":[{"name":"thinly sliced beef","plural":"thinly sliced beef","qty":500,"unit":"g","have":false},{"name":"soy sauce","plural":"soy sauce","qty":5,"unit":"tbsp","have":false},{"name":"brown sugar","plural":"brown sugar","qty":2,"unit":"tbsp","have":false},{"name":"pear","plural":"pears","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"sesame oil","plural":"sesame oil","qty":1,"unit":"tbsp","have":false},{"name":"spring onion","plural":"spring onions","qty":3,"unit":"","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Grate the pear and mix it with the soy sauce, the sugar, the garlic and the sesame oil.","timer":null},{"text":"Cut the beef into thin slices and marinate for 20 minutes.","timer":{"label":"Rest","min":20}},{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Sear the beef for 3 minutes over a very high heat.","timer":{"label":"Pan","min":3}},{"text":"Sprinkle with spring onion and serve with the rice.","timer":null}],"variant":"The classic","change":""},{"title":"Chicken bulgogi","intro":"The bulgogi marinade on chicken.","minutes":40,"calories":450,"difficulty":"Facile","imageSearch":"chicken bulgogi","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"boneless chicken thigh","plural":"boneless chicken thighs","qty":6,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":5,"unit":"tbsp","have":false},{"name":"brown sugar","plural":"brown sugar","qty":2,"unit":"tbsp","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"sesame oil","plural":"sesame oil","qty":1,"unit":"tbsp","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Mix the soy sauce, the sugar, the garlic, the ginger and the oil.","timer":null},{"text":"Cut the chicken into strips and marinate for 20 minutes.","timer":{"label":"Rest","min":20}},{"text":"Brown it for 8 minutes in a pan.","timer":{"label":"Pan","min":8}},{"text":"Serve with rice.","timer":null}],"variant":"With chicken","change":"With chicken thighs."},{"title":"Bulgogi bowl","intro":"A complete Korean bowl with bulgogi beef.","minutes":40,"calories":560,"difficulty":"Facile","imageSearch":"bulgogi rice bowl","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"thinly sliced beef","plural":"thinly sliced beef","qty":400,"unit":"g","have":false},{"name":"soy sauce","plural":"soy sauce","qty":5,"unit":"tbsp","have":false},{"name":"brown sugar","plural":"brown sugar","qty":2,"unit":"tbsp","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":1,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Marinate the sliced beef with the soy sauce, the sugar and the garlic for 20 minutes.","timer":{"label":"Rest","min":20}},{"text":"Cook the rice, grate the carrot and slice the cucumber.","timer":{"label":"Cooking","min":12}},{"text":"Sear the beef for 3 minutes and fry the eggs.","timer":{"label":"Pan","min":3}},{"text":"Assemble the bowls: rice, beef, vegetables and egg.","timer":null}],"variant":"Bowl","change":"Served in a bowl with crunchy vegetables and an egg."}]$r$::jsonb, 'claude')
