insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:raclette', 'Raclette', array['en:homemade raclette', 'en:raclette dinner']::text[], 'dish', $r$[{"title":"Raclette","intro":"Raclette cheese melted over potatoes, with cured meats and gherkins.","minutes":40,"calories":850,"difficulty":"Facile","imageSearch":"raclette dinner","veg":false,"oven":false,"cold":false,"missing":"","origin":"Savoyard speciality","serves":4,"items":[{"name":"raclette cheese","plural":"raclette cheese","qty":800,"unit":"g","have":false},{"name":"potato","plural":"potatoes","qty":1200,"unit":"g","have":false},{"name":"cured ham","plural":"cured ham","qty":8,"unit":"slices","have":false},{"name":"rosette sausage","plural":"rosette sausage","qty":150,"unit":"g","have":false},{"name":"cooked ham","plural":"cooked ham","qty":4,"unit":"slices","have":false},{"name":"gherkin","plural":"gherkins","qty":16,"unit":"","have":false},{"name":"pickled onion","plural":"pickled onions","qty":8,"unit":"","have":false}],"steps":[{"text":"Boil the potatoes in their skins for 25 minutes in salted water.","timer":{"label":"Cooking","min":25}},{"text":"Keep them warm in a tea towel.","timer":null},{"text":"Put the cured meats, the gherkins and the pickled onions on the table.","timer":null},{"text":"Everyone melts their own cheese in the raclette machine and pours it over their potatoes.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Oven-baked raclette","intro":"Raclette with no machine, baked in the oven in one dish.","minutes":45,"calories":800,"difficulty":"Facile","imageSearch":"baked raclette potatoes","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"raclette cheese","plural":"raclette cheese","qty":600,"unit":"g","have":false},{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"cured ham","plural":"cured ham","qty":8,"unit":"slices","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"gherkin","plural":"gherkins","qty":12,"unit":"","have":false}],"steps":[{"text":"Boil the potatoes for 20 minutes, then halve them.","timer":{"label":"Cooking","min":20}},{"text":"Preheat the oven to 220 °C.","timer":null},{"text":"Arrange them in a dish with the sliced onion and cover with slices of cheese.","timer":null},{"text":"Bake for 10 minutes, until the cheese is melting.","timer":{"label":"Oven","min":10}},{"text":"Serve with the cured ham and the gherkins.","timer":null}],"kids":true,"variant":"No machine","change":"The cheese melts in the oven, right on the potatoes."},{"title":"Vegetarian raclette","intro":"A meat-free raclette, with roasted vegetables.","minutes":45,"calories":700,"difficulty":"Facile","imageSearch":"vegetarian raclette vegetables","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"raclette cheese","plural":"raclette cheese","qty":700,"unit":"g","have":false},{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":250,"unit":"g","have":false},{"name":"red pepper","plural":"red peppers","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"gherkin","plural":"gherkins","qty":12,"unit":"","have":false}],"steps":[{"text":"Boil the potatoes for 25 minutes.","timer":{"label":"Cooking","min":25}},{"text":"Cut the vegetables into pieces and roast them for 15 minutes in a pan or on the machine's grill.","timer":{"label":"Pan","min":15}},{"text":"Put everything on the table with the gherkins.","timer":null},{"text":"Everyone melts their cheese over their potatoes and vegetables.","timer":null}],"variant":"Vegetarian","change":"Grilled vegetables instead of cured meats."}]$r$::jsonb, 'claude')
