insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:fondue savoyarde', 'Cheese fondue', array['en:cheese fondue', 'en:fondue', 'en:savoyard fondue']::text[], 'dish', $r$[{"title":"Savoyard cheese fondue","intro":"Three cheeses melted in white wine, for dipping cubes of bread.","minutes":30,"calories":820,"difficulty":"Moyen","imageSearch":"cheese fondue","veg":true,"oven":false,"cold":false,"missing":"","origin":"Savoyard speciality","serves":4,"items":[{"name":"grated comté","plural":"grated comté","qty":300,"unit":"g","have":false},{"name":"beaufort","plural":"beaufort","qty":300,"unit":"g","have":false},{"name":"grated emmental","plural":"grated emmental","qty":200,"unit":"g","have":false},{"name":"dry white wine","plural":"dry white wine","qty":40,"unit":"cl","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"cornflour","plural":"cornflour","qty":1,"unit":"tbsp","have":false},{"name":"country bread","plural":"country bread","qty":1,"unit":"","have":false}],"steps":[{"text":"Cut the bread into cubes, the day before if possible.","timer":null},{"text":"Rub the fondue pot with the garlic.","timer":null},{"text":"Heat the wine in the pot, then add the cheeses little by little, stirring in a figure of eight.","timer":null},{"text":"Mix the cornflour with a little wine and add it to thicken.","timer":null},{"text":"Put the pot on the burner and dip the bread with the forks.","timer":null}],"variant":"The classic","change":""},{"title":"Alcohol-free cheese fondue","intro":"A fondue for the whole family, with no wine.","minutes":30,"calories":780,"difficulty":"Moyen","imageSearch":"family cheese fondue","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"grated comté","plural":"grated comté","qty":300,"unit":"g","have":false},{"name":"grated emmental","plural":"grated emmental","qty":300,"unit":"g","have":false},{"name":"vegetable stock","plural":"vegetable stock","qty":1,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"cornflour","plural":"cornflour","qty":1,"unit":"tbsp","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"country bread","plural":"country bread","qty":1,"unit":"","have":false}],"steps":[{"text":"Make 35 cl of stock and add the lemon juice.","timer":null},{"text":"Rub the fondue pot with garlic and heat the stock in it.","timer":null},{"text":"Add the cheeses little by little, stirring, then the cornflour mixed with a little water.","timer":null},{"text":"Serve with the cubed bread.","timer":null}],"kids":true,"variant":"No wine","change":"The wine is replaced by stock and lemon juice."},{"title":"Mushroom cheese fondue","intro":"A woodland fondue with mushrooms.","minutes":35,"calories":840,"difficulty":"Moyen","imageSearch":"mushroom cheese fondue","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"grated comté","plural":"grated comté","qty":300,"unit":"g","have":false},{"name":"beaufort","plural":"beaufort","qty":300,"unit":"g","have":false},{"name":"dry white wine","plural":"dry white wine","qty":40,"unit":"cl","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":250,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"cornflour","plural":"cornflour","qty":1,"unit":"tbsp","have":false},{"name":"country bread","plural":"country bread","qty":1,"unit":"","have":false}],"steps":[{"text":"Fry the sliced mushrooms for 8 minutes and chop them roughly.","timer":{"label":"Pan","min":8}},{"text":"Heat the wine in the pot rubbed with garlic.","timer":null},{"text":"Add the cheeses little by little, then the cornflour mixed with a little water.","timer":null},{"text":"Add the mushrooms and serve with the bread.","timer":null}],"variant":"Mushroom","change":"With ceps or pan-fried mushrooms."}]$r$::jsonb, 'claude')
on conflict (key) do update set query = excluded.query, aliases = excluded.aliases, kind = excluded.kind, recipes = excluded.recipes, source = 'claude', updated_at = now();
insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:croziflette', 'Croziflette', array['en:crozet', 'en:crozet gratin', 'en:savoyard crozet']::text[], 'dish', $r$[{"title":"Croziflette","intro":"Like a tartiflette, but with crozets, the small square pasta from Savoie.","minutes":50,"calories":780,"difficulty":"Facile","imageSearch":"croziflette crozets reblochon","veg":false,"oven":true,"cold":false,"missing":"","origin":"Savoyard speciality","serves":4,"items":[{"name":"crozets","plural":"crozets","qty":400,"unit":"g","have":false},{"name":"reblochon","plural":"reblochons","qty":1,"unit":"","have":false},{"name":"bacon lardon","plural":"bacon lardons","qty":200,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"white wine","plural":"white wine","qty":10,"unit":"cl","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Cook the crozets for 15 minutes in salted water.","timer":{"label":"Cooking","min":15}},{"text":"Brown the bacon and the sliced onions, then deglaze with the white wine.","timer":{"label":"Pan","min":8}},{"text":"Mix the crozets, the bacon, the onions and the cream in a dish.","timer":null},{"text":"Lay the halved reblochon on top, rind side up.","timer":null},{"text":"Bake for 20 minutes.","timer":{"label":"Oven","min":20}}],"variant":"The classic","change":""},{"title":"Ham crozet gratin","intro":"A milder crozet gratin, with ham.","minutes":45,"calories":680,"difficulty":"Facile","imageSearch":"crozets gratin ham","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"crozets","plural":"crozets","qty":400,"unit":"g","have":false},{"name":"cooked ham","plural":"cooked ham","qty":4,"unit":"slices","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":25,"unit":"cl","have":false},{"name":"grated emmental","plural":"grated emmental","qty":120,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Cook the crozets for 15 minutes.","timer":{"label":"Cooking","min":15}},{"text":"Soften the sliced onion.","timer":null},{"text":"Mix the crozets, the diced ham, the onion and the cream in a dish.","timer":null},{"text":"Cover with Emmental and bake for 20 minutes.","timer":{"label":"Oven","min":20}}],"kids":true,"variant":"With ham","change":"With ham and Emmental."},{"title":"Vegetarian croziflette","intro":"The meat-free croziflette, with mushrooms.","minutes":50,"calories":700,"difficulty":"Facile","imageSearch":"vegetarian croziflette","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"crozets","plural":"crozets","qty":400,"unit":"g","have":false},{"name":"reblochon","plural":"reblochons","qty":1,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":300,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false}],"steps":[{"text":"Cook the crozets for 15 minutes.","timer":{"label":"Cooking","min":15}},{"text":"Fry the sliced mushrooms and onions.","timer":{"label":"Pan","min":10}},{"text":"Mix everything with the cream in a dish and lay the reblochon on top.","timer":null},{"text":"Bake for 20 minutes at 200 °C.","timer":{"label":"Oven","min":20}}],"variant":"Vegetarian","change":"With mushrooms instead of bacon."}]$r$::jsonb, 'claude')
