unit":"","have":false},{"name":"bacon lardon","plural":"bacon lardons","qty":200,"unit":"g","have":false},{"name":"grated emmental","plural":"grated emmental","qty":100,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 250 °C.","timer":null},{"text":"Roll the doughs out thinly and cover with the fromage blanc and cream mixture.","timer":null},{"text":"Add the onions, the bacon and the Emmental.","timer":null},{"text":"Bake for 12 minutes.","timer":{"label":"Oven","min":12}}],"kids":true,"variant":"Cheesy","change":"With Emmental on top."},{"title":"Goat's cheese tarte flambée","intro":"A vegetarian tarte flambée with goat's cheese and onions.","minutes":35,"calories":480,"difficulty":"Facile","imageSearch":"goat cheese flatbread","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pizza dough","plural":"pizza doughs","qty":2,"unit":"","have":false},{"name":"fromage blanc","plural":"fromage blanc","qty":200,"unit":"g","have":false},{"name":"goat's cheese log","plural":"goat's cheese logs","qty":1,"unit":"","have":false},{"name":"red onion","plural":"red onions","qty":2,"unit":"","have":false},{"name":"honey","plural":"honey","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Preheat the oven to 250 °C.","timer":null},{"text":"Roll the doughs out thinly and cover with the fromage blanc.","timer":null},{"text":"Add the sliced onions and the rounds of goat's cheese.","timer":null},{"text":"Bake for 12 minutes and drizzle with honey when it comes out.","timer":{"label":"Oven","min":12}}],"variant":"Vegetarian","change":"With goat's cheese and honey, no bacon."}]$r$::jsonb, 'claude')
