insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:pissaladiere', 'Pissaladière', array['en:nicoise onion tart', 'en:onion tart', 'en:french onion tart']::text[], 'dish', $r$[{"title":"Pissaladière","intro":"The tart from Nice with melted onions, anchovies and black olives.","minutes":80,"calories":380,"difficulty":"Moyen","imageSearch":"pissaladiere","veg":false,"oven":true,"cold":false,"missing":"","origin":"Speciality of Nice","serves":4,"items":[{"name":"pizza dough","plural":"pizza doughs","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1000,"unit":"g","have":false},{"name":"anchovy in oil","plural":"anchovies in oil","qty":12,"unit":"","have":false},{"name":"black olive","plural":"black olives","qty":16,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false}],"steps":[{"text":"Slice the onions finely.","timer":null},{"text":"Soften them for 40 minutes over a low heat in the oil with the thyme, without browning them.","timer":{"label":"Cooking","min":40}},{"text":"Preheat the oven to 220 °C and roll the dough out on a baking tray.","timer":null},{"text":"Spread the onions over, make a criss-cross of anchovies and add the olives.","timer":null},{"text":"Bake for 20 minutes.","timer":{"label":"Oven","min":20}}],"variant":"The classic","change":""},{"title":"Alsatian onion tart","intro":"The creamy onion tart from Alsace.","minutes":70,"calories":420,"difficulty":"Moyen","imageSearch":"alsatian onion tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"Alsatian speciality","serves":4,"items":[{"name":"shortcrust pastry","plural":"shortcrust pastries","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":800,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"nutmeg","plural":"nutmeg","qty":null,"unit":"","have":false}],"steps":[{"text":"Soften the sliced onions for 25 minutes in the butter.","timer":{"label":"Cooking","min":25}},{"text":"Preheat the oven to 200 °C and line a tin with the pastry.","timer":null},{"text":"Beat the eggs with the cream, salt, pepper and nutmeg.","timer":null},{"text":"Spread the onions over the pastry and pour over the mixture.","timer":null},{"text":"Bake for 30 minutes.","timer":{"label":"Oven","min":30}}],"variant":"Alsatian","change":"The onions are bound with eggs and cream."},{"title":"Pissaladière without anchovies","intro":"A vegetarian pissaladière with onions and olives.","minutes":80,"calories":350,"difficulty":"Moyen","imageSearch":"onion olive tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pizza dough","plural":"pizza doughs","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1000,"unit":"g","have":false},{"name":"black olive","plural":"black olives","qty":20,"unit":"","have":false},{"name":"sun-dried tomato","plural":"sun-dried tomatoes","qty":60,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false}],"steps":[{"text":"Soften the sliced onions for 40 minutes over a low heat with the oil and the thyme.","timer":{"label":"Cooking","min":40}},{"text":"Preheat the oven to 220 °C and roll out the dough.","timer":null},{"text":"Spread the onions over, add the olives and the sun-dried tomato strips.","timer":null},{"text":"Bake for 20 minutes.","timer":{"label":"Oven","min":20}}],"variant":"Vegetarian","change":"No anchovies, with sun-dried tomatoes."}]$r$::jsonb, 'claude')
