insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:soupe au pistou', 'Soupe au pistou', array['en:pistou soup', 'en:provencal vegetable soup', 'en:pistou']::text[], 'dish', $r$[{"title":"Soupe au pistou","intro":"The Provençal soup of summer vegetables and beans, with its basil pistou.","minutes":60,"calories":380,"difficulty":"Facile","imageSearch":"soupe au pistou","veg":true,"oven":false,"cold":false,"missing":"","origin":"Provençal speciality","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"green bean","plural":"green beans","qty":200,"unit":"g","have":false},{"name":"white bean","plural":"white beans","qty":400,"unit":"g","have":false},{"name":"potato","plural":"potatoes","qty":2,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":2,"unit":"","have":false},{"name":"small pasta","plural":"small pasta","qty":80,"unit":"g","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"parmesan","plural":"parmesan","qty":50,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":6,"unit":"tbsp","have":false}],"steps":[{"text":"Cut all the vegetables into small dice.","timer":null},{"text":"Put them in 2 litres of salted water and cook for 30 minutes.","timer":{"label":"Cooking","min":30}},{"text":"Add the drained white beans and the pasta, and leave for 10 minutes.","timer":{"label":"Cooking","min":10}},{"text":"Pound the basil, the garlic, the parmesan and the olive oil together: this is the pistou.","timer":null},{"text":"Stir in the pistou off the heat, just before serving.","timer":null}],"variant":"The classic","change":""},{"title":"Quick pistou soup","intro":"Pistou soup in 25 minutes.","minutes":25,"calories":350,"difficulty":"Facile","imageSearch":"quick vegetable bean soup pesto","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"frozen soup vegetables","plural":"frozen soup vegetables","qty":600,"unit":"g","have":false},{"name":"white bean","plural":"white beans","qty":400,"unit":"g","have":false},{"name":"small pasta","plural":"small pasta","qty":80,"unit":"g","have":false},{"name":"pesto","plural":"pesto","qty":4,"unit":"tbsp","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false}],"steps":[{"text":"Bring 1.5 litres of water to the boil with the stock cube.","timer":null},{"text":"Add the vegetables and cook for 12 minutes.","timer":{"label":"Cooking","min":12}},{"text":"Add the beans and the pasta, and leave for 8 minutes.","timer":{"label":"Cooking","min":8}},{"text":"Stir in the pesto off the heat.","timer":null}],"variant":"Quick","change":"With frozen vegetables and ready-made pesto."},{"title":"Green minestrone with pistou","intro":"An all-green spring soup, with pistou.","minutes":45,"calories":320,"difficulty":"Facile","imageSearch":"green minestrone pistou","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"frozen pea","plural":"frozen peas","qty":150,"unit":"g","have":false},{"name":"frozen broad bean","plural":"frozen broad beans","qty":150,"unit":"g","have":false},{"name":"baby spinach","plural":"baby spinach","qty":100,"unit":"g","have":false},{"name":"leek","plural":"leeks","qty":1,"unit":"","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":5,"unit":"tbsp","have":false}],"steps":[{"text":"Fry the sliced leek in a little oil.","timer":null},{"text":"Add the diced courgettes and 1.5 litres of salted water, and cook for 15 minutes.","timer":{"label":"Cooking","min":15}},{"text":"Add the peas and the broad beans for 8 minutes, then the spinach.","timer":{"label":"Cooking","min":8}},{"text":"Blend the basil, the garlic and the oil, and add this pistou just before serving.","timer":null}],"variant":"Extra greens","change":"With peas, broad beans and spinach."}]$r$::jsonb, 'claude')
