insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:bouillabaisse', 'Bouillabaisse', array['en:fish soup', 'en:marseille fish stew', 'en:provencal fish soup']::text[], 'dish', $r$[{"title":"Bouillabaisse","intro":"The Marseille fish soup with saffron, served with rouille and croutons.","minutes":75,"calories":480,"difficulty":"Difficile","imageSearch":"bouillabaisse","veg":false,"oven":false,"cold":false,"missing":"","origin":"Speciality of Marseille","serves":4,"items":[{"name":"white fish fillet","plural":"white fish fillets","qty":800,"unit":"g","have":false},{"name":"mussel","plural":"mussels","qty":500,"unit":"g","have":false},{"name":"potato","plural":"potatoes","qty":4,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":3,"unit":"","have":false},{"name":"fennel","plural":"fennels","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"saffron","plural":"saffron","qty":null,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":4,"unit":"tbsp","have":false},{"name":"baguette","plural":"baguettes","qty":1,"unit":"","have":false}],"steps":[{"text":"Fry the onions, the sliced fennel and 2 cloves of garlic in olive oil.","timer":null},{"text":"Add the diced tomatoes, the saffron and 1.5 litres of water, and cook for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Add the sliced potatoes and leave for 15 minutes.","timer":{"label":"Cooking","min":15}},{"text":"Add the fish, cut into pieces, and the mussels, and leave for 8 minutes.","timer":{"label":"Cooking","min":8}},{"text":"Mix the mayonnaise with the remaining crushed garlic and a little saffron: this is the rouille.","timer":null},{"text":"Serve with toasted baguette and the rouille.","timer":null}],"variant":"The classic","change":""},{"title":"Blended fish soup","intro":"The velvety fish soup, with croutons and cheese.","minutes":50,"calories":350,"difficulty":"Moyen","imageSearch":"fish soup rouille","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"white fish fillet","plural":"white fish fillets","qty":600,"unit":"g","have":false},{"name":"tomato","plural":"tomatoes","qty":3,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"fennel","plural":"fennels","qty":1,"unit":"","have":false},{"name":"saffron","plural":"saffron","qty":null,"unit":"","have":false},{"name":"tomato purée","plural":"tomato purée","qty":1,"unit":"tbsp","have":false},{"name":"baguette","plural":"baguettes","qty":1,"unit":"","have":false},{"name":"grated emmental","plural":"grated emmental","qty":80,"unit":"g","have":false}],"steps":[{"text":"Fry the onions and the fennel, then add the tomatoes and the purée.","timer":null},{"text":"Add 1.2 litres of water, the saffron and the fish, and cook for 25 minutes.","timer":{"label":"Cooking","min":25}},{"text":"Blend finely and strain if you like.","timer":null},{"text":"Serve with toasted baguette and the Emmental.","timer":null}],"variant":"Blended","change":"The fish is blended into a smooth soup."},{"title":"Easy bouillabaisse","intro":"A simplified bouillabaisse for a weeknight.","minutes":40,"calories":400,"difficulty":"Facile","imageSearch":"easy fish stew saffron","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cod fillet","plural":"cod fillets","qty":4,"unit":"","have":false},{"name":"peeled prawn","plural":"peeled prawns","qty":200,"unit":"g","have":false},{"name":"potato","plural":"potatoes","qty":3,"unit":"","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"saffron","plural":"saffron","qty":null,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false}],"steps":[{"text":"Fry the onion and the garlic, then add the tomatoes, the saffron and 80 cl of water.","timer":null},{"text":"Add the sliced potatoes and leave for 15 minutes.","timer":{"label":"Cooking","min":15}},{"text":"Add the cod, cut into pieces, and the prawns, and leave for 6 minutes.","timer":{"label":"Cooking","min":6}},{"text":"Serve with toasted bread.","timer":null}],"variant":"Easy","change":"With cod and prawns, in less time."}]$r$::jsonb, 'claude')
