insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:daube provencale', 'Provençal daube', array['en:provencal daube', 'en:daube', 'en:beef daube', 'en:beef stew in red wine']::text[], 'dish', $r$[{"title":"Provençal daube","intro":"Beef marinated in red wine and slowly simmered with orange and olives.","minutes":210,"calories":580,"difficulty":"Moyen","imageSearch":"provencal beef daube","veg":false,"oven":false,"cold":false,"missing":"","origin":"Provençal speciality","serves":4,"items":[{"name":"braising beef","plural":"braising beef","qty":1200,"unit":"g","have":false},{"name":"red wine","plural":"red wine","qty":75,"unit":"cl","have":false},{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"bacon lardon","plural":"bacon lardons","qty":150,"unit":"g","have":false},{"name":"orange","plural":"oranges","qty":1,"unit":"","have":false},{"name":"black olive","plural":"black olives","qty":80,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false}],"steps":[{"text":"Marinate the beef pieces overnight in the wine with the carrots, the onions, the garlic, the bouquet garni and the orange zest.","timer":null},{"text":"Drain the meat and brown it with the bacon in a casserole dish.","timer":{"label":"Cooking","min":10}},{"text":"Add the marinade and bring to a simmer.","timer":null},{"text":"Cover and leave to simmer for 3 hours over a very low heat.","timer":{"label":"Cooking","min":180}},{"text":"Add the olives 15 minutes before the end.","timer":null}],"variant":"The classic","change":""},{"title":"Quick Provençal daube","intro":"All the flavour of a daube, in one hour.","minutes":75,"calories":560,"difficulty":"Facile","imageSearch":"beef stew red wine olives","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"braising beef","plural":"braising beef","qty":1000,"unit":"g","have":false},{"name":"red wine","plural":"red wine","qty":50,"unit":"cl","have":false},{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"orange","plural":"oranges","qty":1,"unit":"","have":false},{"name":"black olive","plural":"black olives","qty":80,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false}],"steps":[{"text":"Brown the beef pieces in the pressure cooker.","timer":{"label":"Cooking","min":10}},{"text":"Add the onions, the carrots, the garlic, the wine and the orange zest.","timer":null},{"text":"Close the lid and cook for 50 minutes after the pressure whistle.","timer":{"label":"Cooking","min":50}},{"text":"Add the olives and leave for 5 minutes with the lid off.","timer":null}],"variant":"Pressure cooker","change":"No marinating, cooked in a pressure cooker."},{"title":"Beef cheek daube","intro":"An ultra-tender daube made with beef cheeks.","minutes":240,"calories":560,"difficulty":"Moyen","imageSearch":"braised beef cheeks","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"beef cheek","plural":"beef cheeks","qty":1200,"unit":"g","have":false},{"name":"red wine","plural":"red wine","qty":75,"unit":"cl","have":false},{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":200,"unit":"g","have":false},{"name":"orange","plural":"oranges","qty":1,"unit":"","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false}],"steps":[{"text":"Brown the cheek pieces in a casserole dish.","timer":{"label":"Cooking","min":10}},{"text":"Add the onions, the carrots, the tomatoes, the wine, the zest and the bouquet garni.","timer":null},{"text":"Cover and leave to simmer for 3 hours 30 over a very low heat.","timer":{"label":"Cooking","min":210}},{"text":"Serve with fresh pasta or mash.","timer":null}],"variant":"Beef cheek","change":"With beef cheeks, even more tender."}]$r$::jsonb, 'claude')
