insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:piperade', 'Piperade', array['en:basque piperade', 'en:basque pepper and tomatoe']::text[], 'dish', $r$[{"title":"Piperade","intro":"The soft peppers and tomatoes of the Basque Country, with Bayonne ham.","minutes":45,"calories":280,"difficulty":"Facile","imageSearch":"piperade basque","veg":false,"oven":false,"cold":false,"missing":"","origin":"Basque speciality","serves":4,"items":[{"name":"green pepper","plural":"green peppers","qty":2,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":2,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":5,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"bayonne ham","plural":"bayonne ham","qty":4,"unit":"slices","have":false},{"name":"espelette pepper","plural":"espelette pepper","qty":1,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false}],"steps":[{"text":"Slice the onions and the peppers, and dice the tomatoes.","timer":null},{"text":"Soften the onions and the peppers for 15 minutes in the oil.","timer":{"label":"Pan","min":15}},{"text":"Add the tomatoes, the garlic and the espelette pepper, and leave for 15 minutes.","timer":{"label":"Cooking","min":15}},{"text":"Fry the ham for a few seconds in a pan and lay it on the piperade.","timer":null}],"variant":"The classic","change":""},{"title":"Piperade with eggs","intro":"The piperade with its eggs, as a complete dish.","minutes":40,"calories":300,"difficulty":"Facile","imageSearch":"piperade eggs","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"green pepper","plural":"green peppers","qty":2,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":2,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":5,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":6,"unit":"","have":false},{"name":"espelette pepper","plural":"espelette pepper","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Soften the sliced onions and peppers for 15 minutes.","timer":{"label":"Pan","min":15}},{"text":"Add the tomatoes and the pepper, and leave for 10 minutes.","timer":{"label":"Cooking","min":10}},{"text":"Pour in the beaten eggs and stir gently until creamy.","timer":null},{"text":"Serve straight away.","timer":null}],"variant":"With eggs","change":"Scrambled eggs stirred into the piperade."},{"title":"Vegetarian piperade","intro":"The vegetarian piperade, served with rice.","minutes":45,"calories":320,"difficulty":"Facile","imageSearch":"vegetarian piperade rice","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"green pepper","plural":"green peppers","qty":2,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":2,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":5,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"espelette pepper","plural":"espelette pepper","qty":1,"unit":"tsp","have":false},{"name":"rice","plural":"rice","qty":200,"unit":"g","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Soften the onions and the peppers for 15 minutes.","timer":{"label":"Pan","min":15}},{"text":"Add the tomatoes, the garlic and the pepper, and leave for 15 minutes.","timer":{"label":"Cooking","min":15}},{"text":"Serve with the rice.","timer":null}],"variant":"Vegetarian","change":"No ham, with rice."}]$r$::jsonb, 'claude')
