insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:potee auvergnate', 'Potée auvergnate', array['en:potee', 'en:cabbage and pork stew', 'en:auvergne hotpot']::text[], 'dish', $r$[{"title":"Auvergne potée","intro":"Cabbage, vegetables and salted pork simmered together for a complete winter dish.","minutes":150,"calories":650,"difficulty":"Facile","imageSearch":"potee auvergnate cabbage pork","veg":false,"oven":false,"cold":false,"missing":"","origin":"Speciality of the Auvergne","serves":4,"items":[{"name":"green cabbage","plural":"green cabbages","qty":1,"unit":"","have":false},{"name":"lightly salted pork shoulder","plural":"lightly salted pork shoulders","qty":1,"unit":"","have":false},{"name":"morteau sausage","plural":"morteau sausages","qty":1,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":6,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":4,"unit":"","have":false},{"name":"turnip","plural":"turnips","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false}],"steps":[{"text":"Soak the pork in cold water for 2 hours to remove the salt.","timer":null},{"text":"Put it in a large pot of cold water with the onion and the bouquet garni, and cook for 1 hour.","timer":{"label":"Cooking","min":60}},{"text":"Add the cabbage, cut into quarters and blanched for 5 minutes, the carrots and the turnips.","timer":null},{"text":"Cook for 30 minutes.","timer":{"label":"Cooking","min":30}},{"text":"Add the potatoes and the pricked sausage, and leave for 30 minutes.","timer":{"label":"Cooking","min":30}}],"variant":"The classic","change":""},{"title":"Sausage potée","intro":"A simplified potée for a weeknight.","minutes":60,"calories":580,"difficulty":"Facile","imageSearch":"cabbage sausage stew","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"green cabbage","plural":"green cabbages","qty":1,"unit":"","have":false},{"name":"toulouse sausage","plural":"toulouse sausages","qty":4,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":6,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false}],"steps":[{"text":"Cut the cabbage into strips and blanch for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Brown the sausages in a casserole dish.","timer":{"label":"Cooking","min":6}},{"text":"Add the cabbage, the carrots, the potatoes, the onion, the stock cube and 50 cl of water.","timer":null},{"text":"Cover and leave to simmer for 40 minutes.","timer":{"label":"Cooking","min":40}}],"variant":"With sausages","change":"Just with sausages, so it is quicker."},{"title":"Vegetable potée","intro":"A comforting potée with winter vegetables.","minutes":50,"calories":320,"difficulty":"Facile","imageSearch":"vegetable cabbage stew","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"green cabbage","plural":"green cabbages","qty":0.5,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":4,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"leek","plural":"leeks","qty":2,"unit":"","have":false},{"name":"white bean","plural":"white beans","qty":400,"unit":"g","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false}],"steps":[{"text":"Cut all the vegetables into pieces.","timer":null},{"text":"Put them in a casserole dish with the stock cube and 1 litre of water.","timer":null},{"text":"Leave to simmer for 35 minutes.","timer":{"label":"Cooking","min":35}},{"text":"Add the white beans and leave for 5 minutes.","timer":{"label":"Cooking","min":5}}],"variant":"Vegetarian","change":"No meat, with white beans."}]$r$::jsonb, 'claude')
