insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:pate au thon', 'Tuna pasta', array['en:tuna pasta', 'en:tuna tomato pasta', 'en:spaghetti with tuna']::text[], 'dish', $r$[{"title":"Tuna and tomato pasta","intro":"Pasta in a tomato sauce with tuna, garlic and capers: the dinner for busy evenings.","minutes":20,"calories":520,"difficulty":"Facile","imageSearch":"tuna tomato pasta","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pasta","plural":"pasta","qty":400,"unit":"g","have":false},{"name":"tuna in water","plural":"tuna in water","qty":280,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"caper","plural":"capers","qty":1,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the pasta.","timer":{"label":"Cooking","min":10}},{"text":"Fry the onion and the garlic in the oil.","timer":null},{"text":"Add the tomatoes and leave to simmer for 10 minutes.","timer":{"label":"Cooking","min":10}},{"text":"Add the flaked tuna and the capers, and mix with the pasta.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Creamy tuna pasta","intro":"Creamy tuna pasta with lemon and chives.","minutes":20,"calories":580,"difficulty":"Facile","imageSearch":"creamy tuna pasta","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pasta","plural":"pasta","qty":400,"unit":"g","have":false},{"name":"tuna in water","plural":"tuna in water","qty":280,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"chive","plural":"chives","qty":null,"unit":"","have":false},{"name":"parmesan","plural":"parmesan","qty":30,"unit":"g","have":false}],"steps":[{"text":"Cook the pasta.","timer":{"label":"Cooking","min":10}},{"text":"Heat the cream with the lemon zest.","timer":null},{"text":"Add the flaked tuna and a little lemon juice.","timer":null},{"text":"Mix with the pasta, the chives and the parmesan.","timer":null}],"kids":true,"variant":"Creamy","change":"A lemon cream sauce instead of tomato."},{"title":"Baked tuna pasta","intro":"A simple, family tuna pasta bake.","minutes":35,"calories":600,"difficulty":"Facile","imageSearch":"tuna pasta bake","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pasta","plural":"pasta","qty":350,"unit":"g","have":false},{"name":"tuna in water","plural":"tuna in water","qty":280,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarella","qty":1,"unit":"","have":false},{"name":"grated emmental","plural":"grated emmental","qty":80,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Cook the pasta for 2 minutes less than the packet says.","timer":{"label":"Cooking","min":8}},{"text":"Mix the pasta, the tomatoes and the tuna in a dish.","timer":null},{"text":"Cover with mozzarella and Emmental.","timer":null},{"text":"Bake for 20 minutes.","timer":{"label":"Oven","min":20}}],"kids":true,"variant":"Oven-baked","change":"Baked in the oven with cheese."}]$r$::jsonb, 'claude')
