insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:pate au poulet', 'Chicken pasta', array['en:chicken pasta', 'en:creamy chicken pasta', 'en:chicken tagliatelle']::text[], 'dish', $r$[{"title":"Creamy chicken pasta","intro":"Tagliatelle with browned chicken and a creamy mushroom sauce.","minutes":30,"calories":620,"difficulty":"Facile","imageSearch":"creamy chicken pasta","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"tagliatelle","plural":"tagliatelle","qty":400,"unit":"g","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":3,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":200,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"shallot","plural":"shallots","qty":1,"unit":"","have":false},{"name":"parmesan","plural":"parmesan","qty":30,"unit":"g","have":false}],"steps":[{"text":"Cook the pasta.","timer":{"label":"Cooking","min":10}},{"text":"Brown the diced chicken for 6 minutes, then remove it.","timer":{"label":"Pan","min":6}},{"text":"Fry the shallot and the sliced mushrooms for 5 minutes.","timer":{"label":"Pan","min":5}},{"text":"Add the cream and the chicken, and leave for 3 minutes.","timer":null},{"text":"Mix with the pasta and sprinkle with parmesan.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Pesto chicken pasta","intro":"A light chicken pasta, with pesto.","minutes":25,"calories":560,"difficulty":"Facile","imageSearch":"pesto chicken pasta","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pasta","plural":"pasta","qty":400,"unit":"g","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":3,"unit":"","have":false},{"name":"pesto","plural":"pesto","qty":4,"unit":"tbsp","have":false},{"name":"cherry tomato","plural":"cherry tomatoes","qty":250,"unit":"g","have":false},{"name":"parmesan","plural":"parmesan","qty":30,"unit":"g","have":false}],"steps":[{"text":"Cook the pasta.","timer":{"label":"Cooking","min":10}},{"text":"Brown the diced chicken for 6 minutes.","timer":{"label":"Pan","min":6}},{"text":"Add the halved cherry tomatoes and leave for 2 minutes.","timer":null},{"text":"Mix with the pasta, the pesto and the parmesan.","timer":null}],"variant":"Pesto","change":"With pesto and cherry tomatoes."},{"title":"Lemon chicken pasta","intro":"Fresh pasta with chicken, lemon and spinach.","minutes":25,"calories":520,"difficulty":"Facile","imageSearch":"lemon chicken pasta spinach","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pasta","plural":"pasta","qty":400,"unit":"g","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":3,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"baby spinach","plural":"baby spinach","qty":100,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the pasta.","timer":{"label":"Cooking","min":10}},{"text":"Brown the diced chicken with the garlic in the oil.","timer":{"label":"Pan","min":6}},{"text":"Add the spinach, and the zest and juice of the lemon.","timer":null},{"text":"Mix with the pasta and a little of the cooking water.","timer":null}],"variant":"Lemon","change":"A light sauce with lemon and spinach."}]$r$::jsonb, 'claude')
