insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:spaghetti alle vongole', 'Spaghetti alle vongole', array['en:clam spaghetti', 'en:spaghetti with clam', 'en:vongole', 'en:seafood pasta']::text[], 'dish', $r$[{"title":"Spaghetti with clams","intro":"Italian spaghetti with clams, garlic, white wine and parsley.","minutes":30,"calories":480,"difficulty":"Moyen","imageSearch":"spaghetti alle vongole","veg":false,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"spaghetti","plural":"spaghetti","qty":400,"unit":"g","have":false},{"name":"clam","plural":"clams","qty":1000,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"white wine","plural":"white wine","qty":10,"unit":"cl","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"chilli","plural":"chillies","qty":1,"unit":"","have":false}],"steps":[{"text":"Soak the clams for 30 minutes in salted water to get rid of the sand.","timer":null},{"text":"Cook the spaghetti.","timer":{"label":"Cooking","min":9}},{"text":"Fry the garlic and the chilli in the oil, add the clams and the wine, and cover.","timer":null},{"text":"Take off the heat as soon as they open.","timer":{"label":"Cooking","min":4}},{"text":"Mix the spaghetti with the clams and the parsley.","timer":null}],"variant":"The classic","change":""},{"title":"Seafood pasta","intro":"Easy seafood pasta in a tomato sauce.","minutes":25,"calories":500,"difficulty":"Facile","imageSearch":"seafood pasta","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"spaghetti","plural":"spaghetti","qty":400,"unit":"g","have":false},{"name":"frozen seafood mix","plural":"frozen seafood mix","qty":400,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"white wine","plural":"white wine","qty":10,"unit":"cl","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the spaghetti.","timer":{"label":"Cooking","min":9}},{"text":"Fry the garlic, add the seafood and the wine, and leave for 5 minutes.","timer":{"label":"Pan","min":5}},{"text":"Add the tomatoes and leave for 8 minutes.","timer":{"label":"Cooking","min":8}},{"text":"Mix with the pasta and sprinkle with parsley.","timer":null}],"variant":"Seafood","change":"With a mix of frozen seafood and tomato."},{"title":"Spaghetti with mussels","intro":"The more affordable version, with mussels.","minutes":30,"calories":480,"difficulty":"Moyen","imageSearch":"mussel spaghetti","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"spaghetti","plural":"spaghetti","qty":400,"unit":"g","have":false},{"name":"mussel","plural":"mussels","qty":1000,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"white wine","plural":"white wine","qty":10,"unit":"cl","have":false},{"name":"cherry tomato","plural":"cherry tomatoes","qty":200,"unit":"g","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the spaghetti.","timer":{"label":"Cooking","min":9}},{"text":"Open the mussels with the garlic and the wine, covered.","timer":{"label":"Cooking","min":5}},{"text":"Shell half of them and add the cherry tomatoes.","timer":null},{"text":"Mix with the spaghetti and the parsley.","timer":null}],"variant":"With mussels","change":"Mussels instead of clams."}]$r$::jsonb, 'claude')
