insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:cannelloni', 'Cannelloni', array['en:spinach and ricotta cannelloni', 'en:meat cannelloni']::text[], 'dish', $r$[{"title":"Spinach and ricotta cannelloni","intro":"Pasta tubes stuffed with ricotta and spinach, baked in tomato sauce.","minutes":60,"calories":520,"difficulty":"Moyen","imageSearch":"spinach ricotta cannelloni","veg":true,"oven":true,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"cannelloni tube","plural":"cannelloni tubes","qty":16,"unit":"","have":false},{"name":"ricotta","plural":"ricotta","qty":500,"unit":"g","have":false},{"name":"frozen spinach","plural":"frozen spinach","qty":400,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":600,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarella","qty":1,"unit":"","have":false},{"name":"parmesan","plural":"parmesan","qty":50,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C. Defrost the spinach and squeeze it dry.","timer":null},{"text":"Mix it with the ricotta, the egg, half of the parmesan, salt and pepper.","timer":null},{"text":"Fill the cannelloni using a piping bag or a small spoon.","timer":null},{"text":"Spread half of the tomatoes in a dish, arrange the cannelloni on top and cover with the rest.","timer":null},{"text":"Add the mozzarella and the parmesan, and bake for 35 minutes.","timer":{"label":"Oven","min":35}}],"makes":{"n":16,"one":"cannelloni","many":"cannelloni"},"variant":"The classic","change":""},{"title":"Meat cannelloni","intro":"Cannelloni like rolled-up lasagne, with meat.","minutes":70,"calories":620,"difficulty":"Moyen","imageSearch":"meat cannelloni bechamel","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cannelloni tube","plural":"cannelloni tubes","qty":16,"unit":"","have":false},{"name":"minced beef","plural":"minced beef","qty":500,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"flour","plural":"flour","qty":40,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"grated emmental","plural":"grated emmental","qty":80,"unit":"g","have":false}],"steps":[{"text":"Fry the onion and the beef, add half of the tomatoes and leave for 10 minutes.","timer":{"label":"Cooking","min":10}},{"text":"Make a béchamel with the butter, the flour and the milk.","timer":null},{"text":"Fill the cannelloni with the meat and arrange them in a dish on the rest of the tomatoes.","timer":null},{"text":"Cover with the béchamel and the Emmental.","timer":null},{"text":"Bake for 35 minutes at 180 °C.","timer":{"label":"Oven","min":35}}],"kids":true,"makes":{"n":16,"one":"cannelloni","many":"cannelloni"},"variant":"With meat","change":"Stuffed with minced beef in tomato, under béchamel."},{"title":"Salmon cannelloni","intro":"Delicate cannelloni with salmon and dill.","minutes":60,"calories":540,"difficulty":"Moyen","imageSearch":"salmon cannelloni","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cannelloni tube","plural":"cannelloni tubes","qty":16,"unit":"","have":false},{"name":"salmon fillet","plural":"salmon fillets","qty":2,"unit":"","have":false},{"name":"ricotta","plural":"ricotta","qty":400,"unit":"g","have":false},{"name":"dill","plural":"dill","qty":null,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":25,"unit":"cl","have":false},{"name":"parmesan","plural":"parmesan","qty":50,"unit":"g","have":false}],"steps":[{"text":"Steam the salmon for 10 minutes and flake it.","timer":{"label":"Cooking","min":10}},{"text":"Mix it with the ricotta and the dill.","timer":null},{"text":"Fill the cannelloni and arrange them in a dish.","timer":null},{"text":"Cover with the cream and the parmesan, and bake for 30 minutes at 180 °C.","timer":{"label":"Oven","min":30}}],"makes":{"n":16,"one":"cannelloni","many":"cannelloni"},"variant":"With salmon","change":"Stuffed with salmon and ricotta."}]$r$::jsonb, 'claude')
