insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:aubergine a la parmesane', 'Aubergine parmigiana', array['en:aubergine parmigiana', 'en:parmigiana', 'en:aubergine parmesan', 'en:eggplant parmesan', 'en:melanzane']::text[], 'dish', $r$[{"title":"Aubergine parmigiana","intro":"Layers of grilled aubergine slices with tomato sauce, mozzarella and parmesan.","minutes":75,"calories":420,"difficulty":"Moyen","imageSearch":"eggplant parmigiana","veg":true,"oven":true,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"aubergine","plural":"aubergines","qty":3,"unit":"","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":800,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarella","qty":2,"unit":"","have":false},{"name":"parmesan","plural":"parmesan","qty":80,"unit":"g","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":5,"unit":"tbsp","have":false}],"steps":[{"text":"Slice the aubergines, brush with oil and roast them in the oven for 20 minutes at 200 °C.","timer":{"label":"Oven","min":20}},{"text":"Simmer the tomatoes with the garlic for 15 minutes.","timer":{"label":"Cooking","min":15}},{"text":"Layer in a dish: sauce, aubergines, mozzarella, parmesan and basil.","timer":null},{"text":"Finish with sauce, mozzarella and parmesan.","timer":null},{"text":"Bake for 30 minutes at 180 °C.","timer":{"label":"Oven","min":30}}],"variant":"The classic","change":""},{"title":"Aubergine and meat bake","intro":"A generous aubergine bake, like a quick moussaka.","minutes":75,"calories":520,"difficulty":"Moyen","imageSearch":"eggplant beef bake","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"aubergine","plural":"aubergines","qty":3,"unit":"","have":false},{"name":"minced beef","plural":"minced beef","qty":400,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":600,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"mozzarella","plural":"mozzarella","qty":1,"unit":"","have":false},{"name":"parmesan","plural":"parmesan","qty":50,"unit":"g","have":false}],"steps":[{"text":"Roast the sliced aubergines in the oven for 20 minutes.","timer":{"label":"Oven","min":20}},{"text":"Fry the onion and the beef, then add the tomatoes and leave for 10 minutes.","timer":{"label":"Cooking","min":10}},{"text":"Layer the aubergines and the meat in a dish.","timer":null},{"text":"Cover with mozzarella and parmesan, and bake for 25 minutes at 180 °C.","timer":{"label":"Oven","min":25}}],"variant":"With meat","change":"With a layer of minced beef."},{"title":"Italian stuffed aubergines","intro":"Aubergine halves filled with tomato and mozzarella.","minutes":55,"calories":350,"difficulty":"Facile","imageSearch":"stuffed eggplant italian","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"aubergine","plural":"aubergines","qty":2,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":3,"unit":"","have":false},{"name":"mozzarella","plural":"mozzarella","qty":1,"unit":"","have":false},{"name":"parmesan","plural":"parmesan","qty":40,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Halve the aubergines and score the flesh.","timer":null},{"text":"Bake for 25 minutes, then scoop out half of the flesh.","timer":{"label":"Oven","min":25}},{"text":"Mix the flesh with the diced tomatoes, the garlic and the basil.","timer":null},{"text":"Fill the aubergines, cover with mozzarella and parmesan, and bake for 15 minutes.","timer":{"label":"Oven","min":15}}],"variant":"Stuffed","change":"The halved aubergines are stuffed."}]$r$::jsonb, 'claude')
