insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:polenta', 'Polenta', array['en:creamy polenta', 'en:grilled polenta', 'en:polenta chip']::text[], 'dish', $r$[{"title":"Creamy parmesan polenta","intro":"A smooth polenta with parmesan and butter, to serve with a meat in sauce.","minutes":15,"calories":320,"difficulty":"Facile","imageSearch":"creamy polenta","veg":true,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"instant polenta","plural":"instant polenta","qty":250,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"parmesan","plural":"parmesan","qty":60,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Bring the milk to the boil with 50 cl of salted water.","timer":null},{"text":"Pour in the polenta in a thin stream, whisking.","timer":null},{"text":"Cook for 5 minutes, stirring.","timer":{"label":"Cooking","min":5}},{"text":"Stir in the parmesan and the butter off the heat.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Grilled polenta","intro":"Crispy polenta pieces, with a tomato sauce.","minutes":30,"calories":300,"difficulty":"Facile","imageSearch":"grilled polenta squares","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"instant polenta","plural":"instant polenta","qty":250,"unit":"g","have":false},{"name":"parmesan","plural":"parmesan","qty":50,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false}],"steps":[{"text":"Cook the polenta in 1 litre of salted water for 5 minutes, then stir in the parmesan.","timer":{"label":"Cooking","min":5}},{"text":"Spread it 2 cm thick in a dish and leave to cool for 1 hour.","timer":null},{"text":"Cut into pieces and brown them in the oil in a pan.","timer":{"label":"Pan","min":8}},{"text":"Serve with the heated tomato sauce.","timer":null}],"kids":true,"variant":"Grilled","change":"Cooled, cut into pieces and browned in a pan."},{"title":"Mushroom polenta","intro":"A creamy polenta topped with mushrooms.","minutes":25,"calories":420,"difficulty":"Facile","imageSearch":"polenta mushrooms","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"instant polenta","plural":"instant polenta","qty":250,"unit":"g","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":400,"unit":"g","have":false},{"name":"shallot","plural":"shallots","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":15,"unit":"cl","have":false},{"name":"parmesan","plural":"parmesan","qty":50,"unit":"g","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the shallots and the sliced mushrooms for 10 minutes, then add the cream.","timer":{"label":"Pan","min":10}},{"text":"Cook the polenta in 1 litre of salted water for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Stir the parmesan into the polenta.","timer":null},{"text":"Serve the polenta with the mushrooms and the parsley.","timer":null}],"variant":"Mushroom","change":"With creamy pan-fried mushrooms."}]$r$::jsonb, 'claude')
