insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:saltimbocca', 'Saltimbocca', array['en:veal saltimbocca', 'en:saltimbocca alla romana']::text[], 'dish', $r$[{"title":"Veal saltimbocca","intro":"Thin veal escalopes with cured ham and sage, pan-fried and deglazed with white wine.","minutes":25,"calories":380,"difficulty":"Moyen","imageSearch":"veal saltimbocca","veg":false,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"veal escalope","plural":"veal escalopes","qty":4,"unit":"","have":false},{"name":"cured ham","plural":"cured ham","qty":4,"unit":"slices","have":false},{"name":"sage","plural":"sage","qty":8,"unit":"leaves","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"white wine","plural":"white wine","qty":10,"unit":"cl","have":false},{"name":"flour","plural":"flour","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Flatten the escalopes and cut them in half.","timer":null},{"text":"Lay half a slice of ham and a sage leaf on each one, held with a cocktail stick.","timer":null},{"text":"Lightly flour the meat side.","timer":null},{"text":"Brown for 2 minutes on each side in the butter.","timer":{"label":"Pan","min":4}},{"text":"Deglaze with the white wine and leave to reduce for 2 minutes.","timer":null}],"variant":"The classic","change":""},{"title":"Chicken saltimbocca","intro":"The chicken saltimbocca, cheaper and just as good.","minutes":30,"calories":360,"difficulty":"Facile","imageSearch":"chicken saltimbocca","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"cured ham","plural":"cured ham","qty":4,"unit":"slices","have":false},{"name":"sage","plural":"sage","qty":8,"unit":"leaves","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"white wine","plural":"white wine","qty":10,"unit":"cl","have":false}],"steps":[{"text":"Slice the chicken breasts in half and flatten them.","timer":null},{"text":"Lay on the ham and the sage, and hold with a cocktail stick.","timer":null},{"text":"Brown for 4 minutes on each side in the butter.","timer":{"label":"Pan","min":8}},{"text":"Deglaze with the white wine and leave to reduce.","timer":null}],"variant":"With chicken","change":"With flattened chicken breasts."},{"title":"Lemon turkey saltimbocca","intro":"Turkey escalopes with cured ham, in a lemon sauce.","minutes":25,"calories":320,"difficulty":"Facile","imageSearch":"turkey saltimbocca lemon","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"turkey escalope","plural":"turkey escalopes","qty":4,"unit":"","have":false},{"name":"cured ham","plural":"cured ham","qty":4,"unit":"slices","have":false},{"name":"sage","plural":"sage","qty":8,"unit":"leaves","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false}],"steps":[{"text":"Lay the ham and the sage on the escalopes and hold with a cocktail stick.","timer":null},{"text":"Brown for 3 minutes on each side in the butter.","timer":{"label":"Pan","min":6}},{"text":"Add the lemon juice and 5 cl of water.","timer":null},{"text":"Leave to reduce for 1 minute and serve.","timer":null}],"variant":"Turkey and lemon","change":"With turkey and a lemon sauce."}]$r$::jsonb, 'claude')
