insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:pate aux courgette', 'Courgette pasta', array['en:courgette pasta', 'en:zucchini pasta', 'en:courgette and feta pasta', 'en:spaghetti with courgette']::text[], 'dish', $r$[{"title":"Courgette and parmesan pasta","intro":"Pasta with soft courgettes cooked with garlic, lemon and parmesan.","minutes":25,"calories":450,"difficulty":"Facile","imageSearch":"zucchini pasta","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pasta","plural":"pasta","qty":400,"unit":"g","have":false},{"name":"courgette","plural":"courgettes","qty":3,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"parmesan","plural":"parmesan","qty":50,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the pasta.","timer":{"label":"Cooking","min":10}},{"text":"Grate the courgettes or cut them into thin slices.","timer":null},{"text":"Soften them for 10 minutes with the garlic in the oil.","timer":{"label":"Pan","min":10}},{"text":"Mix with the pasta, the lemon zest and the parmesan.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Courgette and feta pasta","intro":"Fresh pasta with courgettes, feta and mint.","minutes":25,"calories":470,"difficulty":"Facile","imageSearch":"zucchini feta pasta","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pasta","plural":"pasta","qty":400,"unit":"g","have":false},{"name":"courgette","plural":"courgettes","qty":3,"unit":"","have":false},{"name":"feta","plural":"feta","qty":150,"unit":"g","have":false},{"name":"fresh mint","plural":"fresh mint","qty":null,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the pasta.","timer":{"label":"Cooking","min":10}},{"text":"Fry the diced courgettes with the garlic for 8 minutes.","timer":{"label":"Pan","min":8}},{"text":"Mix with the pasta.","timer":null},{"text":"Add the crumbled feta and the chopped mint.","timer":null}],"variant":"Feta","change":"With feta and mint."},{"title":"Courgette and bacon pasta","intro":"Creamy pasta with courgettes and bacon.","minutes":25,"calories":560,"difficulty":"Facile","imageSearch":"zucchini bacon pasta","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pasta","plural":"pasta","qty":400,"unit":"g","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"bacon lardon","plural":"bacon lardons","qty":150,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":15,"unit":"cl","have":false},{"name":"parmesan","plural":"parmesan","qty":30,"unit":"g","have":false}],"steps":[{"text":"Cook the pasta.","timer":{"label":"Cooking","min":10}},{"text":"Brown the bacon, then add the diced courgettes for 8 minutes.","timer":{"label":"Pan","min":8}},{"text":"Add the cream and leave for 2 minutes.","timer":null},{"text":"Mix with the pasta and the parmesan.","timer":null}],"kids":true,"variant":"Bacon","change":"With bacon and cream."}]$r$::jsonb, 'claude')
