insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:arancini', 'Arancini', array['en:rice ball', 'en:sicilian rice ball']::text[], 'dish', $r$[{"title":"Arancini","intro":"Sicilian risotto balls with a mozzarella centre, breaded and fried.","minutes":90,"calories":420,"difficulty":"Difficile","imageSearch":"arancini","veg":true,"oven":false,"cold":false,"missing":"","origin":"Sicilian speciality","serves":4,"items":[{"name":"risotto rice","plural":"risotto rice","qty":300,"unit":"g","have":false},{"name":"vegetable stock","plural":"vegetable stock","qty":1,"unit":"","have":false},{"name":"parmesan","plural":"parmesan","qty":60,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarella","qty":1,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"breadcrumb","plural":"breadcrumbs","qty":100,"unit":"g","have":false},{"name":"frying oil","plural":"frying oil","qty":100,"unit":"cl","have":false}],"steps":[{"text":"Make a risotto: toast the rice until translucent, then add the stock little by little for 18 minutes.","timer":{"label":"Cooking","min":18}},{"text":"Stir in the parmesan and leave to cool completely.","timer":null},{"text":"Shape into balls with a cube of mozzarella in the middle.","timer":null},{"text":"Dip them in the beaten eggs, then in the breadcrumbs.","timer":null},{"text":"Fry for 4 minutes in the hot oil.","timer":{"label":"Frying","min":4}}],"makes":{"n":16,"one":"arancini","many":"arancini"},"variant":"The classic","change":""},{"title":"Bolognese arancini","intro":"Meat-filled arancini, like in Sicily.","minutes":100,"calories":480,"difficulty":"Difficile","imageSearch":"meat arancini","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"risotto rice","plural":"risotto rice","qty":300,"unit":"g","have":false},{"name":"vegetable stock","plural":"vegetable stock","qty":1,"unit":"","have":false},{"name":"parmesan","plural":"parmesan","qty":50,"unit":"g","have":false},{"name":"minced beef","plural":"minced beef","qty":200,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":200,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"breadcrumb","plural":"breadcrumbs","qty":100,"unit":"g","have":false},{"name":"frying oil","plural":"frying oil","qty":100,"unit":"cl","have":false}],"steps":[{"text":"Make a parmesan risotto and leave it to cool.","timer":{"label":"Cooking","min":18}},{"text":"Make a small, thick bolognese with the beef and the tomatoes.","timer":{"label":"Cooking","min":15}},{"text":"Shape the rice into balls with a little bolognese in the middle.","timer":null},{"text":"Coat them in egg and breadcrumbs, and fry for 4 minutes.","timer":{"label":"Frying","min":4}}],"makes":{"n":16,"one":"arancini","many":"arancini"},"variant":"With meat","change":"With a bolognese sauce centre."},{"title":"Baked arancini","intro":"Lighter arancini, golden from the oven.","minutes":80,"calories":350,"difficulty":"Moyen","imageSearch":"baked arancini","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"risotto rice","plural":"risotto rice","qty":300,"unit":"g","have":false},{"name":"vegetable stock","plural":"vegetable stock","qty":1,"unit":"","have":false},{"name":"parmesan","plural":"parmesan","qty":60,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarella","qty":1,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"breadcrumb","plural":"breadcrumbs","qty":100,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false}],"steps":[{"text":"Make a parmesan risotto and leave it to cool.","timer":{"label":"Cooking","min":18}},{"text":"Shape into balls with a cube of mozzarella in the middle.","timer":null},{"text":"Coat them in egg and breadcrumbs, and drizzle with oil.","timer":null},{"text":"Bake for 25 minutes at 200 °C.","timer":{"label":"Oven","min":25}}],"makes":{"n":16,"one":"arancini","many":"arancini"},"variant":"Oven-baked","change":"Baked in the oven rather than fried."}]$r$::jsonb, 'claude')
