insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:pate aux quatre fromage', 'Four cheese pasta', array['en:four cheese pasta', 'en:4 cheese pasta', 'en:quattro formaggi', 'en:four cheese penne']::text[], 'dish', $r$[{"title":"Four cheese pasta","intro":"Pasta covered in a melting cream sauce with gorgonzola, mozzarella, parmesan and Emmental.","minutes":20,"calories":700,"difficulty":"Facile","imageSearch":"four cheese pasta","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pasta","plural":"pasta","qty":400,"unit":"g","have":false},{"name":"gorgonzola","plural":"gorgonzola","qty":100,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarella","qty":1,"unit":"","have":false},{"name":"parmesan","plural":"parmesan","qty":40,"unit":"g","have":false},{"name":"grated emmental","plural":"grated emmental","qty":60,"unit":"g","have":false},{"name":"single cream","plural":"single cream","qty":20,"unit":"cl","have":false}],"steps":[{"text":"Cook the pasta.","timer":{"label":"Cooking","min":10}},{"text":"Heat the cream over a low heat.","timer":null},{"text":"Add the gorgonzola, the diced mozzarella, the Emmental and the parmesan, and stir until everything has melted.","timer":null},{"text":"Mix with the pasta and add pepper.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Baked four cheese pasta","intro":"A four cheese pasta bake, golden and stringy.","minutes":35,"calories":720,"difficulty":"Facile","imageSearch":"baked four cheese pasta","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"short pasta","plural":"short pasta","qty":400,"unit":"g","have":false},{"name":"gorgonzola","plural":"gorgonzola","qty":100,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarella","qty":1,"unit":"","have":false},{"name":"parmesan","plural":"parmesan","qty":40,"unit":"g","have":false},{"name":"grated emmental","plural":"grated emmental","qty":80,"unit":"g","have":false},{"name":"single cream","plural":"single cream","qty":20,"unit":"cl","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Cook the pasta for 2 minutes less than the packet says.","timer":{"label":"Cooking","min":8}},{"text":"Melt the gorgonzola and the parmesan in the cream.","timer":null},{"text":"Mix with the pasta in a dish and cover with mozzarella and Emmental.","timer":null},{"text":"Bake for 15 minutes.","timer":{"label":"Oven","min":15}}],"kids":true,"variant":"Oven-baked","change":"Finished in the oven."},{"title":"Mild three cheese pasta","intro":"A mild version with no blue cheese, using Emmental, mozzarella and parmesan.","minutes":20,"calories":650,"difficulty":"Facile","imageSearch":"mild cheese pasta","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pasta","plural":"pasta","qty":400,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarella","qty":1,"unit":"","have":false},{"name":"grated emmental","plural":"grated emmental","qty":80,"unit":"g","have":false},{"name":"parmesan","plural":"parmesan","qty":40,"unit":"g","have":false},{"name":"single cream","plural":"single cream","qty":20,"unit":"cl","have":false}],"steps":[{"text":"Cook the pasta.","timer":{"label":"Cooking","min":10}},{"text":"Heat the cream and melt the cheeses in it.","timer":null},{"text":"Mix with the pasta.","timer":null},{"text":"Add pepper and serve straight away.","timer":null}],"kids":true,"variant":"Mild cheeses","change":"No blue cheese, for kids."}]$r$::jsonb, 'claude')
