insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:sole meuniere', 'Sole meunière', array['en:sole', 'en:pan fried sole', 'en:sole in butter']::text[], 'dish', $r$[{"title":"Sole meunière","intro":"Sole dusted in flour and fried golden in butter, with lemon and parsley.","minutes":25,"calories":380,"difficulty":"Moyen","imageSearch":"sole meuniere","veg":false,"oven":false,"cold":false,"missing":"","origin":"French classic","serves":4,"items":[{"name":"sole","plural":"soles","qty":2,"unit":"","have":false},{"name":"flour","plural":"flour","qty":3,"unit":"tbsp","have":false},{"name":"butter","plural":"butter","qty":80,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":600,"unit":"g","have":false}],"steps":[{"text":"Boil the potatoes in salted water for 20 min.","timer":{"label":"Cooking","min":20}},{"text":"Dip the soles in the flour and shake off the excess.","timer":null},{"text":"Fry them for 5 min on each side in 40 g of butter.","timer":{"label":"Pan","min":10}},{"text":"Add the rest of the butter and let it turn golden. Add the lemon juice and the parsley.","timer":null},{"text":"Spoon this butter over the soles and serve with the potatoes.","timer":null}],"variant":"The classic","change":""},{"title":"Dab fillets meunière","intro":"The meunière recipe with fillets, so no bones.","minutes":20,"calories":320,"difficulty":"Facile","imageSearch":"fish fillet meuniere","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"dab fillet","plural":"dab fillets","qty":8,"unit":"","have":false},{"name":"flour","plural":"flour","qty":3,"unit":"tbsp","have":false},{"name":"butter","plural":"butter","qty":60,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"rice","plural":"rice","qty":200,"unit":"g","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Dip the fillets in the flour.","timer":null},{"text":"Fry them for 2 min on each side in the butter.","timer":{"label":"Pan","min":4}},{"text":"Add the lemon juice and the parsley, and spoon it over the fillets.","timer":null}],"variant":"Fillets","change":"Made with dab fillets, which are easier and cheaper."},{"title":"Baked sole","intro":"A lighter sole, with no frying.","minutes":30,"calories":300,"difficulty":"Facile","imageSearch":"baked sole white wine","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"sole","plural":"soles","qty":2,"unit":"","have":false},{"name":"shallot","plural":"shallots","qty":2,"unit":"","have":false},{"name":"white wine","plural":"white wine","qty":10,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Scatter chopped shallots in a dish and lay the soles on top.","timer":null},{"text":"Pour over the white wine and dot with the butter.","timer":null},{"text":"Bake for 15 min.","timer":{"label":"Oven","min":15}},{"text":"Squeeze over the lemon juice and sprinkle with parsley.","timer":null}],"variant":"Oven-baked","change":"Baked in the oven with white wine and shallots."}]$r$::jsonb, 'claude')
