insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:truite aux amande', 'Trout with almonds', array['en:trout with almond', 'en:trout amandine', 'en:baked trout']::text[], 'dish', $r$[{"title":"Trout with almonds","intro":"Trout fried golden in butter with toasted flaked almonds.","minutes":25,"calories":450,"difficulty":"Facile","imageSearch":"trout almonds","veg":false,"oven":false,"cold":false,"missing":"","origin":"French classic","serves":4,"items":[{"name":"trout","plural":"trout","qty":4,"unit":"","have":false},{"name":"flaked almond","plural":"flaked almonds","qty":60,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":3,"unit":"tbsp","have":false},{"name":"butter","plural":"butter","qty":60,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false}],"steps":[{"text":"Dust the trout lightly with flour.","timer":null},{"text":"Fry them for 5 min on each side in 40 g of butter.","timer":{"label":"Pan","min":10}},{"text":"Take them out and toast the almonds in the rest of the butter.","timer":{"label":"Pan","min":2}},{"text":"Add the lemon juice and pour over the trout with the parsley.","timer":null}],"variant":"The classic","change":""},{"title":"Trout in a parcel","intro":"A light, fragrant trout cooked in a parcel.","minutes":30,"calories":320,"difficulty":"Facile","imageSearch":"trout en papillote","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"trout","plural":"trout","qty":4,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":2,"unit":"","have":false},{"name":"dill","plural":"dill","qty":null,"unit":"","have":false},{"name":"shallot","plural":"shallots","qty":2,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Put each trout on a sheet of baking paper with lemon slices, shallot and dill.","timer":null},{"text":"Drizzle with oil, add salt and pepper, and close the parcels.","timer":null},{"text":"Bake for 20 min.","timer":{"label":"Oven","min":20}}],"variant":"In a parcel","change":"Baked in the oven in a parcel with lemon and herbs."},{"title":"Trout fillets in cream sauce","intro":"Boneless fillets covered in a light cream sauce.","minutes":20,"calories":380,"difficulty":"Facile","imageSearch":"trout fillet cream sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"trout fillet","plural":"trout fillets","qty":4,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":15,"unit":"cl","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"chive","plural":"chives","qty":null,"unit":"","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false}],"steps":[{"text":"Fry the fillets skin side down for 4 min in the butter, then 1 min on the other side.","timer":{"label":"Pan","min":5}},{"text":"Take them out and pour the cream and the lemon juice into the pan.","timer":null},{"text":"Let it reduce for 2 min.","timer":null},{"text":"Spoon the sauce over the fillets and sprinkle with chives.","timer":null}],"variant":"Fillets","change":"Trout fillets with a lemon cream sauce."}]$r$::jsonb, 'claude')
