insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:calamar a la romaine', 'Fried calamari', array['en:fried calamari', 'en:calamari', 'en:calamari ring', 'en:squid ring', 'en:fritto misto']::text[], 'dish', $r$[{"title":"Fried calamari","intro":"Crispy battered squid rings, served with lemon.","minutes":30,"calories":380,"difficulty":"Moyen","imageSearch":"fried calamari rings","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"calamari ring","plural":"calamari rings","qty":500,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":100,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"sparkling water","plural":"sparkling water","qty":15,"unit":"cl","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"frying oil","plural":"frying oil","qty":100,"unit":"cl","have":false}],"steps":[{"text":"Mix the flour, the egg and the very cold sparkling water into a smooth batter.","timer":null},{"text":"Dry the calamari well with kitchen paper.","timer":null},{"text":"Dip them in the batter.","timer":null},{"text":"Fry them for 2 to 3 min in the hot oil.","timer":{"label":"Frying","min":3}},{"text":"Drain, add salt and serve with lemon wedges.","timer":null}],"variant":"The classic","change":""},{"title":"Garlic and parsley calamari","intro":"Quick pan-fried calamari with garlic and parsley.","minutes":20,"calories":220,"difficulty":"Facile","imageSearch":"garlic sauteed calamari","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"calamari ring","plural":"calamari rings","qty":500,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false}],"steps":[{"text":"Dry the calamari well.","timer":null},{"text":"Fry them for 3 min over a very high heat in the oil.","timer":{"label":"Pan","min":3}},{"text":"Add the chopped garlic and the parsley, and cook for 1 min.","timer":null},{"text":"Squeeze over the lemon juice.","timer":null}],"variant":"Pan-fried","change":"Pan-fried, with no deep frying."},{"title":"Calamari in tomato sauce","intro":"Tender squid in a tomato sauce.","minutes":50,"calories":280,"difficulty":"Facile","imageSearch":"calamari tomato stew","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"calamari ring","plural":"calamari rings","qty":600,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"white wine","plural":"white wine","qty":10,"unit":"cl","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion and the garlic.","timer":null},{"text":"Add the calamari and fry them for 3 min.","timer":null},{"text":"Add the wine and the tomatoes, and simmer for 35 min.","timer":{"label":"Cooking","min":35}},{"text":"Sprinkle with parsley and serve with rice or pasta.","timer":null}],"variant":"In tomato sauce","change":"Simmered in a tomato sauce."}]$r$::jsonb, 'claude')
