insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:saint jacque poelee', 'Pan-seared scallops', array['en:pan seared scallop', 'en:scallop', 'en:coquille saint jacque', 'en:seared scallop']::text[], 'dish', $r$[{"title":"Pan-seared scallops","intro":"Scallops seared in butter, golden outside and pearly inside.","minutes":15,"calories":250,"difficulty":"Moyen","imageSearch":"seared scallops","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"scallop","plural":"scallops","qty":16,"unit":"","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Dry the scallops well on kitchen paper.","timer":null},{"text":"Heat the butter until it foams.","timer":null},{"text":"Sear the scallops for 1 min 30 on each side without moving them.","timer":{"label":"Pan","min":3}},{"text":"Squeeze over the lemon juice, add salt and sprinkle with parsley.","timer":null}],"variant":"The classic","change":""},{"title":"Scallops in cream sauce","intro":"Scallops covered in a delicate cream sauce.","minutes":20,"calories":350,"difficulty":"Moyen","imageSearch":"scallops cream sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"scallop","plural":"scallops","qty":16,"unit":"","have":false},{"name":"shallot","plural":"shallots","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"white wine","plural":"white wine","qty":5,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false}],"steps":[{"text":"Sear the scallops for 1 min 30 on each side in the butter and take them out.","timer":{"label":"Pan","min":3}},{"text":"Fry the shallots, then add the white wine.","timer":null},{"text":"Add the cream and let it reduce for 3 min.","timer":{"label":"Cooking","min":3}},{"text":"Put the scallops back in the sauce for 30 seconds.","timer":null}],"variant":"In cream sauce","change":"With a shallot cream sauce."},{"title":"Scallops au gratin","intro":"The baked scallop shells served at festive meals.","minutes":40,"calories":380,"difficulty":"Moyen","imageSearch":"coquilles saint jacques gratinees","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"scallop","plural":"scallops","qty":12,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":150,"unit":"g","have":false},{"name":"shallot","plural":"shallots","qty":1,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"breadcrumb","plural":"breadcrumbs","qty":2,"unit":"tbsp","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to its grill setting.","timer":null},{"text":"Fry the shallot and the sliced mushrooms for 5 min.","timer":{"label":"Pan","min":5}},{"text":"Add the cream and let it reduce for 3 min.","timer":null},{"text":"Cut the scallops in half and share them between 4 shells. Spoon over the sauce.","timer":null},{"text":"Sprinkle with breadcrumbs and dot with butter. Grill for 6 min.","timer":{"label":"Oven","min":6}}],"variant":"Au gratin","change":"In shells, with a sauce and breadcrumbs."}]$r$::jsonb, 'claude')
