insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:curry de poisson', 'Fish curry', array['en:fish curry', 'en:coconut fish curry', 'en:fish and coconut curry']::text[], 'dish', $r$[{"title":"Coconut fish curry","intro":"White fish simmered in a coconut curry sauce, served with rice.","minutes":30,"calories":420,"difficulty":"Facile","imageSearch":"fish coconut curry","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"white fish fillet","plural":"white fish fillets","qty":600,"unit":"g","have":false},{"name":"coconut milk","plural":"coconut milk","qty":40,"unit":"cl","have":false},{"name":"tomato","plural":"tomatoes","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"curry powder","plural":"curry powder","qty":2,"unit":"tsp","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Fry the onion with the curry powder and the ginger.","timer":null},{"text":"Add the diced tomatoes and the coconut milk, and cook for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Add the fish in big pieces and cook for 6 min without stirring too much.","timer":{"label":"Cooking","min":6}},{"text":"Sprinkle with coriander.","timer":null}],"variant":"The classic","change":""},{"title":"Fish and prawn curry","intro":"A richer seafood curry.","minutes":30,"calories":450,"difficulty":"Facile","imageSearch":"fish shrimp curry","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"white fish fillet","plural":"white fish fillets","qty":400,"unit":"g","have":false},{"name":"peeled prawn","plural":"peeled prawns","qty":200,"unit":"g","have":false},{"name":"coconut milk","plural":"coconut milk","qty":40,"unit":"cl","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"curry powder","plural":"curry powder","qty":2,"unit":"tsp","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Fry the onion with the curry powder, then add the coconut milk.","timer":null},{"text":"Add the fish and the prawns, and cook for 6 min.","timer":{"label":"Cooking","min":6}},{"text":"Serve with the rice.","timer":null}],"variant":"With prawns","change":"With some prawns added."},{"title":"Tomato fish curry","intro":"A lighter fish curry made with tomato.","minutes":30,"calories":320,"difficulty":"Facile","imageSearch":"fish tomato curry","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"white fish fillet","plural":"white fish fillets","qty":600,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"curry powder","plural":"curry powder","qty":2,"unit":"tsp","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Fry the onion, the garlic and the curry powder.","timer":null},{"text":"Add the tomatoes and cook for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Add the fish and cook for 6 min.","timer":{"label":"Cooking","min":6}}],"variant":"No coconut","change":"A spicy tomato sauce, with no coconut milk."}]$r$::jsonb, 'claude')
