insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:rillette de thon', 'Tuna rillettes', array['en:tuna rillette', 'en:fish rillette', 'en:sardine rillette', 'en:salmon rillette', 'en:tuna spread']::text[], 'dish', $r$[{"title":"Tuna rillettes","intro":"Tuna mashed with soft cheese and lemon, to spread on toast with drinks.","minutes":10,"calories":180,"difficulty":"Facile","imageSearch":"tuna rillettes","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"tuna in brine","plural":"tuna in brine","qty":280,"unit":"g","have":false},{"name":"soft cheese","plural":"soft cheese","qty":150,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"chive","plural":"chives","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Drain the tuna.","timer":null},{"text":"Mash it with a fork and the soft cheese.","timer":null},{"text":"Add the lemon juice, the chopped chives and some pepper.","timer":null},{"text":"Keep it cold and serve with toasted bread.","timer":null}],"variant":"The classic","change":""},{"title":"Sardine rillettes","intro":"Sardine rillettes with butter and lemon.","minutes":10,"calories":220,"difficulty":"Facile","imageSearch":"sardine rillettes","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"sardine in oil","plural":"sardines in oil","qty":2,"unit":"","have":false},{"name":"soft cheese","plural":"soft cheese","qty":100,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"shallot","plural":"shallots","qty":1,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false}],"steps":[{"text":"Drain the sardines and remove the central bone.","timer":null},{"text":"Mash them with the soft cheese.","timer":null},{"text":"Add the lemon juice, the chopped shallot and the parsley.","timer":null},{"text":"Keep it cold.","timer":null}],"variant":"Sardines","change":"Made with sardines in oil."},{"title":"Salmon rillettes","intro":"The salmon rillettes served with drinks at parties.","minutes":25,"calories":220,"difficulty":"Facile","imageSearch":"salmon rillettes","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"salmon fillet","plural":"salmon fillets","qty":1,"unit":"","have":false},{"name":"smoked salmon","plural":"smoked salmon","qty":2,"unit":"slices","have":false},{"name":"soft cheese","plural":"soft cheese","qty":150,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"dill","plural":"dill","qty":null,"unit":"","have":false}],"steps":[{"text":"Steam the salmon for 8 min and let it cool.","timer":{"label":"Cooking","min":8}},{"text":"Flake it and cut the smoked salmon into small pieces.","timer":null},{"text":"Mix with the soft cheese, the lemon juice and the dill.","timer":null},{"text":"Chill for 1 h.","timer":null}],"variant":"Salmon","change":"Made with fresh salmon and smoked salmon."}]$r$::jsonb, 'claude')
