insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:steak de thon', 'Tuna steak', array['en:tuna steak', 'en:seared tuna', 'en:grilled tuna', 'en:fresh tuna']::text[], 'dish', $r$[{"title":"Sesame-seared tuna steak","intro":"Tuna seared in sesame seeds, pink in the middle, with a soy sauce.","minutes":15,"calories":320,"difficulty":"Moyen","imageSearch":"seared tuna steak sesame","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"tuna steak","plural":"tuna steaks","qty":4,"unit":"","have":false},{"name":"sesame seed","plural":"sesame seeds","qty":4,"unit":"tbsp","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false},{"name":"lime","plural":"limes","qty":1,"unit":"","have":false},{"name":"oil","plural":"oil","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Coat the steaks in sesame seeds.","timer":null},{"text":"Sear them for 1 min on each side over a very high heat.","timer":{"label":"Pan","min":2}},{"text":"Cut them into slices.","timer":null},{"text":"Serve with the soy sauce mixed with the lime juice.","timer":null}],"variant":"The classic","change":""},{"title":"Provençal tuna","intro":"Tuna simmered with tomato, olives and capers.","minutes":30,"calories":350,"difficulty":"Facile","imageSearch":"tuna provencal tomato","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"tuna steak","plural":"tuna steaks","qty":4,"unit":"","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"black olive","plural":"black olives","qty":60,"unit":"g","have":false},{"name":"caper","plural":"capers","qty":1,"unit":"tbsp","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false}],"steps":[{"text":"Fry the onion and the garlic.","timer":null},{"text":"Add the tomatoes, the olives and the capers, and cook for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Sear the tuna for 1 min on each side, then add it to the sauce.","timer":null},{"text":"Cover and cook for 5 min.","timer":{"label":"Cooking","min":5}}],"variant":"In tomato sauce","change":"Cooked in a tomato sauce with olives."},{"title":"Grilled tuna with mango","intro":"A fresh, exotic grilled tuna.","minutes":20,"calories":380,"difficulty":"Facile","imageSearch":"grilled tuna mango salsa","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"tuna steak","plural":"tuna steaks","qty":4,"unit":"","have":false},{"name":"mango","plural":"mangoes","qty":1,"unit":"","have":false},{"name":"avocado","plural":"avocados","qty":1,"unit":"","have":false},{"name":"red onion","plural":"red onions","qty":0.5,"unit":"","have":false},{"name":"lime","plural":"limes","qty":1,"unit":"","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the mango, the avocado and the onion into small cubes.","timer":null},{"text":"Mix with the lime juice and the coriander.","timer":null},{"text":"Grill the tuna for 2 min on each side.","timer":{"label":"Pan","min":4}},{"text":"Serve with the salsa.","timer":null}],"variant":"With mango","change":"With a mango and avocado salsa."}]$r$::jsonb, 'claude')
