insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:lotte a l armoricaine', 'Monkfish armoricaine', array['en:monkfish armoricaine', 'en:monkfish', 'en:armoricaine sauce']::text[], 'dish', $r$[{"title":"Monkfish armoricaine","intro":"Monkfish in a tomato sauce with white wine and cognac, Breton style.","minutes":45,"calories":380,"difficulty":"Moyen","imageSearch":"monkfish armoricaine","veg":false,"oven":false,"cold":false,"missing":"","origin":"Breton speciality","serves":4,"items":[{"name":"monkfish","plural":"monkfish","qty":800,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"shallot","plural":"shallots","qty":3,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"white wine","plural":"white wine","qty":20,"unit":"cl","have":false},{"name":"cognac","plural":"cognac","qty":3,"unit":"tbsp","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Cut the monkfish into medallions and brown them for 3 min. Flambé with the cognac.","timer":{"label":"Pan","min":3}},{"text":"Take out the monkfish and fry the shallots and the garlic.","timer":null},{"text":"Add the wine and the tomatoes, and let it reduce for 15 min.","timer":{"label":"Cooking","min":15}},{"text":"Add the cream, put the monkfish back and cook for 8 min.","timer":{"label":"Cooking","min":8}}],"variant":"The classic","change":""},{"title":"Monkfish in saffron cream","intro":"Monkfish medallions in a golden saffron sauce.","minutes":35,"calories":400,"difficulty":"Moyen","imageSearch":"monkfish saffron cream","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"monkfish","plural":"monkfish","qty":800,"unit":"g","have":false},{"name":"shallot","plural":"shallots","qty":2,"unit":"","have":false},{"name":"white wine","plural":"white wine","qty":10,"unit":"cl","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"saffron","plural":"saffron","qty":null,"unit":"","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false}],"steps":[{"text":"Brown the monkfish medallions in the butter and take them out.","timer":{"label":"Pan","min":4}},{"text":"Fry the shallots, then add the white wine.","timer":null},{"text":"Add the cream and the saffron, and let it reduce for 5 min.","timer":{"label":"Cooking","min":5}},{"text":"Put the monkfish back and cook for 6 min.","timer":{"label":"Cooking","min":6}}],"variant":"Saffron","change":"A saffron cream sauce, with no tomato."},{"title":"Cod armoricaine","intro":"Armoricaine sauce made with cod, which is cheaper.","minutes":35,"calories":340,"difficulty":"Facile","imageSearch":"cod tomato wine sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cod fillet","plural":"cod fillets","qty":4,"unit":"","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"shallot","plural":"shallots","qty":2,"unit":"","have":false},{"name":"white wine","plural":"white wine","qty":15,"unit":"cl","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false}],"steps":[{"text":"Fry the shallots, then add the wine and the tomatoes.","timer":null},{"text":"Let it reduce for 15 min.","timer":{"label":"Cooking","min":15}},{"text":"Add the cream.","timer":null},{"text":"Put the cod in the sauce, cover and cook for 8 min.","timer":{"label":"Cooking","min":8}}],"variant":"Cod","change":"Cod replaces the monkfish."}]$r$::jsonb, 'claude')
