insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:sardine grillee', 'Grilled sardines', array['en:grilled sardine', 'en:sardine', 'en:baked sardine', 'en:plancha sardine']::text[], 'dish', $r$[{"title":"Grilled sardines","intro":"Fresh sardines grilled on a hot plate, with lemon and coarse salt.","minutes":20,"calories":320,"difficulty":"Facile","imageSearch":"grilled sardines","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"fresh sardine","plural":"fresh sardines","qty":16,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":2,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"coarse salt","plural":"coarse salt","qty":null,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false}],"steps":[{"text":"Gut and rinse the sardines, or ask the fishmonger to do it.","timer":null},{"text":"Brush them with oil.","timer":null},{"text":"Grill them for 3 min on each side on a hot plate or a very hot pan.","timer":{"label":"Pan","min":6}},{"text":"Serve with the coarse salt, the parsley and lemon wedges.","timer":null}],"variant":"The classic","change":""},{"title":"Baked sardines","intro":"Roast sardines on a bed of vegetables.","minutes":30,"calories":350,"difficulty":"Facile","imageSearch":"baked sardines tomatoes","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"fresh sardine","plural":"fresh sardines","qty":16,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":4,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Spread the sliced tomatoes, the onion and the garlic in a dish.","timer":null},{"text":"Lay the sardines on top, drizzle with oil and sprinkle with thyme.","timer":null},{"text":"Bake for 15 min.","timer":{"label":"Oven","min":15}}],"variant":"Oven-baked","change":"Baked in the oven on tomatoes and onions."},{"title":"Marinated sardine fillets","intro":"Marinated sardines to serve as a fresh starter.","minutes":20,"calories":240,"difficulty":"Moyen","imageSearch":"marinated sardine fillets","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"sardine fillet","plural":"sardine fillets","qty":16,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":3,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"shallot","plural":"shallots","qty":1,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false}],"steps":[{"text":"Lay the fillets in a dish, skin side down.","timer":null},{"text":"Pour over the lemon juice and leave for 1 h in the fridge.","timer":null},{"text":"Drain and drizzle with olive oil.","timer":null},{"text":"Sprinkle with chopped shallot and parsley.","timer":null}],"variant":"Marinated","change":"Raw fillets marinated in lemon."}]$r$::jsonb, 'claude')
