insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:filet de colin', 'Pollock fillet', array['en:pollock fillet', 'en:pollock', 'en:baked pollock', 'en:hake', 'en:pollock in cream sauce']::text[], 'dish', $r$[{"title":"Pollock in cream sauce","intro":"Pollock fillets cooked gently in a lemon cream sauce.","minutes":25,"calories":320,"difficulty":"Facile","imageSearch":"hake fillet cream sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pollock fillet","plural":"pollock fillets","qty":4,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"shallot","plural":"shallots","qty":1,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"rice","plural":"rice","qty":200,"unit":"g","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Fry the shallot, then add the cream and the lemon zest.","timer":null},{"text":"Lay the fillets in the sauce, cover and cook for 8 min over a low heat.","timer":{"label":"Cooking","min":8}},{"text":"Squeeze over the lemon juice and sprinkle with parsley.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Baked pollock with vegetables","intro":"A complete dish of roast pollock with courgettes and tomatoes.","minutes":35,"calories":280,"difficulty":"Facile","imageSearch":"baked hake vegetables","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pollock fillet","plural":"pollock fillets","qty":4,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"cherry tomato","plural":"cherry tomatoes","qty":250,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"herbes de provence","plural":"herbes de provence","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Put the sliced courgettes and the tomatoes in a dish with the oil and the herbs.","timer":null},{"text":"Bake for 15 min.","timer":{"label":"Oven","min":15}},{"text":"Add the pollock, squeeze over the lemon and bake for another 12 min.","timer":{"label":"Oven","min":12}}],"variant":"Oven-baked","change":"Baked in the oven with vegetables."},{"title":"Breaded pollock","intro":"Homemade fish fingers that kids love.","minutes":25,"calories":380,"difficulty":"Facile","imageSearch":"breaded hake fillet","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pollock fillet","plural":"pollock fillets","qty":4,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"breadcrumb","plural":"breadcrumbs","qty":80,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":3,"unit":"tbsp","have":false},{"name":"oil","plural":"oil","qty":4,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false}],"steps":[{"text":"Dip the fillets in the flour, then the beaten egg, then the breadcrumbs.","timer":null},{"text":"Fry them for 4 min on each side in the oil until golden.","timer":{"label":"Pan","min":8}},{"text":"Drain on kitchen paper.","timer":null},{"text":"Serve with lemon wedges.","timer":null}],"kids":true,"variant":"Breaded","change":"Breaded fillets fried golden in a pan."}]$r$::jsonb, 'claude')
