insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:tofu saute', 'Stir-fried tofu', array['en:stir fried tofu', 'en:crispy tofu', 'en:pan fried tofu', 'en:tofu stir fry']::text[], 'dish', $r$[{"title":"Stir-fried tofu with vegetables","intro":"Crispy golden tofu stir-fried with vegetables in a soy and ginger sauce.","minutes":25,"calories":350,"difficulty":"Facile","imageSearch":"crispy tofu stir fry","veg":true,"oven":false,"cold":false,"missing":"","origin":"Asian-inspired","serves":4,"items":[{"name":"firm tofu","plural":"firm tofu","qty":400,"unit":"g","have":false},{"name":"cornflour","plural":"cornflour","qty":2,"unit":"tbsp","have":false},{"name":"broccoli","plural":"broccoli","qty":1,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"oil","plural":"oil","qty":3,"unit":"tbsp","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Cut the tofu into cubes, pat it dry and roll it in the cornflour.","timer":null},{"text":"Fry it for 8 min in the hot oil until golden, then take it out.","timer":{"label":"Pan","min":8}},{"text":"Stir-fry the broccoli and the pepper for 5 min.","timer":{"label":"Pan","min":5}},{"text":"Put the tofu back in with the soy sauce and the ginger, and stir for 1 min.","timer":null}],"variant":"The classic","change":""},{"title":"Caramelised tofu","intro":"Vietnamese-style tofu, sweet and salty.","minutes":25,"calories":380,"difficulty":"Facile","imageSearch":"caramelized tofu","veg":true,"oven":false,"cold":false,"missing":"","origin":"Vietnamese-inspired","serves":4,"items":[{"name":"firm tofu","plural":"firm tofu","qty":400,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":3,"unit":"tbsp","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"spring onion","plural":"spring onions","qty":3,"unit":"","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Fry the cubed tofu in a pan until golden.","timer":{"label":"Pan","min":8}},{"text":"Make a caramel with the sugar, then add the soy sauce, the garlic and 5 cl of water.","timer":null},{"text":"Add the tofu and let it reduce until it is glazed. Sprinkle with spring onion.","timer":null}],"variant":"Caramelised","change":"Glazed in a soy caramel sauce."},{"title":"Tofu curry","intro":"A mild tofu curry with coconut milk.","minutes":25,"calories":420,"difficulty":"Facile","imageSearch":"tofu coconut curry","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"firm tofu","plural":"firm tofu","qty":400,"unit":"g","have":false},{"name":"coconut milk","plural":"coconut milk","qty":40,"unit":"cl","have":false},{"name":"curry powder","plural":"curry powder","qty":2,"unit":"tsp","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"baby spinach","plural":"baby spinach","qty":100,"unit":"g","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Fry the cubed tofu until golden and take it out.","timer":{"label":"Pan","min":8}},{"text":"Fry the onion with the curry powder, add the coconut milk and cook for 5 min.","timer":{"label":"Cooking","min":5}},{"text":"Add the tofu and the spinach, and cook for 3 min.","timer":null}],"variant":"Curry","change":"Simmered in a coconut curry sauce."}]$r$::jsonb, 'claude')
