insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:epinard a la creme', 'Creamed spinach', array['en:creamed spinach', 'en:spinach in cream', 'en:spinach cream']::text[], 'dish', $r$[{"title":"Creamed spinach","intro":"Spinach cooked down in cream and nutmeg, to serve as a side.","minutes":15,"calories":150,"difficulty":"Facile","imageSearch":"creamed spinach","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"baby spinach","plural":"baby spinach","qty":600,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":15,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":15,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"nutmeg","plural":"nutmeg","qty":null,"unit":"","have":false}],"steps":[{"text":"Melt the chopped garlic in the butter.","timer":null},{"text":"Add the spinach a handful at a time and let it wilt for 3 min.","timer":{"label":"Pan","min":3}},{"text":"Add the cream and the nutmeg.","timer":null},{"text":"Let it reduce for 3 min, then add salt and pepper.","timer":{"label":"Cooking","min":3}}],"kids":true,"variant":"The classic","change":""},{"title":"Creamed spinach with eggs","intro":"A complete dish of creamed spinach with baked eggs.","minutes":20,"calories":280,"difficulty":"Facile","imageSearch":"creamed spinach eggs","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"frozen spinach","plural":"frozen spinach","qty":600,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":15,"unit":"cl","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"nutmeg","plural":"nutmeg","qty":null,"unit":"","have":false}],"steps":[{"text":"Heat the spinach with the garlic.","timer":{"label":"Pan","min":8}},{"text":"Add the cream and the nutmeg.","timer":null},{"text":"Make 4 wells and crack an egg into each.","timer":null},{"text":"Cover and cook for 5 min.","timer":{"label":"Cooking","min":5}}],"variant":"With eggs","change":"Eggs cooked in the middle of the spinach."},{"title":"Spinach gratin","intro":"Creamed spinach baked with emmental.","minutes":30,"calories":240,"difficulty":"Facile","imageSearch":"spinach gratin","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"frozen spinach","plural":"frozen spinach","qty":600,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"grated emmental","plural":"grated emmental","qty":80,"unit":"g","have":false},{"name":"nutmeg","plural":"nutmeg","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Defrost the spinach and squeeze it dry.","timer":null},{"text":"Mix with the cream, the egg and the nutmeg, and pour into a dish.","timer":null},{"text":"Cover with the emmental and bake for 20 min.","timer":{"label":"Oven","min":20}}],"kids":true,"variant":"Baked","change":"Baked in the oven with cheese."}]$r$::jsonb, 'claude')
