insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:haricot vert a l ail', 'Garlic green beans', array['en:garlic green bean', 'en:sauteed green bean', 'en:green bean with garlic', 'en:pan fried green bean']::text[], 'dish', $r$[{"title":"Garlic green beans","intro":"Crunchy green beans sautéed in butter with garlic and parsley.","minutes":20,"calories":100,"difficulty":"Facile","imageSearch":"garlic green beans","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"green bean","plural":"green beans","qty":600,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Trim the beans and boil them for 8 min in salted water.","timer":{"label":"Cooking","min":8}},{"text":"Drain them and rinse in cold water.","timer":null},{"text":"Sauté them for 3 min in the butter with the chopped garlic.","timer":{"label":"Pan","min":3}},{"text":"Sprinkle with parsley.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Green beans with bacon","intro":"Richer green beans with bacon.","minutes":25,"calories":200,"difficulty":"Facile","imageSearch":"green beans bacon","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"green bean","plural":"green beans","qty":600,"unit":"g","have":false},{"name":"bacon lardon","plural":"bacon lardons","qty":125,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false}],"steps":[{"text":"Boil the beans for 8 min in salted water.","timer":{"label":"Cooking","min":8}},{"text":"Fry the bacon and the sliced onion until golden.","timer":{"label":"Pan","min":6}},{"text":"Add the drained beans.","timer":null},{"text":"Sauté for 3 min.","timer":null}],"kids":true,"variant":"With bacon","change":"With bacon lardons and onions."},{"title":"Green beans with almonds","intro":"Crunchy green beans with almonds.","minutes":20,"calories":150,"difficulty":"Facile","imageSearch":"green beans almondine","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"green bean","plural":"green beans","qty":600,"unit":"g","have":false},{"name":"flaked almond","plural":"flaked almonds","qty":40,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":0.5,"unit":"","have":false}],"steps":[{"text":"Boil the beans for 8 min in salted water.","timer":{"label":"Cooking","min":8}},{"text":"Toast the almonds in a dry pan.","timer":{"label":"Pan","min":2}},{"text":"Add the butter and the beans, and sauté for 3 min.","timer":null},{"text":"Squeeze over a little lemon juice.","timer":null}],"variant":"With almonds","change":"With toasted flaked almonds."}]$r$::jsonb, 'claude')
