insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:petit poi carotte', 'Peas and carrots', array['en:pea and carrot', 'en:buttered pea and carrot', 'en:french style pea']::text[], 'dish', $r$[{"title":"Peas and carrots","intro":"Tender peas and carrots cooked with onion and butter.","minutes":30,"calories":150,"difficulty":"Facile","imageSearch":"peas and carrots","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"frozen pea","plural":"frozen peas","qty":500,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":4,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Soften the sliced onion in the butter.","timer":null},{"text":"Add the sliced carrots, the sugar and 15 cl of water, and cook for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Add the peas and cook for 10 min with the lid on.","timer":{"label":"Cooking","min":10}},{"text":"Add salt and pepper.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"French-style peas","intro":"Old-fashioned braised peas with lettuce.","minutes":30,"calories":170,"difficulty":"Facile","imageSearch":"french style peas lettuce","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"frozen pea","plural":"frozen peas","qty":500,"unit":"g","have":false},{"name":"lettuce","plural":"lettuces","qty":1,"unit":"","have":false},{"name":"pearl onion","plural":"pearl onions","qty":8,"unit":"","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Fry the pearl onions in the butter.","timer":null},{"text":"Add the shredded lettuce, the peas, the sugar and 10 cl of water.","timer":null},{"text":"Cover and cook for 15 min.","timer":{"label":"Cooking","min":15}},{"text":"Add salt and pepper.","timer":null}],"variant":"French style","change":"With lettuce and small onions."},{"title":"Peas with bacon","intro":"Richer peas and carrots with bacon.","minutes":30,"calories":240,"difficulty":"Facile","imageSearch":"peas carrots bacon","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"frozen pea","plural":"frozen peas","qty":500,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"bacon lardon","plural":"bacon lardons","qty":125,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false}],"steps":[{"text":"Fry the bacon and the onion until golden.","timer":{"label":"Pan","min":5}},{"text":"Add the carrots and 15 cl of water, and cook for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Add the peas and cook for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Add pepper and serve.","timer":null}],"kids":true,"variant":"With bacon","change":"With bacon lardons."}]$r$::jsonb, 'claude')
