insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:butternut rotie', 'Roasted butternut squash', array['en:roasted butternut squash', 'en:roast butternut squash', 'en:baked butternut squash', 'en:roasted squash']::text[], 'dish', $r$[{"title":"Roasted butternut squash","intro":"Butternut squash roasted in the oven with honey, thyme and olive oil.","minutes":50,"calories":180,"difficulty":"Facile","imageSearch":"roasted butternut squash","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"butternut squash","plural":"butternut squashes","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"honey","plural":"honey","qty":1,"unit":"tbsp","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Peel the squash, remove the seeds and cut it into cubes.","timer":null},{"text":"Mix with the oil, the honey, the thyme and the salt.","timer":null},{"text":"Bake for 40 min, stirring halfway through.","timer":{"label":"Oven","min":40}}],"variant":"The classic","change":""},{"title":"Stuffed butternut squash","intro":"Baked butternut squash halves stuffed with goat's cheese and walnuts.","minutes":70,"calories":350,"difficulty":"Facile","imageSearch":"stuffed butternut squash","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"butternut squash","plural":"butternut squashes","qty":2,"unit":"","have":false},{"name":"goat's cheese log","plural":"goat's cheese logs","qty":1,"unit":"","have":false},{"name":"walnut half","plural":"walnut halves","qty":40,"unit":"g","have":false},{"name":"honey","plural":"honey","qty":2,"unit":"tbsp","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Cut the squashes in half and remove the seeds.","timer":null},{"text":"Bake them for 40 min, cut side up.","timer":{"label":"Oven","min":40}},{"text":"Top with slices of goat's cheese, the walnuts and the thyme.","timer":null},{"text":"Drizzle with honey and put back in the oven for 15 min.","timer":{"label":"Oven","min":15}}],"variant":"Stuffed","change":"Cut in half and stuffed with cheese."},{"title":"Spiced roasted butternut squash","intro":"A spiced butternut squash that becomes a full meal with chickpeas.","minutes":50,"calories":320,"difficulty":"Facile","imageSearch":"spiced roasted squash chickpeas","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"butternut squash","plural":"butternut squashes","qty":1,"unit":"","have":false},{"name":"chickpea","plural":"chickpeas","qty":400,"unit":"g","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"greek yoghurt","plural":"greek yoghurts","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Cut the squash into cubes and mix with the chickpeas, the spices and the oil.","timer":null},{"text":"Bake for 40 min.","timer":{"label":"Oven","min":40}},{"text":"Serve with the yoghurt.","timer":null}],"variant":"Spiced","change":"With cumin, paprika and chickpeas."}]$r$::jsonb, 'claude')
