insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:champignon farci', 'Stuffed mushrooms', array['en:stuffed mushroom', 'en:baked stuffed mushroom']::text[], 'dish', $r$[{"title":"Stuffed mushrooms","intro":"Big mushrooms stuffed with garlic, parsley and soft cheese, then baked until golden.","minutes":30,"calories":180,"difficulty":"Facile","imageSearch":"stuffed mushrooms","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"button mushroom","plural":"button mushrooms","qty":12,"unit":"","have":false},{"name":"garlic and herb soft cheese","plural":"garlic and herb soft cheese","qty":150,"unit":"g","have":false},{"name":"breadcrumb","plural":"breadcrumbs","qty":2,"unit":"tbsp","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Remove the mushroom stalks.","timer":null},{"text":"Fill the caps with soft cheese and sprinkle with breadcrumbs.","timer":null},{"text":"Drizzle with oil and bake for 15 min.","timer":{"label":"Oven","min":15}},{"text":"Sprinkle with parsley.","timer":null}],"makes":{"n":12,"one":"stuffed mushroom","many":"stuffed mushrooms"},"variant":"The classic","change":""},{"title":"Sausage-stuffed mushrooms","intro":"Rich stuffed mushrooms with meat.","minutes":35,"calories":280,"difficulty":"Facile","imageSearch":"sausage stuffed mushrooms","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"button mushroom","plural":"button mushrooms","qty":12,"unit":"","have":false},{"name":"sausage meat","plural":"sausage meat","qty":250,"unit":"g","have":false},{"name":"shallot","plural":"shallots","qty":1,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"breadcrumb","plural":"breadcrumbs","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Chop the mushroom stalks and mix them with the sausage meat, the shallot and the parsley.","timer":null},{"text":"Stuff the caps and sprinkle with breadcrumbs.","timer":null},{"text":"Bake for 20 min.","timer":{"label":"Oven","min":20}}],"makes":{"n":12,"one":"stuffed mushroom","many":"stuffed mushrooms"},"variant":"With meat","change":"Stuffed with sausage meat."},{"title":"Goat's cheese stuffed mushrooms","intro":"Stuffed mushrooms with melting goat's cheese.","minutes":25,"calories":200,"difficulty":"Facile","imageSearch":"goat cheese stuffed mushrooms","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"button mushroom","plural":"button mushrooms","qty":12,"unit":"","have":false},{"name":"goat's cheese log","plural":"goat's cheese logs","qty":1,"unit":"","have":false},{"name":"honey","plural":"honey","qty":1,"unit":"tbsp","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Remove the mushroom stalks.","timer":null},{"text":"Put a slice of goat's cheese in each cap, with a little thyme and honey.","timer":null},{"text":"Bake for 15 min.","timer":{"label":"Oven","min":15}}],"makes":{"n":12,"one":"stuffed mushroom","many":"stuffed mushrooms"},"variant":"With goat's cheese","change":"With goat's cheese and honey."}]$r$::jsonb, 'claude')
