insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:poireau vinaigrette', 'Leeks vinaigrette', array['en:leek vinaigrette', 'en:leek in vinaigrette', 'en:leek with mustard dressing']::text[], 'dish', $r$[{"title":"Leeks vinaigrette","intro":"Tender leeks in a mustard vinaigrette, topped with grated egg.","minutes":30,"calories":200,"difficulty":"Facile","imageSearch":"leeks vinaigrette","veg":true,"oven":false,"cold":true,"missing":"","origin":"French bistro dish","serves":4,"items":[{"name":"leek","plural":"leeks","qty":6,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tbsp","have":false},{"name":"vinegar","plural":"vinegar","qty":2,"unit":"tbsp","have":false},{"name":"oil","plural":"oil","qty":5,"unit":"tbsp","have":false},{"name":"shallot","plural":"shallots","qty":1,"unit":"","have":false}],"steps":[{"text":"Cut the leeks into chunks and boil them for 15 min in salted water.","timer":{"label":"Cooking","min":15}},{"text":"Boil the eggs for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Make the vinaigrette with the mustard, the vinegar, the oil and the chopped shallot.","timer":null},{"text":"Drain the leeks, pour over the vinaigrette and grate the eggs on top.","timer":null}],"variant":"The classic","change":""},{"title":"Leeks vinaigrette with hazelnuts","intro":"Crunchy leeks vinaigrette with hazelnuts.","minutes":25,"calories":230,"difficulty":"Facile","imageSearch":"leeks hazelnut dressing","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"leek","plural":"leeks","qty":6,"unit":"","have":false},{"name":"hazelnut","plural":"hazelnuts","qty":40,"unit":"g","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tbsp","have":false},{"name":"balsamic vinegar","plural":"balsamic vinegar","qty":2,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false}],"steps":[{"text":"Boil the leeks in chunks for 15 min.","timer":{"label":"Cooking","min":15}},{"text":"Toast the hazelnuts in a dry pan and crush them.","timer":{"label":"Pan","min":3}},{"text":"Make the vinaigrette.","timer":null},{"text":"Pour it over the leeks and sprinkle with hazelnuts.","timer":null}],"variant":"With hazelnuts","change":"With toasted hazelnuts."},{"title":"Grilled leeks","intro":"Grilled, caramelised leeks with a vinaigrette.","minutes":30,"calories":180,"difficulty":"Facile","imageSearch":"grilled leeks","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"leek","plural":"leeks","qty":6,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tsp","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the leeks in half and boil them for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Drain them and grill them in a pan for 5 min.","timer":{"label":"Pan","min":5}},{"text":"Mix the oil, the lemon juice and the mustard.","timer":null},{"text":"Pour over the leeks and sprinkle with parsley.","timer":null}],"variant":"Grilled","change":"Grilled in a pan after boiling."}]$r$::jsonb, 'claude')
