insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:asperge', 'Asparagus', array['en:asparagu', 'en:white asparagu', 'en:green asparagu', 'en:asparagu with mousseline sauce']::text[], 'dish', $r$[{"title":"Asparagus with mousseline sauce","intro":"Perfectly cooked white asparagus with a light mousseline sauce.","minutes":30,"calories":250,"difficulty":"Moyen","imageSearch":"white asparagus hollandaise","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"white asparagus","plural":"white asparagus","qty":1000,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"butter","plural":"butter","qty":80,"unit":"g","have":false},{"name":"single cream","plural":"single cream","qty":10,"unit":"cl","have":false},{"name":"lemon","plural":"lemons","qty":0.5,"unit":"","have":false}],"steps":[{"text":"Peel the asparagus and boil it for 15 min in salted water.","timer":{"label":"Cooking","min":15}},{"text":"Whisk the egg yolks with 2 tbsp of water over a pan of simmering water until thick.","timer":null},{"text":"Add the melted butter little by little, then the lemon juice.","timer":null},{"text":"Whip the cream and fold it into the sauce.","timer":null},{"text":"Serve the warm asparagus with the sauce.","timer":null}],"variant":"The classic","change":""},{"title":"Roasted green asparagus","intro":"Crunchy green asparagus roasted with parmesan.","minutes":20,"calories":150,"difficulty":"Facile","imageSearch":"roasted green asparagus parmesan","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"green asparagus","plural":"green asparagus","qty":500,"unit":"g","have":false},{"name":"parmesan","plural":"parmesan","qty":40,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Snap off the hard ends of the asparagus.","timer":null},{"text":"Drizzle with oil and bake for 12 min.","timer":{"label":"Oven","min":12}},{"text":"Sprinkle with parmesan and squeeze over the lemon.","timer":null}],"variant":"Roasted green","change":"Roasted in the oven with parmesan."},{"title":"Asparagus with a soft-boiled egg","intro":"A spring starter of asparagus, soft-boiled egg and cured ham.","minutes":20,"calories":280,"difficulty":"Facile","imageSearch":"asparagus soft boiled egg","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"green asparagus","plural":"green asparagus","qty":500,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"cured ham","plural":"cured ham","qty":4,"unit":"slices","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Boil the asparagus for 6 min in salted water.","timer":{"label":"Cooking","min":6}},{"text":"Boil the eggs for 6 min and peel them.","timer":{"label":"Cooking","min":6}},{"text":"Arrange the asparagus, ham and egg on each plate.","timer":null},{"text":"Drizzle with oil, then add salt and pepper.","timer":null}],"variant":"Soft-boiled egg","change":"With a soft-boiled egg and cured ham."}]$r$::jsonb, 'claude')
