insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:poi chiche roti', 'Roasted chickpeas', array['en:roasted chickpea', 'en:crispy chickpea', 'en:baked chickpea', 'en:oven roasted chickpea']::text[], 'dish', $r$[{"title":"Roasted chickpeas","intro":"Crispy paprika chickpeas, for nibbling with drinks or sprinkling on a salad.","minutes":40,"calories":180,"difficulty":"Facile","imageSearch":"roasted chickpeas","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chickpea","plural":"chickpeas","qty":400,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Rinse the chickpeas and dry them well in a tea towel.","timer":null},{"text":"Mix them with the oil, the spices and the salt.","timer":null},{"text":"Spread them on a tray and bake for 30 min, stirring now and then.","timer":{"label":"Oven","min":30}}],"variant":"The classic","change":""},{"title":"Honey roasted chickpeas","intro":"Sweet, crunchy chickpeas for a snack.","minutes":40,"calories":200,"difficulty":"Facile","imageSearch":"honey roasted chickpeas","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chickpea","plural":"chickpeas","qty":400,"unit":"g","have":false},{"name":"coconut oil","plural":"coconut oil","qty":1,"unit":"tbsp","have":false},{"name":"honey","plural":"honey","qty":2,"unit":"tbsp","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Dry the chickpeas and bake them for 20 min with the oil.","timer":{"label":"Oven","min":20}},{"text":"Mix them with the honey and the cinnamon.","timer":null},{"text":"Put them back in the oven for 10 min.","timer":{"label":"Oven","min":10}}],"dessert":true,"variant":"Sweet","change":"With honey and cinnamon."},{"title":"Chickpeas with spinach","intro":"A quick dish of chickpeas with spinach.","minutes":15,"calories":280,"difficulty":"Facile","imageSearch":"chickpeas spinach skillet","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chickpea","plural":"chickpeas","qty":800,"unit":"g","have":false},{"name":"baby spinach","plural":"baby spinach","qty":200,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Fry the garlic and the cumin in the oil.","timer":null},{"text":"Add the chickpeas and fry them for 5 min until golden.","timer":{"label":"Pan","min":5}},{"text":"Add the spinach and let it wilt.","timer":null},{"text":"Squeeze over the lemon juice.","timer":null}],"variant":"Pan-fried","change":"Pan-fried with spinach and garlic."}]$r$::jsonb, 'claude')
