insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:veloute de champignon', 'Mushroom soup', array['en:mushroom soup', 'en:cream of mushroom soup']::text[], 'dish', $r$[{"title":"Cream of mushroom soup","intro":"A creamy soup made with button mushrooms and shallots.","minutes":30,"calories":180,"difficulty":"Facile","imageSearch":"mushroom soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"button mushroom","plural":"button mushrooms","qty":500,"unit":"g","have":false},{"name":"shallot","plural":"shallots","qty":2,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":1,"unit":"","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false}],"steps":[{"text":"Fry the shallots and the sliced mushrooms in the butter for 5 min.","timer":{"label":"Pan","min":5}},{"text":"Add the diced potato, the stock cube and 70 cl of water.","timer":null},{"text":"Simmer for 20 min.","timer":{"label":"Cooking","min":20}},{"text":"Blend with the cream, then add salt and pepper.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Mushroom and chestnut soup","intro":"An autumn soup with mushrooms and chestnuts.","minutes":30,"calories":250,"difficulty":"Facile","imageSearch":"mushroom chestnut soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"button mushroom","plural":"button mushrooms","qty":400,"unit":"g","have":false},{"name":"cooked chestnut","plural":"cooked chestnuts","qty":200,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false}],"steps":[{"text":"Fry the onion and the mushrooms for 5 min.","timer":{"label":"Pan","min":5}},{"text":"Add the chestnuts, the stock cube and 80 cl of water.","timer":null},{"text":"Simmer for 20 min.","timer":{"label":"Cooking","min":20}},{"text":"Blend with the cream.","timer":null}],"variant":"With chestnuts","change":"With cooked chestnuts."},{"title":"Light mushroom soup","intro":"A lighter mushroom soup.","minutes":30,"calories":110,"difficulty":"Facile","imageSearch":"light mushroom soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"button mushroom","plural":"button mushrooms","qty":500,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"semi-skimmed milk","plural":"semi-skimmed milk","qty":20,"unit":"cl","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the onion and the mushrooms in a little water for 5 min.","timer":{"label":"Cooking","min":5}},{"text":"Add the stock cube and 60 cl of water, and simmer for 20 min.","timer":{"label":"Cooking","min":20}},{"text":"Blend with the milk.","timer":null},{"text":"Sprinkle with parsley.","timer":null}],"variant":"Lighter","change":"With milk instead of cream."}]$r$::jsonb, 'claude')
