insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:cote de porc', 'Pork chops', array['en:pork chop', 'en:grilled pork chop', 'en:pork cutlet']::text[], 'dish', $r$[{"title":"Pork chops with mustard sauce","intro":"Pan-fried pork chops with a creamy wholegrain mustard sauce.","minutes":25,"calories":480,"difficulty":"Facile","imageSearch":"pork chops mustard sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pork chop","plural":"pork chops","qty":4,"unit":"","have":false},{"name":"wholegrain mustard","plural":"wholegrain mustard","qty":2,"unit":"tbsp","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"shallot","plural":"shallots","qty":1,"unit":"","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"white wine","plural":"white wine","qty":5,"unit":"cl","have":false}],"steps":[{"text":"Fry the chops for 5 min on each side in the butter.","timer":{"label":"Pan","min":10}},{"text":"Take them out and fry the chopped shallot.","timer":null},{"text":"Add the white wine, then the cream and the mustard, and cook for 2 min.","timer":null},{"text":"Put the chops back in the sauce for 2 min.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Marinated pork chops","intro":"Glazed pork chops, sweet and salty.","minutes":35,"calories":450,"difficulty":"Facile","imageSearch":"glazed pork chops","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pork chop","plural":"pork chops","qty":4,"unit":"","have":false},{"name":"honey","plural":"honey","qty":2,"unit":"tbsp","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Mix the honey, the soy sauce, the crushed garlic and the paprika.","timer":null},{"text":"Marinate the chops for 20 min.","timer":{"label":"Rest","min":20}},{"text":"Grill them for 5 min on each side.","timer":{"label":"Pan","min":10}},{"text":"Brush with the rest of the marinade at the end of cooking.","timer":null}],"kids":true,"variant":"Marinated","change":"Marinated in honey and soy sauce, then grilled."},{"title":"Pork chops with apples","intro":"Normandy-style pork chops with apples.","minutes":30,"calories":500,"difficulty":"Facile","imageSearch":"pork chops apples","veg":false,"oven":false,"cold":false,"missing":"","origin":"Normandy-inspired","serves":4,"items":[{"name":"pork chop","plural":"pork chops","qty":4,"unit":"","have":false},{"name":"apple","plural":"apples","qty":3,"unit":"","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false},{"name":"cider","plural":"cider","qty":10,"unit":"cl","have":false}],"steps":[{"text":"Fry the chops for 5 min on each side in the butter and take them out.","timer":{"label":"Pan","min":10}},{"text":"Fry the apple wedges for 5 min.","timer":{"label":"Pan","min":5}},{"text":"Add the cider, then the cream.","timer":null},{"text":"Put the chops back in the sauce for 2 min.","timer":null}],"kids":true,"variant":"With apples","change":"With caramelised apple wedges."}]$r$::jsonb, 'claude')
