insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:traver de porc', 'Pork ribs', array['en:pork rib', 'en:rib', 'en:spare rib', 'en:baked rib', 'en:barbecue rib']::text[], 'dish', $r$[{"title":"Glazed pork ribs","intro":"Tender pork ribs glazed with honey and barbecue sauce.","minutes":120,"calories":620,"difficulty":"Facile","imageSearch":"bbq pork ribs","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pork ribs","plural":"pork ribs","qty":1500,"unit":"g","have":false},{"name":"barbecue sauce","plural":"barbecue sauce","qty":10,"unit":"tbsp","have":false},{"name":"honey","plural":"honey","qty":2,"unit":"tbsp","have":false},{"name":"soy sauce","plural":"soy sauce","qty":2,"unit":"tbsp","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 160 °C.","timer":null},{"text":"Put the ribs in a dish, add 10 cl of water, cover with foil and bake for 1 h 15.","timer":{"label":"Oven","min":75}},{"text":"Mix the barbecue sauce, the honey, the soy sauce, the garlic and the paprika.","timer":null},{"text":"Brush the ribs with the sauce and put them back uncovered for 30 min at 200 °C, brushing twice more.","timer":{"label":"Oven","min":30}}],"variant":"The classic","change":""},{"title":"Chinese-style pork ribs","intro":"Sticky Chinese-style ribs.","minutes":120,"calories":600,"difficulty":"Facile","imageSearch":"chinese pork ribs","veg":false,"oven":true,"cold":false,"missing":"","origin":"Chinese-inspired","serves":4,"items":[{"name":"pork ribs","plural":"pork ribs","qty":1500,"unit":"g","have":false},{"name":"hoisin sauce","plural":"hoisin sauce","qty":6,"unit":"tbsp","have":false},{"name":"honey","plural":"honey","qty":2,"unit":"tbsp","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false},{"name":"five-spice","plural":"five-spice","qty":1,"unit":"tsp","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Cook the ribs covered for 1 h 15 at 160 °C with a little water.","timer":{"label":"Oven","min":75}},{"text":"Mix the hoisin sauce, the honey, the soy sauce and the spices.","timer":null},{"text":"Brush the ribs with it.","timer":null},{"text":"Put them back for 30 min at 200 °C, brushing now and then.","timer":{"label":"Oven","min":30}}],"variant":"Chinese style","change":"Glazed with hoisin sauce and five-spice."},{"title":"Braised pork ribs","intro":"Tender braised ribs with their potatoes.","minutes":100,"calories":650,"difficulty":"Facile","imageSearch":"braised pork ribs potatoes","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pork ribs","plural":"pork ribs","qty":1200,"unit":"g","have":false},{"name":"potato","plural":"potatoes","qty":800,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false},{"name":"white wine","plural":"white wine","qty":15,"unit":"cl","have":false}],"steps":[{"text":"Cut the ribs into pieces and brown them in a casserole.","timer":{"label":"Cooking","min":10}},{"text":"Add the onions, the thyme, the wine and 20 cl of water, and simmer for 45 min.","timer":{"label":"Cooking","min":45}},{"text":"Add the potatoes in chunks.","timer":null},{"text":"Cook for 30 min with the lid on.","timer":{"label":"Cooking","min":30}}],"variant":"Braised","change":"Slowly cooked in a casserole with potatoes."}]$r$::jsonb, 'claude')
