insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:saucisse puree', 'Sausage and mash', array['en:sausage and mash', 'en:banger and mash', 'en:toulouse sausage', 'en:sausage with onion gravy']::text[], 'dish', $r$[{"title":"Sausage and mash","intro":"Browned Toulouse sausages with homemade mash and onion gravy.","minutes":40,"calories":720,"difficulty":"Facile","imageSearch":"sausage mash onion gravy","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"toulouse sausage","plural":"toulouse sausages","qty":4,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"beef stock cube","plural":"beef stock cubes","qty":1,"unit":"","have":false}],"steps":[{"text":"Boil the potatoes for 20 min in salted water.","timer":{"label":"Cooking","min":20}},{"text":"Brown the sausages for 15 min in a pan, turning them.","timer":{"label":"Pan","min":15}},{"text":"Take them out and soften the sliced onions in the pan, then add the stock cube and 20 cl of water, and let it reduce.","timer":{"label":"Cooking","min":8}},{"text":"Mash the potatoes with the milk and the butter.","timer":null},{"text":"Serve the sausages on the mash, covered with gravy.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Sausages with onions and wine","intro":"Old-fashioned sausages in a red wine sauce.","minutes":45,"calories":650,"difficulty":"Facile","imageSearch":"sausages red wine onions","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"toulouse sausage","plural":"toulouse sausages","qty":4,"unit":"","have":false},{"name":"onion","plural":"onions","qty":3,"unit":"","have":false},{"name":"red wine","plural":"red wine","qty":20,"unit":"cl","have":false},{"name":"flour","plural":"flour","qty":1,"unit":"tbsp","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":800,"unit":"g","have":false}],"steps":[{"text":"Brown the sausages and take them out.","timer":{"label":"Pan","min":8}},{"text":"Soften the onions, sprinkle with flour, then add the wine and 10 cl of water.","timer":null},{"text":"Put the sausages back with the thyme and simmer for 25 min.","timer":{"label":"Cooking","min":25}},{"text":"Serve with steamed potatoes.","timer":null}],"variant":"With wine","change":"Simmered in red wine with onions."},{"title":"Chicken sausages with carrot mash","intro":"A lighter, more colourful version.","minutes":40,"calories":480,"difficulty":"Facile","imageSearch":"chicken sausages carrot mash","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken sausage","plural":"chicken sausages","qty":8,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":4,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":500,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":15,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":15,"unit":"g","have":false}],"steps":[{"text":"Boil the carrots and the potatoes for 20 min.","timer":{"label":"Cooking","min":20}},{"text":"Brown the sausages for 10 min.","timer":{"label":"Pan","min":10}},{"text":"Mash the vegetables with the milk and the butter.","timer":null},{"text":"Serve the sausages with the mash.","timer":null}],"kids":true,"variant":"Lighter","change":"Chicken sausages and a carrot and potato mash."}]$r$::jsonb, 'claude')
