insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:roti de boeuf', 'Roast beef', array['en:roast beef', 'en:roast beef joint', 'en:roasted beef', 'en:rosbif']::text[], 'dish', $r$[{"title":"Roast beef","intro":"A beef joint seared then roasted in the oven, pink in the middle, with potatoes.","minutes":60,"calories":520,"difficulty":"Moyen","imageSearch":"roast beef","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"beef joint","plural":"beef joints","qty":1,"unit":"","have":false},{"name":"new potato","plural":"new potatoes","qty":800,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":4,"unit":"clove","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false}],"steps":[{"text":"Take the beef out of the fridge 1 h before. Preheat the oven to 220 °C.","timer":null},{"text":"Put the potatoes in a dish with the oil, the garlic and the thyme, and bake for 15 min.","timer":{"label":"Oven","min":15}},{"text":"Sear the beef on all sides in the butter.","timer":{"label":"Pan","min":5}},{"text":"Put it on the potatoes and bake for 15 min per 500 g for pink meat.","timer":{"label":"Oven","min":30}},{"text":"Rest it for 10 min under foil before slicing.","timer":null}],"variant":"The classic","change":""},{"title":"Mustard-crusted roast beef","intro":"A fragrant joint with a mustard and herb crust.","minutes":60,"calories":500,"difficulty":"Moyen","imageSearch":"mustard herb crusted roast beef","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"beef joint","plural":"beef joints","qty":1,"unit":"","have":false},{"name":"mustard","plural":"mustard","qty":2,"unit":"tbsp","have":false},{"name":"herbes de provence","plural":"herbes de provence","qty":1,"unit":"tbsp","have":false},{"name":"breadcrumb","plural":"breadcrumbs","qty":2,"unit":"tbsp","have":false},{"name":"green bean","plural":"green beans","qty":500,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 220 °C. Sear the beef on all sides.","timer":{"label":"Pan","min":5}},{"text":"Brush it with mustard and roll it in the herbs and breadcrumbs.","timer":null},{"text":"Bake for 30 min.","timer":{"label":"Oven","min":30}},{"text":"Boil the green beans for 8 min.","timer":{"label":"Cooking","min":8}},{"text":"Rest the beef for 10 min before slicing.","timer":null}],"variant":"Mustard crust","change":"Brushed with mustard and herbs."},{"title":"Cold roast beef","intro":"Cold roast beef with mayonnaise and salad, for summer.","minutes":50,"calories":420,"difficulty":"Moyen","imageSearch":"cold roast beef slices","veg":false,"oven":true,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"beef joint","plural":"beef joints","qty":1,"unit":"","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":4,"unit":"tbsp","have":false},{"name":"gherkin","plural":"gherkins","qty":12,"unit":"","have":false},{"name":"salad leaves","plural":"salad leaves","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 220 °C. Sear the beef.","timer":{"label":"Pan","min":5}},{"text":"Bake for 25 min.","timer":{"label":"Oven","min":25}},{"text":"Let it cool completely, then chill it.","timer":null},{"text":"Cut it into thin slices and serve with mayonnaise, gherkins and salad.","timer":null}],"variant":"Cold","change":"Served cold in thin slices."}]$r$::jsonb, 'claude')
