"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"white wine","plural":"white wine","qty":10,"unit":"cl","have":false}],"steps":[{"text":"Brown the paupiettes.","timer":{"label":"Cooking","min":8}},{"text":"Add the shallots, the wine and 15 cl of water, and simmer for 25 min.","timer":{"label":"Cooking","min":25}},{"text":"Add the mushrooms and the cream.","timer":null},{"text":"Cook for 10 min.","timer":{"label":"Cooking","min":10}}],"kids":true,"variant":"Turkey and cream","change":"Turkey paupiettes in a cream sauce."},{"title":"Paupiettes in tomato sauce","intro":"Paupiettes in tomato sauce, served with pasta.","minutes":50,"calories":430,"difficulty":"Facile","imageSearch":"paupiettes tomato sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"veal paupiette","plural":"veal paupiettes","qty":4,"unit":"","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"green olive","plural":"green olives","qty":60,"unit":"g","have":false}],"steps":[{"text":"Brown the paupiettes.","timer":{"label":"Cooking","min":8}},{"text":"Add the onion and the garlic, then the tomatoes.","timer":null},{"text":"Simmer for 30 min.","timer":{"label":"Cooking","min":30}},{"text":"Add the olives 5 min before the end.","timer":null}],"variant":"In tomato sauce","change":"Simmered in a tomato sauce."}]$r$::jsonb, 'claude')
