insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:tajine d agneau', 'Lamb tagine', array['en:lamb tagine', 'en:lamb tagine with prune', 'en:lamb with prune']::text[], 'dish', $r$[{"title":"Lamb tagine with prunes","intro":"Tender lamb simmered with spices, prunes and toasted almonds.","minutes":120,"calories":620,"difficulty":"Moyen","imageSearch":"lamb tagine prunes","veg":false,"oven":false,"cold":false,"missing":"","origin":"Moroccan recipe","serves":4,"items":[{"name":"lamb shoulder","plural":"lamb shoulders","qty":1000,"unit":"g","have":false},{"name":"prune","plural":"prunes","qty":200,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"honey","plural":"honey","qty":2,"unit":"tbsp","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false},{"name":"ras el hanout","plural":"ras el hanout","qty":2,"unit":"tsp","have":false},{"name":"almond","plural":"almonds","qty":50,"unit":"g","have":false}],"steps":[{"text":"Cut the lamb into pieces and brown it with the onions.","timer":{"label":"Cooking","min":10}},{"text":"Add the spices and 40 cl of water, cover and simmer for 1 h 15.","timer":{"label":"Cooking","min":75}},{"text":"Add the prunes and the honey, and cook for 20 min.","timer":{"label":"Cooking","min":20}},{"text":"Toast the almonds in a dry pan and sprinkle them over.","timer":null}],"variant":"The classic","change":""},{"title":"Lamb tagine with vegetables","intro":"A complete lamb tagine with vegetables.","minutes":110,"calories":560,"difficulty":"Moyen","imageSearch":"lamb vegetable tagine","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"lamb shoulder","plural":"lamb shoulders","qty":800,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"chickpea","plural":"chickpeas","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"ras el hanout","plural":"ras el hanout","qty":2,"unit":"tsp","have":false}],"steps":[{"text":"Brown the lamb with the onions.","timer":{"label":"Cooking","min":10}},{"text":"Add the spices, the carrots and 40 cl of water, and simmer for 1 h.","timer":{"label":"Cooking","min":60}},{"text":"Add the courgettes and the chickpeas.","timer":null},{"text":"Cook for 25 min.","timer":{"label":"Cooking","min":25}}],"variant":"With vegetables","change":"With carrots, courgettes and chickpeas."},{"title":"Lamb tagine with apricots","intro":"A sweet and savoury tagine with apricots.","minutes":120,"calories":600,"difficulty":"Moyen","imageSearch":"lamb apricot tagine","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"lamb shoulder","plural":"lamb shoulders","qty":1000,"unit":"g","have":false},{"name":"dried apricot","plural":"dried apricots","qty":150,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the lamb with the onions.","timer":{"label":"Cooking","min":10}},{"text":"Add the spices and 40 cl of water, and simmer for 1 h 15.","timer":{"label":"Cooking","min":75}},{"text":"Add the apricots and cook for 20 min.","timer":{"label":"Cooking","min":20}},{"text":"Sprinkle with coriander.","timer":null}],"variant":"With apricots","change":"With dried apricots."}]$r$::jsonb, 'claude')
