insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:brochette de poulet', 'Chicken skewers', array['en:chicken skewer', 'en:chicken kebab', 'en:grilled chicken skewer', 'en:barbecue skewer', 'en:turkey skewer']::text[], 'dish', $r$[{"title":"Marinated chicken skewers","intro":"Chicken skewers marinated in lemon and paprika, with peppers and onions.","minutes":45,"calories":350,"difficulty":"Facile","imageSearch":"grilled chicken skewers","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"red onion","plural":"red onions","qty":1,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"paprika","plural":"paprika","qty":2,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false}],"steps":[{"text":"Cut the chicken into cubes and marinate it for 20 min with the oil, the lemon, the paprika and the garlic.","timer":{"label":"Rest","min":20}},{"text":"Cut the pepper and the onion into chunks.","timer":null},{"text":"Thread the chicken and the vegetables onto skewers, alternating them.","timer":null},{"text":"Grill them for 12 min, turning them.","timer":{"label":"Pan","min":12}}],"kids":true,"makes":{"n":8,"one":"skewer","many":"skewers"},"variant":"The classic","change":""},{"title":"Yoghurt chicken skewers","intro":"Tender, fragrant skewers with a yoghurt sauce.","minutes":45,"calories":320,"difficulty":"Facile","imageSearch":"yogurt marinated chicken skewers","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"plain yoghurt","plural":"plain yoghurts","qty":2,"unit":"","have":false},{"name":"curry powder","plural":"curry powder","qty":2,"unit":"tsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"cucumber","plural":"cucumbers","qty":1,"unit":"","have":false}],"steps":[{"text":"Mix 1 yoghurt with the curry powder, the lemon juice and the garlic.","timer":null},{"text":"Marinate the cubed chicken for 30 min.","timer":{"label":"Rest","min":30}},{"text":"Thread onto skewers and grill for 12 min.","timer":{"label":"Pan","min":12}},{"text":"Serve with the other yoghurt mixed with grated cucumber.","timer":null}],"makes":{"n":8,"one":"skewer","many":"skewers"},"variant":"With yoghurt","change":"Marinated in yoghurt and spices, Indian style."},{"title":"Honey chicken skewers","intro":"Sweet and salty skewers that kids like.","minutes":40,"calories":360,"difficulty":"Facile","imageSearch":"honey soy chicken skewers","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"honey","plural":"honey","qty":3,"unit":"tbsp","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false},{"name":"sesame seed","plural":"sesame seeds","qty":1,"unit":"tbsp","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Marinate the cubed chicken for 20 min with the honey and the soy sauce.","timer":{"label":"Rest","min":20}},{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Thread onto skewers and grill for 12 min, brushing with the marinade.","timer":{"label":"Pan","min":12}},{"text":"Sprinkle with sesame seeds.","timer":null}],"kids":true,"makes":{"n":8,"one":"skewer","many":"skewers"},"variant":"With honey","change":"Glazed with honey and soy sauce."}]$r$::jsonb, 'claude')
