insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:poulet tandoori', 'Tandoori chicken', array['en:tandoori chicken', 'en:tandoori', 'en:chicken tandoori', 'en:tandoori chicken thigh']::text[], 'dish', $r$[{"title":"Tandoori chicken","intro":"Chicken thighs marinated in yoghurt and tandoori spices, then roasted in the oven.","minutes":60,"calories":420,"difficulty":"Facile","imageSearch":"tandoori chicken","veg":false,"oven":true,"cold":false,"missing":"","origin":"Indian dish","serves":4,"items":[{"name":"chicken thigh","plural":"chicken thighs","qty":4,"unit":"","have":false},{"name":"plain yoghurt","plural":"plain yoghurts","qty":2,"unit":"","have":false},{"name":"tandoori spice mix","plural":"tandoori spice mix","qty":2,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"basmati rice","plural":"basmati rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Score the thighs and marinate them for at least 1 h with the yoghurt, the spices, the lemon, the garlic and the ginger.","timer":{"label":"Rest","min":60}},{"text":"Preheat the oven to 220 °C.","timer":null},{"text":"Put the thighs on a tray and bake for 40 min.","timer":{"label":"Oven","min":40}},{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}}],"variant":"The classic","change":""},{"title":"Tandoori chicken skewers","intro":"Quick tandoori skewers to grill.","minutes":40,"calories":360,"difficulty":"Facile","imageSearch":"tandoori chicken skewers","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"plain yoghurt","plural":"plain yoghurts","qty":1,"unit":"","have":false},{"name":"tandoori spice mix","plural":"tandoori spice mix","qty":2,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"red onion","plural":"red onions","qty":1,"unit":"","have":false}],"steps":[{"text":"Marinate the cubed chicken for 30 min with the yoghurt, the spices and the lemon.","timer":{"label":"Rest","min":30}},{"text":"Thread it onto skewers with chunks of onion.","timer":null},{"text":"Grill for 12 min, turning them.","timer":{"label":"Pan","min":12}},{"text":"Serve with a salad.","timer":null}],"makes":{"n":8,"one":"skewer","many":"skewers"},"variant":"Skewers","change":"Cubes of chicken breast on skewers."},{"title":"Tandoori cauliflower","intro":"The tandoori marinade on roasted cauliflower.","minutes":50,"calories":220,"difficulty":"Facile","imageSearch":"tandoori cauliflower","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cauliflower","plural":"cauliflowers","qty":1,"unit":"","have":false},{"name":"plain yoghurt","plural":"plain yoghurts","qty":1,"unit":"","have":false},{"name":"tandoori spice mix","plural":"tandoori spice mix","qty":2,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 210 °C.","timer":null},{"text":"Cut the cauliflower into florets and coat them in the yoghurt mixed with the spices and the lemon.","timer":null},{"text":"Bake for 35 min.","timer":{"label":"Oven","min":35}},{"text":"Sprinkle with coriander.","timer":null}],"variant":"Vegetarian","change":"A cauliflower roasted in tandoori marinade."}]$r$::jsonb, 'claude')
