insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:escalope de dinde', 'Turkey escalopes', array['en:turkey escalope', 'en:turkey in cream sauce', 'en:turkey cutlet']::text[], 'dish', $r$[{"title":"Turkey escalopes in cream sauce","intro":"Browned turkey escalopes covered in a creamy mushroom sauce.","minutes":25,"calories":380,"difficulty":"Facile","imageSearch":"turkey escalope cream sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"turkey escalope","plural":"turkey escalopes","qty":4,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":200,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":15,"unit":"cl","have":false},{"name":"shallot","plural":"shallots","qty":1,"unit":"","have":false},{"name":"butter","plural":"butter","qty":15,"unit":"g","have":false}],"steps":[{"text":"Fry the escalopes for 4 min on each side in the butter and take them out.","timer":{"label":"Pan","min":8}},{"text":"Fry the shallot and the mushrooms for 5 min.","timer":{"label":"Pan","min":5}},{"text":"Add the cream and cook for 2 min.","timer":null},{"text":"Put the escalopes back in the sauce for 2 min.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Lemon turkey escalopes","intro":"Light escalopes with lemon and capers.","minutes":20,"calories":300,"difficulty":"Facile","imageSearch":"turkey piccata lemon capers","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"turkey escalope","plural":"turkey escalopes","qty":4,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"caper","plural":"capers","qty":1,"unit":"tbsp","have":false},{"name":"flour","plural":"flour","qty":2,"unit":"tbsp","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false}],"steps":[{"text":"Dust the escalopes lightly with flour.","timer":null},{"text":"Fry them for 3 min on each side in the butter.","timer":{"label":"Pan","min":6}},{"text":"Add the lemon juice, the capers and 5 cl of water.","timer":null},{"text":"Let it reduce for 1 min.","timer":null}],"variant":"Lemon","change":"With a light lemon and caper sauce."},{"title":"Curried turkey escalopes","intro":"Turkey escalopes in a mild curry sauce.","minutes":25,"calories":380,"difficulty":"Facile","imageSearch":"turkey curry coconut","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"turkey escalope","plural":"turkey escalopes","qty":4,"unit":"","have":false},{"name":"coconut milk","plural":"coconut milk","qty":20,"unit":"cl","have":false},{"name":"curry powder","plural":"curry powder","qty":2,"unit":"tsp","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Cut the turkey into strips and brown it with the onion.","timer":{"label":"Pan","min":6}},{"text":"Add the curry powder and the coconut milk.","timer":null},{"text":"Simmer for 8 min.","timer":{"label":"Cooking","min":8}}],"kids":true,"variant":"Curry","change":"With a coconut curry sauce."}]$r$::jsonb, 'claude')
