insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:poulet au miel', 'Honey chicken', array['en:honey chicken', 'en:honey soy chicken', 'en:honey garlic chicken', 'en:honey glazed chicken']::text[], 'dish', $r$[{"title":"Honey and soy chicken","intro":"Chicken pieces glazed with honey, soy sauce and garlic, served with rice.","minutes":25,"calories":450,"difficulty":"Facile","imageSearch":"honey soy chicken","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"honey","plural":"honey","qty":3,"unit":"tbsp","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"sesame seed","plural":"sesame seeds","qty":1,"unit":"tbsp","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Cut the chicken into pieces and brown it for 6 min.","timer":{"label":"Pan","min":6}},{"text":"Add the honey, the soy sauce and the garlic.","timer":null},{"text":"Let it reduce for 3 min until the chicken is glazed.","timer":{"label":"Cooking","min":3}},{"text":"Sprinkle with sesame seeds.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Oven-baked honey chicken thighs","intro":"Golden chicken thighs with honey and mustard.","minutes":55,"calories":480,"difficulty":"Facile","imageSearch":"honey mustard chicken thighs","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken thigh","plural":"chicken thighs","qty":4,"unit":"","have":false},{"name":"honey","plural":"honey","qty":3,"unit":"tbsp","have":false},{"name":"mustard","plural":"mustard","qty":2,"unit":"tbsp","have":false},{"name":"potato","plural":"potatoes","qty":600,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Mix the honey and the mustard and brush it over the thighs.","timer":null},{"text":"Put them in a dish with the potato wedges and the oil.","timer":null},{"text":"Bake for 45 min, basting now and then.","timer":{"label":"Oven","min":45}}],"kids":true,"variant":"Oven-baked","change":"Thighs roasted in the oven with honey and mustard."},{"title":"Honey and lemon chicken","intro":"A fresh, mild chicken with honey and lemon.","minutes":25,"calories":420,"difficulty":"Facile","imageSearch":"honey lemon chicken","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"honey","plural":"honey","qty":3,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the chicken into pieces and brown it.","timer":{"label":"Pan","min":6}},{"text":"Add the honey, the lemon zest and juice, the garlic and the thyme.","timer":null},{"text":"Let it reduce for 3 min.","timer":{"label":"Cooking","min":3}},{"text":"Serve with rice or vegetables.","timer":null}],"variant":"Lemon","change":"With a honey and lemon sauce."}]$r$::jsonb, 'claude')
