insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:tarte aux fraise', 'Strawberry tart', array['en:strawberry tart', 'en:strawberry custard tart']::text[], 'dish', $r$[{"title":"Strawberry tart","intro":"A shortcrust base, vanilla custard and fresh strawberries.","minutes":70,"calories":380,"difficulty":"Moyen","imageSearch":"strawberry tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"French pastry","serves":4,"items":[{"name":"shortcrust pastry","plural":"shortcrust pastry","qty":1,"unit":"","have":false},{"name":"strawberry","plural":"strawberries","qty":500,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"cornflour","plural":"cornflour","qty":40,"unit":"g","have":false},{"name":"vanilla sugar","plural":"vanilla sugar","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C. Line a tin with the pastry, prick it and blind bake it for 20 min.","timer":{"label":"Oven","min":20}},{"text":"Heat the milk. Whisk the eggs, the sugar, the vanilla sugar and the cornflour.","timer":null},{"text":"Pour the hot milk over, put back on the heat and whisk until the custard thickens.","timer":{"label":"Cooking","min":3}},{"text":"Let the custard cool, then spread it over the tart base.","timer":null},{"text":"Arrange the halved strawberries on top and keep it chilled.","timer":null}],"dessert":true,"variant":"The classic","change":""},{"title":"Quick strawberry tart","intro":"A strawberry tart with no custard to cook, ready in 40 minutes.","minutes":40,"calories":420,"difficulty":"Facile","imageSearch":"easy strawberry mascarpone tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"shortcrust pastry","plural":"shortcrust pastry","qty":1,"unit":"","have":false},{"name":"strawberry","plural":"strawberries","qty":500,"unit":"g","have":false},{"name":"mascarpone","plural":"mascarpone","qty":250,"unit":"g","have":false},{"name":"whipping cream","plural":"whipping cream","qty":15,"unit":"cl","have":false},{"name":"icing sugar","plural":"icing sugar","qty":50,"unit":"g","have":false}],"steps":[{"text":"Blind bake the pastry for 20 min at 180 °C and let it cool.","timer":{"label":"Oven","min":20}},{"text":"Whisk the mascarpone, the cold cream and the icing sugar until firm.","timer":null},{"text":"Spread it over the tart base.","timer":null},{"text":"Arrange the strawberries on top.","timer":null}],"dessert":true,"variant":"Quick","change":"With mascarpone instead of custard."},{"title":"No-bake strawberry tart","intro":"A fresh strawberry tart that needs no oven.","minutes":30,"calories":400,"difficulty":"Facile","imageSearch":"no bake strawberry tart","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"digestive biscuit","plural":"digestive biscuits","qty":200,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":80,"unit":"g","have":false},{"name":"strawberry","plural":"strawberries","qty":500,"unit":"g","have":false},{"name":"fromage blanc","plural":"fromage blanc","qty":250,"unit":"g","have":false},{"name":"whipping cream","plural":"whipping cream","qty":15,"unit":"cl","have":false},{"name":"icing sugar","plural":"icing sugar","qty":50,"unit":"g","have":false}],"steps":[{"text":"Crush the biscuits, mix them with the melted butter and press into the bottom of a tin.","timer":null},{"text":"Chill for 30 min to harden.","timer":null},{"text":"Whip the cream and fold it into the fromage blanc and the icing sugar.","timer":null},{"text":"Spread over the base and arrange the strawberries on top.","timer":null}],"dessert":true,"variant":"No oven","change":"With a crushed biscuit base."}]$r$::jsonb, 'claude')
