insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:tarte bourdaloue', 'Tarte Bourdaloue', array['en:pear tart', 'en:pear and almond tart', 'en:pear frangipane tart']::text[], 'dish', $r$[{"title":"Tarte Bourdaloue","intro":"A pear tart on a golden almond cream.","minutes":60,"calories":420,"difficulty":"Moyen","imageSearch":"pear almond tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"French pastry","serves":4,"items":[{"name":"shortcrust pastry","plural":"shortcrust pastry","qty":1,"unit":"","have":false},{"name":"pear in syrup","plural":"pears in syrup","qty":8,"unit":"","have":false},{"name":"ground almond","plural":"ground almonds","qty":100,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":80,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"flaked almond","plural":"flaked almonds","qty":20,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C and line a tin with the pastry.","timer":null},{"text":"Mix the soft butter, the sugar, the ground almonds and the eggs.","timer":null},{"text":"Spread this cream over the pastry.","timer":null},{"text":"Slice the drained pear halves and arrange them in a rosette.","timer":null},{"text":"Sprinkle with flaked almonds and bake for 35 min.","timer":{"label":"Oven","min":35}}],"dessert":true,"variant":"The classic","change":""},{"title":"Pear and chocolate tart","intro":"Pear and chocolate together in a rich tart.","minutes":60,"calories":470,"difficulty":"Moyen","imageSearch":"pear chocolate tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"shortcrust pastry","plural":"shortcrust pastry","qty":1,"unit":"","have":false},{"name":"pear in syrup","plural":"pears in syrup","qty":8,"unit":"","have":false},{"name":"ground almond","plural":"ground almonds","qty":80,"unit":"g","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":100,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":60,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":60,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C and line a tin with the pastry.","timer":null},{"text":"Melt the chocolate with the butter and mix with the sugar, the eggs and the ground almonds.","timer":null},{"text":"Spread over the pastry and lay the sliced pears on top.","timer":null},{"text":"Bake for 35 min.","timer":{"label":"Oven","min":35}}],"dessert":true,"variant":"Chocolate","change":"With chocolate in the almond cream."},{"title":"Thin pear tart","intro":"A thin, crisp tart with fresh pears.","minutes":40,"calories":280,"difficulty":"Facile","imageSearch":"thin pear tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"puff pastry","plural":"puff pastry","qty":1,"unit":"","have":false},{"name":"pear","plural":"pears","qty":4,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":30,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Roll the pastry out onto a tray.","timer":null},{"text":"Peel the pears and slice them thinly.","timer":null},{"text":"Arrange them on the pastry, sprinkle with sugar and cinnamon, and dot with butter.","timer":null},{"text":"Bake for 25 min.","timer":{"label":"Oven","min":25}}],"dessert":true,"variant":"Thin tart","change":"On puff pastry, with no cream."}]$r$::jsonb, 'claude')
