insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:far breton', 'Far breton', array['en:far with prune', 'en:prune far', 'en:breton custard cake']::text[], 'dish', $r$[{"title":"Far breton with prunes","intro":"The thick Breton custard cake with prunes, golden and soft.","minutes":70,"calories":300,"difficulty":"Facile","imageSearch":"far breton prunes","veg":true,"oven":true,"cold":false,"missing":"","origin":"Breton speciality","serves":4,"items":[{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":120,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"milk","plural":"milk","qty":75,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"prune","plural":"prunes","qty":200,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Butter a dish.","timer":null},{"text":"Mix the flour, the sugar and a pinch of salt, then add the eggs one by one.","timer":null},{"text":"Pour in the milk little by little, whisking.","timer":null},{"text":"Spread the prunes in the dish and pour in the batter.","timer":null},{"text":"Dot with butter and bake for 45 min.","timer":{"label":"Oven","min":45}}],"kids":true,"dessert":true,"variant":"The classic","change":""},{"title":"Plain far breton","intro":"The plain vanilla far, for people who do not like prunes.","minutes":65,"calories":280,"difficulty":"Facile","imageSearch":"plain far breton","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":120,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"milk","plural":"milk","qty":75,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"vanilla pod","plural":"vanilla pods","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Heat the milk with the split vanilla pod and leave to infuse.","timer":null},{"text":"Mix the flour, the sugar and the eggs, then the milk.","timer":null},{"text":"Pour into a buttered dish and dot with butter.","timer":null},{"text":"Bake for 45 min.","timer":{"label":"Oven","min":45}}],"kids":true,"dessert":true,"variant":"Plain","change":"Without prunes, with vanilla."},{"title":"Apple far","intro":"A soft far with caramelised apples.","minutes":70,"calories":300,"difficulty":"Facile","imageSearch":"apple far breton","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":120,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"milk","plural":"milk","qty":75,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"apple","plural":"apples","qty":3,"unit":"","have":false}],"steps":[{"text":"Fry the sliced apples for 5 min in a little butter.","timer":{"label":"Pan","min":5}},{"text":"Make the batter: flour, sugar, eggs, then milk.","timer":null},{"text":"Put the apples in a buttered dish and pour in the batter.","timer":null},{"text":"Bake for 45 min at 200 °C.","timer":{"label":"Oven","min":45}}],"kids":true,"dessert":true,"variant":"With apples","change":"With pan-fried apples."}]$r$::jsonb, 'claude')
