insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:churro', 'Churros', array['en:homemade churro']::text[], 'dish', $r$[{"title":"Churros","intro":"Crispy ridged Spanish fritters rolled in cinnamon sugar.","minutes":30,"calories":300,"difficulty":"Moyen","imageSearch":"churros cinnamon sugar","veg":true,"oven":false,"cold":false,"missing":"","origin":"Spanish recipe","serves":4,"items":[{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false},{"name":"frying oil","plural":"frying oil","qty":100,"unit":"cl","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Bring 25 cl of water to the boil with the butter and a pinch of salt.","timer":null},{"text":"Tip in the flour all at once and stir until the dough forms a ball.","timer":null},{"text":"Put the dough in a piping bag with a star nozzle.","timer":null},{"text":"Pipe 10 cm lengths into the hot oil and fry them for 3 min.","timer":{"label":"Frying","min":3}},{"text":"Drain and roll them in the sugar mixed with the cinnamon.","timer":null}],"kids":true,"dessert":true,"makes":{"n":24,"one":"churro","many":"churros"},"variant":"The classic","change":""},{"title":"Churros with chocolate sauce","intro":"Churros with thick hot chocolate, as in Spain.","minutes":35,"calories":420,"difficulty":"Moyen","imageSearch":"churros chocolate sauce","veg":true,"oven":false,"cold":false,"missing":"","origin":"Spanish recipe","serves":4,"items":[{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":60,"unit":"g","have":false},{"name":"frying oil","plural":"frying oil","qty":100,"unit":"cl","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":150,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false}],"steps":[{"text":"Make the dough: bring the water, butter and salt to the boil, then add the flour all at once.","timer":null},{"text":"Fry lengths of dough for 3 min.","timer":{"label":"Frying","min":3}},{"text":"Roll them in the sugar.","timer":null},{"text":"Melt the chocolate in the hot milk and serve for dipping.","timer":null}],"kids":true,"dessert":true,"makes":{"n":24,"one":"churro","many":"churros"},"variant":"Chocolate sauce","change":"With a hot chocolate sauce for dipping."},{"title":"Baked churros","intro":"Lighter churros, golden from the oven.","minutes":40,"calories":220,"difficulty":"Moyen","imageSearch":"baked churros","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":150,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":60,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":60,"unit":"g","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Bring 25 cl of water to the boil with the butter.","timer":null},{"text":"Add the flour all at once, then the eggs one by one off the heat.","timer":null},{"text":"Pipe lengths onto a tray with a star nozzle.","timer":null},{"text":"Bake for 20 min.","timer":{"label":"Oven","min":20}},{"text":"Roll in the cinnamon sugar.","timer":null}],"kids":true,"dessert":true,"makes":{"n":20,"one":"churro","many":"churros"},"variant":"Oven-baked","change":"Baked rather than fried."}]$r$::jsonb, 'claude')
