insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:cupcake', 'Cupcakes', array['en:vanilla cupcake', 'en:chocolate cupcake']::text[], 'dish', $r$[{"title":"Vanilla cupcakes","intro":"Soft vanilla cakes with a buttercream frosting.","minutes":50,"calories":350,"difficulty":"Moyen","imageSearch":"vanilla cupcakes frosting","veg":true,"oven":true,"cold":false,"missing":"","origin":"American recipe","serves":4,"items":[{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":150,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":200,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"milk","plural":"milk","qty":10,"unit":"cl","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"icing sugar","plural":"icing sugar","qty":200,"unit":"g","have":false},{"name":"vanilla sugar","plural":"vanilla sugar","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Whisk 100 g of butter with the sugar, then add the eggs, the flour, the baking powder, the milk and the vanilla sugar.","timer":null},{"text":"Fill paper cases two-thirds full and bake for 20 min.","timer":{"label":"Oven","min":20}},{"text":"Whisk the rest of the butter with the icing sugar to make the frosting.","timer":null},{"text":"Decorate the cooled cupcakes.","timer":null}],"kids":true,"dessert":true,"makes":{"n":12,"one":"cupcake","many":"cupcakes"},"variant":"The classic","change":""},{"title":"Chocolate cupcakes","intro":"All-chocolate cupcakes for birthdays.","minutes":50,"calories":380,"difficulty":"Moyen","imageSearch":"chocolate cupcakes","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":180,"unit":"g","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":30,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":150,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":100,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"milk","plural":"milk","qty":10,"unit":"cl","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":150,"unit":"g","have":false},{"name":"single cream","plural":"single cream","qty":15,"unit":"cl","have":false}],"steps":[{"text":"Preheat the oven to 180 °C. Mix the butter and the sugar, then add the eggs, the flour, the cocoa, the baking powder and the milk.","timer":null},{"text":"Fill paper cases and bake for 20 min.","timer":{"label":"Oven","min":20}},{"text":"Melt the chocolate in the hot cream and chill until thick.","timer":null},{"text":"Decorate the cooled cupcakes.","timer":null}],"kids":true,"dessert":true,"makes":{"n":12,"one":"cupcake","many":"cupcakes"},"variant":"Chocolate","change":"With cocoa and a chocolate frosting."},{"title":"Lemon cupcakes","intro":"Fresh, tangy lemon cupcakes.","minutes":50,"calories":340,"difficulty":"Moyen","imageSearch":"lemon cupcakes","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":150,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":100,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":2,"unit":"","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"cream cheese","plural":"cream cheese","qty":150,"unit":"g","have":false},{"name":"icing sugar","plural":"icing sugar","qty":80,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C. Mix the butter, the sugar, the eggs, the flour, the baking powder, and the zest and juice of one lemon.","timer":null},{"text":"Fill paper cases and bake for 20 min.","timer":{"label":"Oven","min":20}},{"text":"Whisk the cream cheese with the icing sugar and the zest of the second lemon.","timer":null},{"text":"Decorate the cooled cupcakes.","timer":null}],"kids":true,"dessert":true,"makes":{"n":12,"one":"cupcake","many":"cupcakes"},"variant":"Lemon","change":"With a lemony cream cheese frosting."}]$r$::jsonb, 'claude')
