insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:donut', 'Doughnuts', array['en:doughnut', 'en:homemade doughnut']::text[], 'dish', $r$[{"title":"Glazed doughnuts","intro":"Soft ring doughnuts with a sugar glaze.","minutes":150,"calories":320,"difficulty":"Moyen","imageSearch":"glazed donuts","veg":true,"oven":false,"cold":false,"missing":"","origin":"American recipe","serves":4,"items":[{"name":"flour","plural":"flour","qty":400,"unit":"g","have":false},{"name":"yeast","plural":"yeast","qty":10,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":50,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":50,"unit":"g","have":false},{"name":"icing sugar","plural":"icing sugar","qty":200,"unit":"g","have":false},{"name":"frying oil","plural":"frying oil","qty":100,"unit":"cl","have":false}],"steps":[{"text":"Mix the yeast into the warm milk, then knead with the flour, the sugar, the egg and the butter.","timer":null},{"text":"Leave to rise for 1 h 30.","timer":{"label":"Rising","min":90}},{"text":"Roll out to 1 cm thick and cut out rings. Leave to rise for 30 min.","timer":{"label":"Rising","min":30}},{"text":"Fry for 1 min on each side.","timer":{"label":"Frying","min":2}},{"text":"Dip the tops in the icing sugar mixed with 3 tbsp of water.","timer":null}],"kids":true,"dessert":true,"makes":{"n":12,"one":"doughnut","many":"doughnuts"},"variant":"The classic","change":""},{"title":"Chocolate doughnuts","intro":"Doughnuts covered in melting chocolate.","minutes":150,"calories":370,"difficulty":"Moyen","imageSearch":"chocolate glazed donuts","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":400,"unit":"g","have":false},{"name":"yeast","plural":"yeast","qty":10,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":50,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":50,"unit":"g","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":150,"unit":"g","have":false},{"name":"frying oil","plural":"frying oil","qty":100,"unit":"cl","have":false}],"steps":[{"text":"Make the dough and leave to rise for 1 h 30.","timer":{"label":"Rising","min":90}},{"text":"Cut out rings and leave to rise for 30 min.","timer":{"label":"Rising","min":30}},{"text":"Fry for 1 min on each side.","timer":{"label":"Frying","min":2}},{"text":"Dip the tops in the melted chocolate.","timer":null}],"kids":true,"dessert":true,"makes":{"n":12,"one":"doughnut","many":"doughnuts"},"variant":"Chocolate","change":"With a chocolate glaze."},{"title":"Baked doughnuts","intro":"Lighter doughnuts with no frying.","minutes":30,"calories":230,"difficulty":"Facile","imageSearch":"baked donuts","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"milk","plural":"milk","qty":12,"unit":"cl","have":false},{"name":"melted butter","plural":"melted butter","qty":50,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"icing sugar","plural":"icing sugar","qty":100,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Mix all the ingredients except the icing sugar.","timer":null},{"text":"Fill a buttered doughnut tin and bake for 12 min.","timer":{"label":"Oven","min":12}},{"text":"Dip the tops in the icing sugar mixed with a little water.","timer":null}],"kids":true,"dessert":true,"makes":{"n":8,"one":"doughnut","many":"doughnuts"},"variant":"Oven-baked","change":"Baked in a doughnut tin."}]$r$::jsonb, 'claude')
