insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:eclair au chocolat', 'Chocolate éclairs', array['en:chocolate eclair', 'en:eclair', 'en:coffee eclair']::text[], 'dish', $r$[{"title":"Chocolate éclairs","intro":"Long choux buns filled with chocolate custard and iced with chocolate.","minutes":90,"calories":380,"difficulty":"Difficile","imageSearch":"chocolate eclairs","veg":true,"oven":true,"cold":false,"missing":"","origin":"French pastry","serves":4,"items":[{"name":"flour","plural":"flour","qty":100,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":80,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":7,"unit":"","have":false},{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"cornflour","plural":"cornflour","qty":40,"unit":"g","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":200,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C. Bring 15 cl of water, the butter and a pinch of salt to the boil, tip in the flour and stir until the dough comes away from the pan.","timer":null},{"text":"Off the heat, add 4 eggs one by one. Pipe 12 cm lengths onto a tray.","timer":null},{"text":"Bake for 30 min without opening the oven.","timer":{"label":"Oven","min":30}},{"text":"Make a custard with the milk, 3 eggs, the sugar and the cornflour, and stir in 100 g of chocolate.","timer":{"label":"Cooking","min":5}},{"text":"Fill the cold éclairs and cover them with the rest of the melted chocolate.","timer":null}],"dessert":true,"makes":{"n":12,"one":"éclair","many":"éclairs"},"variant":"The classic","change":""},{"title":"Coffee éclairs","intro":"The coffee éclairs from the bakery.","minutes":90,"calories":360,"difficulty":"Difficile","imageSearch":"coffee eclairs","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":100,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":80,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":7,"unit":"","have":false},{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"cornflour","plural":"cornflour","qty":40,"unit":"g","have":false},{"name":"instant coffee","plural":"instant coffee","qty":2,"unit":"tbsp","have":false},{"name":"icing sugar","plural":"icing sugar","qty":150,"unit":"g","have":false}],"steps":[{"text":"Make the choux pastry and bake the éclairs for 30 min.","timer":{"label":"Oven","min":30}},{"text":"Make a custard and flavour it with 1 tbsp of instant coffee.","timer":{"label":"Cooking","min":5}},{"text":"Fill the cold éclairs.","timer":null},{"text":"Mix the icing sugar with the rest of the coffee dissolved in a little water and spread it over the éclairs.","timer":null}],"dessert":true,"makes":{"n":12,"one":"éclair","many":"éclairs"},"variant":"Coffee","change":"With a coffee custard and icing."},{"title":"Cream-filled éclairs","intro":"Light éclairs filled with whipped cream and iced with chocolate.","minutes":70,"calories":330,"difficulty":"Moyen","imageSearch":"cream filled eclairs","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":100,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":80,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"whipping cream","plural":"whipping cream","qty":30,"unit":"cl","have":false},{"name":"icing sugar","plural":"icing sugar","qty":40,"unit":"g","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":100,"unit":"g","have":false}],"steps":[{"text":"Make the choux pastry and bake the éclairs for 30 min.","timer":{"label":"Oven","min":30}},{"text":"Whip the very cold cream with the icing sugar.","timer":null},{"text":"Fill the cold éclairs.","timer":null},{"text":"Cover with melted chocolate.","timer":null}],"dessert":true,"makes":{"n":12,"one":"éclair","many":"éclairs"},"variant":"Whipped cream","change":"Filled with whipped cream, which is easier."}]$r$::jsonb, 'claude')
