insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:glace maison', 'Homemade ice cream', array['en:homemade ice cream', 'en:ice cream', 'en:no churn ice cream', 'en:vanilla ice cream']::text[], 'dish', $r$[{"title":"No-churn vanilla ice cream","intro":"A creamy vanilla ice cream made with condensed milk, with no machine.","minutes":15,"calories":330,"difficulty":"Facile","imageSearch":"no churn vanilla ice cream","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"whipping cream","plural":"whipping cream","qty":50,"unit":"cl","have":false},{"name":"condensed milk","plural":"condensed milk","qty":400,"unit":"g","have":false},{"name":"vanilla pod","plural":"vanilla pods","qty":1,"unit":"","have":false}],"steps":[{"text":"Whip the very cold cream until stiff.","timer":null},{"text":"Mix the condensed milk with the vanilla seeds.","timer":null},{"text":"Gently fold in the whipped cream.","timer":null},{"text":"Pour into a tub and freeze for 6 h.","timer":null}],"kids":true,"dessert":true,"variant":"The classic","change":""},{"title":"No-churn chocolate ice cream","intro":"A smooth chocolate ice cream, no machine needed.","minutes":15,"calories":380,"difficulty":"Facile","imageSearch":"no churn chocolate ice cream","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"whipping cream","plural":"whipping cream","qty":50,"unit":"cl","have":false},{"name":"condensed milk","plural":"condensed milk","qty":400,"unit":"g","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":100,"unit":"g","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Melt the chocolate and let it cool a little.","timer":null},{"text":"Mix the condensed milk, the chocolate and the cocoa.","timer":null},{"text":"Whip the cream and fold it in.","timer":null},{"text":"Freeze for 6 h.","timer":null}],"kids":true,"dessert":true,"variant":"Chocolate","change":"With melted chocolate."},{"title":"Banana ice cream","intro":"A quick, light banana ice cream.","minutes":5,"calories":120,"difficulty":"Facile","imageSearch":"banana nice cream","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"frozen banana","plural":"frozen bananas","qty":4,"unit":"","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Slice the bananas before freezing them.","timer":null},{"text":"Blend them until they have an ice cream texture.","timer":null},{"text":"Add the cocoa if you like.","timer":null},{"text":"Serve straight away.","timer":null}],"kids":true,"dessert":true,"variant":"One ingredient","change":"Frozen bananas blended on their own."}]$r$::jsonb, 'claude')
