insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:sorbet', 'Sorbet', array['en:homemade sorbet', 'en:lemon sorbet', 'en:strawberry sorbet', 'en:mango sorbet']::text[], 'dish', $r$[{"title":"Lemon sorbet","intro":"A fresh, tangy lemon sorbet, with no ice cream maker.","minutes":20,"calories":150,"difficulty":"Facile","imageSearch":"lemon sorbet","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"lemon","plural":"lemons","qty":5,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":200,"unit":"g","have":false},{"name":"egg white","plural":"egg whites","qty":1,"unit":"","have":false}],"steps":[{"text":"Heat 50 cl of water with the sugar until it dissolves, then let it cool.","timer":null},{"text":"Add the juice of the lemons and the zest of one.","timer":null},{"text":"Freeze for 2 h, then beat with a fork.","timer":null},{"text":"Whisk the egg white until stiff, fold it in and freeze for another 4 h, beating twice.","timer":null}],"dessert":true,"variant":"The classic","change":""},{"title":"Strawberry sorbet","intro":"A fruity pink strawberry sorbet.","minutes":15,"calories":140,"difficulty":"Facile","imageSearch":"strawberry sorbet","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"strawberry","plural":"strawberries","qty":500,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":120,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false}],"steps":[{"text":"Blend the strawberries with the sugar and the lemon juice.","timer":null},{"text":"Pour into a tub and freeze.","timer":null},{"text":"Beat with a fork every hour for 4 h.","timer":null},{"text":"Serve in scoops.","timer":null}],"kids":true,"dessert":true,"variant":"Strawberry","change":"Made with blended strawberries."},{"title":"Mango sorbet","intro":"A quick mango sorbet, ready in 5 minutes.","minutes":5,"calories":130,"difficulty":"Facile","imageSearch":"mango sorbet","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"frozen mango","plural":"frozen mango","qty":500,"unit":"g","have":false},{"name":"honey","plural":"honey","qty":2,"unit":"tbsp","have":false},{"name":"lime","plural":"limes","qty":1,"unit":"","have":false}],"steps":[{"text":"Blend the frozen mango with the honey and the lime juice.","timer":null},{"text":"Blend until smooth.","timer":null},{"text":"Serve straight away or freeze for 30 min.","timer":null}],"dessert":true,"variant":"Mango","change":"With frozen mango, blended in minutes."}]$r$::jsonb, 'claude')
