insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:creme au chocolat', 'Chocolate pudding', array['en:chocolate pudding', 'en:chocolate cream dessert', 'en:chocolate custard', 'en:homemade chocolate pot']::text[], 'dish', $r$[{"title":"Chocolate cream dessert","intro":"A smooth, creamy chocolate dessert, like the ones in shop-bought pots.","minutes":15,"calories":250,"difficulty":"Facile","imageSearch":"chocolate pudding cups","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":100,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":50,"unit":"g","have":false},{"name":"cornflour","plural":"cornflour","qty":30,"unit":"g","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Mix the cornflour and the cocoa with a little cold milk.","timer":null},{"text":"Heat the rest of the milk with the sugar and the chopped chocolate.","timer":null},{"text":"Add the cornflour mixture and stir until the cream thickens.","timer":{"label":"Cooking","min":3}},{"text":"Pour into pots and chill for 2 h.","timer":null}],"kids":true,"dessert":true,"variant":"The classic","change":""},{"title":"Vanilla cream dessert","intro":"The classic vanilla cream dessert.","minutes":15,"calories":220,"difficulty":"Facile","imageSearch":"vanilla pudding","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"sugar","plural":"sugar","qty":60,"unit":"g","have":false},{"name":"cornflour","plural":"cornflour","qty":35,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"vanilla pod","plural":"vanilla pods","qty":1,"unit":"","have":false}],"steps":[{"text":"Heat the milk with the split vanilla pod.","timer":null},{"text":"Whisk the egg, the sugar and the cornflour.","timer":null},{"text":"Pour the hot milk over and put back on the heat, stirring until it thickens.","timer":{"label":"Cooking","min":3}},{"text":"Pour into pots and chill for 2 h.","timer":null}],"kids":true,"dessert":true,"variant":"Vanilla","change":"Flavoured with vanilla, with no chocolate."},{"title":"Dairy-free chocolate pudding","intro":"A lactose-free chocolate cream.","minutes":15,"calories":230,"difficulty":"Facile","imageSearch":"vegan chocolate pudding","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"oat milk","plural":"oat milk","qty":50,"unit":"cl","have":false},{"name":"dark chocolate","plural":"dark chocolate","qty":100,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":40,"unit":"g","have":false},{"name":"cornflour","plural":"cornflour","qty":30,"unit":"g","have":false}],"steps":[{"text":"Mix the cornflour with a little cold milk.","timer":null},{"text":"Heat the rest of the milk with the sugar and the chocolate.","timer":null},{"text":"Add the cornflour mixture and stir until it thickens.","timer":{"label":"Cooking","min":3}},{"text":"Pour into pots and chill for 2 h.","timer":null}],"dessert":true,"variant":"Dairy-free","change":"Made with oat milk, with no dairy."}]$r$::jsonb, 'claude')
