insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:empanada', 'Empanadas', array['en:argentinian turnover']::text[], 'dish', $r$[{"title":"Beef empanadas","intro":"Golden Argentinian turnovers filled with beef, onions and paprika.","minutes":60,"calories":380,"difficulty":"Moyen","imageSearch":"beef empanadas","veg":false,"oven":true,"cold":false,"missing":"","origin":"Argentinian recipe","serves":4,"items":[{"name":"shortcrust pastry","plural":"shortcrust pastries","qty":2,"unit":"","have":false},{"name":"minced beef","plural":"minced beef","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"paprika","plural":"paprika","qty":2,"unit":"tsp","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false}],"steps":[{"text":"Fry the diced onions and pepper, then add the beef and spices and cook for 8 min.","timer":{"label":"Pan","min":8}},{"text":"Hard-boil an egg for 10 min, chop it and add it to the filling.","timer":{"label":"Cooking","min":10}},{"text":"Preheat the oven to 200 °C. Cut 12 cm circles from the pastry.","timer":null},{"text":"Spoon the filling onto half of each circle, fold over and press the edges closed with a fork.","timer":null},{"text":"Brush with the second beaten egg and bake for 20 min.","timer":{"label":"Oven","min":20}}],"makes":{"n":12,"one":"empanada","many":"empanadas"},"variant":"The classic","change":""},{"title":"Chicken empanadas","intro":"Milder empanadas filled with chicken.","minutes":60,"calories":350,"difficulty":"Moyen","imageSearch":"chicken empanadas","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"shortcrust pastry","plural":"shortcrust pastries","qty":2,"unit":"","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"sweetcorn","plural":"sweetcorn","qty":140,"unit":"g","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false}],"steps":[{"text":"Fry the onion and pepper, then the diced chicken with the paprika.","timer":{"label":"Pan","min":8}},{"text":"Add the sweetcorn.","timer":null},{"text":"Spoon the filling onto circles of pastry, fold over and seal.","timer":null},{"text":"Brush with egg and bake for 20 min at 200 °C.","timer":{"label":"Oven","min":20}}],"makes":{"n":12,"one":"empanada","many":"empanadas"},"variant":"Chicken","change":"Filled with chicken, sweetcorn and pepper."},{"title":"Cheese empanadas","intro":"Melting vegetarian empanadas.","minutes":50,"calories":340,"difficulty":"Moyen","imageSearch":"cheese spinach empanadas","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"shortcrust pastry","plural":"shortcrust pastries","qty":2,"unit":"","have":false},{"name":"baby spinach","plural":"baby spinach","qty":200,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarella","qty":1,"unit":"","have":false},{"name":"feta","plural":"feta","qty":100,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false}],"steps":[{"text":"Soften the onion and spinach.","timer":{"label":"Pan","min":5}},{"text":"Mix with the diced mozzarella and crumbled feta.","timer":null},{"text":"Spoon the filling onto circles of pastry, fold over and seal.","timer":null},{"text":"Brush with egg and bake for 20 min at 200 °C.","timer":{"label":"Oven","min":20}}],"makes":{"n":12,"one":"empanada","many":"empanadas"},"variant":"Vegetarian","change":"Filled with cheese and spinach."}]$r$::jsonb, 'claude')
