insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:quesadilla', 'Quesadillas', array['en:chicken quesadilla', 'en:cheese quesadilla']::text[], 'dish', $r$[{"title":"Chicken quesadillas","intro":"Tortillas crisped in a pan and filled with chicken, peppers and melted cheese.","minutes":25,"calories":480,"difficulty":"Facile","imageSearch":"chicken quesadillas","veg":false,"oven":false,"cold":false,"missing":"","origin":"Mexican recipe","serves":4,"items":[{"name":"wheat tortilla","plural":"wheat tortillas","qty":8,"unit":"","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"grated cheddar","plural":"grated cheddar","qty":150,"unit":"g","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":4,"unit":"tbsp","have":false}],"steps":[{"text":"Fry the sliced chicken with the pepper and paprika for 8 min.","timer":{"label":"Pan","min":8}},{"text":"Top 4 tortillas with cheese, chicken and more cheese.","timer":null},{"text":"Cover with a second tortilla.","timer":null},{"text":"Brown for 2 min on each side in a dry pan.","timer":{"label":"Pan","min":4}},{"text":"Cut into wedges and serve with the crème fraîche.","timer":null}],"kids":true,"makes":{"n":4,"one":"quesadilla","many":"quesadillas"},"variant":"The classic","change":""},{"title":"Cheese and bean quesadillas","intro":"Melting vegetarian quesadillas.","minutes":20,"calories":450,"difficulty":"Facile","imageSearch":"bean cheese quesadillas","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"wheat tortilla","plural":"wheat tortillas","qty":8,"unit":"","have":false},{"name":"kidney beans","plural":"kidney beans","qty":250,"unit":"g","have":false},{"name":"sweetcorn","plural":"sweetcorn","qty":140,"unit":"g","have":false},{"name":"grated cheddar","plural":"grated cheddar","qty":150,"unit":"g","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Roughly mash the beans with the cumin.","timer":null},{"text":"Spread them over 4 tortillas, then add the sweetcorn and cheese.","timer":null},{"text":"Cover with a second tortilla.","timer":null},{"text":"Brown for 2 min on each side.","timer":{"label":"Pan","min":4}}],"kids":true,"makes":{"n":4,"one":"quesadilla","many":"quesadillas"},"variant":"Vegetarian","change":"With kidney beans and sweetcorn."},{"title":"Ham quesadillas","intro":"The ham and cheese quesadilla that kids love.","minutes":15,"calories":420,"difficulty":"Facile","imageSearch":"ham cheese quesadilla","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"wheat tortilla","plural":"wheat tortillas","qty":8,"unit":"","have":false},{"name":"cooked ham","plural":"cooked ham","qty":4,"unit":"slices","have":false},{"name":"grated emmental","plural":"grated emmental","qty":150,"unit":"g","have":false},{"name":"tomato","plural":"tomatoes","qty":1,"unit":"","have":false}],"steps":[{"text":"Top 4 tortillas with cheese, ham and diced tomato.","timer":null},{"text":"Cover with a second tortilla.","timer":null},{"text":"Brown for 2 min on each side.","timer":{"label":"Pan","min":4}},{"text":"Cut into wedges.","timer":null}],"kids":true,"makes":{"n":4,"one":"quesadilla","many":"quesadillas"},"variant":"Ham and cheese","change":"With ham and cheese, like a croque."}]$r$::jsonb, 'claude')
