insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:enchilada', 'Enchiladas', array['en:chicken enchilada']::text[], 'dish', $r$[{"title":"Chicken enchiladas","intro":"Tortillas rolled around chicken, covered in spicy tomato sauce and baked until golden.","minutes":50,"calories":560,"difficulty":"Facile","imageSearch":"chicken enchiladas","veg":false,"oven":true,"cold":false,"missing":"","origin":"Mexican recipe","serves":4,"items":[{"name":"wheat tortilla","plural":"wheat tortillas","qty":8,"unit":"","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":3,"unit":"","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":600,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"chilli","plural":"chillies","qty":1,"unit":"","have":false},{"name":"grated cheddar","plural":"grated cheddar","qty":150,"unit":"g","have":false}],"steps":[{"text":"Poach the chicken in simmering water for 15 min, then shred it.","timer":{"label":"Cooking","min":15}},{"text":"Fry the onion, add the tomatoes, cumin and chilli, and leave for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Preheat the oven to 200 °C. Mix the chicken with a third of the sauce.","timer":null},{"text":"Roll the chicken up in the tortillas and arrange them in a dish.","timer":null},{"text":"Pour over the rest of the sauce, top with cheddar and bake for 20 min.","timer":{"label":"Oven","min":20}}],"variant":"The classic","change":""},{"title":"Beef enchiladas","intro":"Generous beef enchiladas.","minutes":50,"calories":620,"difficulty":"Facile","imageSearch":"beef enchiladas","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"wheat tortilla","plural":"wheat tortillas","qty":8,"unit":"","have":false},{"name":"minced beef","plural":"minced beef","qty":400,"unit":"g","have":false},{"name":"kidney beans","plural":"kidney beans","qty":250,"unit":"g","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":600,"unit":"g","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"grated cheddar","plural":"grated cheddar","qty":150,"unit":"g","have":false}],"steps":[{"text":"Fry the beef with the cumin, then add the beans.","timer":{"label":"Pan","min":8}},{"text":"Heat the tomatoes for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Roll the filling up in the tortillas and arrange them in a dish.","timer":null},{"text":"Pour over the sauce, top with cheddar and bake for 20 min at 200 °C.","timer":{"label":"Oven","min":20}}],"variant":"Beef","change":"Filled with minced beef and beans."},{"title":"Vegetarian enchiladas","intro":"Sweet, spicy vegetarian enchiladas.","minutes":55,"calories":500,"difficulty":"Facile","imageSearch":"vegetarian enchiladas sweet potato","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"wheat tortilla","plural":"wheat tortillas","qty":8,"unit":"","have":false},{"name":"sweet potato","plural":"sweet potatoes","qty":2,"unit":"","have":false},{"name":"black beans","plural":"black beans","qty":250,"unit":"g","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":600,"unit":"g","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"grated cheddar","plural":"grated cheddar","qty":120,"unit":"g","have":false}],"steps":[{"text":"Boil the diced sweet potato for 12 min.","timer":{"label":"Cooking","min":12}},{"text":"Mix it with the beans and cumin.","timer":null},{"text":"Roll up in the tortillas and arrange them in a dish.","timer":null},{"text":"Pour over the tomatoes, top with cheddar and bake for 20 min at 200 °C.","timer":{"label":"Oven","min":20}}],"variant":"Vegetarian","change":"Filled with sweet potato and black beans."}]$r$::jsonb, 'claude')
