insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:nacho', 'Nachos', array['en:loaded nacho', 'en:cheese nacho', 'en:tortilla chip']::text[], 'dish', $r$[{"title":"Loaded nachos","intro":"Tortilla chips baked with cheddar and topped with guacamole, salsa and soured cream.","minutes":20,"calories":520,"difficulty":"Facile","imageSearch":"loaded nachos","veg":true,"oven":true,"cold":false,"missing":"","origin":"Tex-mex inspired","serves":4,"items":[{"name":"tortilla chips","plural":"tortilla chips","qty":200,"unit":"g","have":false},{"name":"grated cheddar","plural":"grated cheddar","qty":150,"unit":"g","have":false},{"name":"tomato","plural":"tomatoes","qty":2,"unit":"","have":false},{"name":"red onion","plural":"red onions","qty":0.5,"unit":"","have":false},{"name":"avocado","plural":"avocados","qty":1,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":4,"unit":"tbsp","have":false},{"name":"jalapeño","plural":"jalapeños","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Spread the chips in a dish and cover with cheddar.","timer":null},{"text":"Bake for 8 min.","timer":{"label":"Oven","min":8}},{"text":"Mix the diced tomatoes with the onion to make a salsa, and mash the avocado.","timer":null},{"text":"Top the nachos with salsa, avocado, crème fraîche and jalapeño.","timer":null}],"variant":"The classic","change":""},{"title":"Chilli nachos","intro":"Nachos as a full meal, topped with beef chilli.","minutes":30,"calories":650,"difficulty":"Facile","imageSearch":"beef chili nachos","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"tortilla chips","plural":"tortilla chips","qty":200,"unit":"g","have":false},{"name":"minced beef","plural":"minced beef","qty":300,"unit":"g","have":false},{"name":"kidney beans","plural":"kidney beans","qty":250,"unit":"g","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":200,"unit":"g","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"grated cheddar","plural":"grated cheddar","qty":150,"unit":"g","have":false}],"steps":[{"text":"Fry the beef with the cumin, add the beans and tomatoes, and leave for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Spread the chips and cover with chilli and cheddar.","timer":null},{"text":"Bake for 8 min.","timer":{"label":"Oven","min":8}}],"variant":"Chilli","change":"With spicy minced beef."},{"title":"Chicken nachos","intro":"Baked nachos with chicken and sweetcorn.","minutes":30,"calories":560,"difficulty":"Facile","imageSearch":"chicken nachos","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"tortilla chips","plural":"tortilla chips","qty":200,"unit":"g","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"sweetcorn","plural":"sweetcorn","qty":140,"unit":"g","have":false},{"name":"grated cheddar","plural":"grated cheddar","qty":150,"unit":"g","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":4,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the sliced chicken with the paprika.","timer":{"label":"Pan","min":8}},{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Spread the chips and add the chicken, sweetcorn and cheddar.","timer":null},{"text":"Bake for 8 min and serve with the crème fraîche.","timer":{"label":"Oven","min":8}}],"variant":"Chicken","change":"With shredded chicken."}]$r$::jsonb, 'claude')
