insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:hot dog', 'Hot dog', array['en:homemade hot dog', 'en:hotdog']::text[], 'dish', $r$[{"title":"Homemade hot dogs","intro":"Sausages in soft rolls, with fried onions, ketchup and mustard.","minutes":20,"calories":480,"difficulty":"Facile","imageSearch":"hot dog","veg":false,"oven":false,"cold":false,"missing":"","origin":"American recipe","serves":4,"items":[{"name":"hot dog roll","plural":"hot dog rolls","qty":4,"unit":"","have":false},{"name":"frankfurter","plural":"frankfurters","qty":4,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"ketchup","plural":"ketchup","qty":4,"unit":"tbsp","have":false},{"name":"mustard","plural":"mustard","qty":4,"unit":"tsp","have":false},{"name":"oil","plural":"oil","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Brown the sliced onions in the oil for 10 min.","timer":{"label":"Pan","min":10}},{"text":"Heat the sausages for 5 min in simmering water.","timer":{"label":"Cooking","min":5}},{"text":"Warm the rolls in the oven.","timer":null},{"text":"Fill each roll with a sausage, onions, ketchup and mustard.","timer":null}],"kids":true,"makes":{"n":4,"one":"hot dog","many":"hot dogs"},"variant":"The classic","change":""},{"title":"Cheesy hot dogs","intro":"The French-style hot dog, baked with emmental.","minutes":20,"calories":560,"difficulty":"Facile","imageSearch":"cheese hot dog","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"hot dog roll","plural":"hot dog rolls","qty":4,"unit":"","have":false},{"name":"strasbourg sausage","plural":"strasbourg sausages","qty":4,"unit":"","have":false},{"name":"grated emmental","plural":"grated emmental","qty":100,"unit":"g","have":false},{"name":"mustard","plural":"mustard","qty":4,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Spread mustard in the rolls and put a sausage in each.","timer":null},{"text":"Cover with emmental.","timer":null},{"text":"Bake for 10 min.","timer":{"label":"Oven","min":10}}],"kids":true,"makes":{"n":4,"one":"hot dog","many":"hot dogs"},"variant":"Baked with cheese","change":"Baked in the oven with cheese."},{"title":"Vegetarian hot dogs","intro":"The meat-free hot dog, with fresh crunchy toppings.","minutes":15,"calories":420,"difficulty":"Facile","imageSearch":"veggie hot dog","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"hot dog roll","plural":"hot dog rolls","qty":4,"unit":"","have":false},{"name":"vegetarian sausage","plural":"vegetarian sausages","qty":4,"unit":"","have":false},{"name":"red onion","plural":"red onions","qty":1,"unit":"","have":false},{"name":"gherkin","plural":"gherkins","qty":4,"unit":"","have":false},{"name":"ketchup","plural":"ketchup","qty":4,"unit":"tbsp","have":false}],"steps":[{"text":"Brown the vegetarian sausages for 6 min in a pan.","timer":{"label":"Pan","min":6}},{"text":"Cut the onion and gherkins into small dice.","timer":null},{"text":"Fill the warm rolls.","timer":null},{"text":"Add the ketchup.","timer":null}],"kids":true,"makes":{"n":4,"one":"hot dog","many":"hot dogs"},"variant":"Vegetarian","change":"With vegetarian sausages."}]$r$::jsonb, 'claude')
