insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:bagel', 'Bagels', array['en:salmon bagel', 'en:homemade bagel']::text[], 'dish', $r$[{"title":"Salmon and cream cheese bagels","intro":"The New York bagel with cream cheese, smoked salmon, red onion and dill.","minutes":10,"calories":420,"difficulty":"Facile","imageSearch":"salmon cream cheese bagel","veg":false,"oven":false,"cold":true,"missing":"","origin":"New York recipe","serves":4,"items":[{"name":"bagel","plural":"bagels","qty":4,"unit":"","have":false},{"name":"cream cheese","plural":"cream cheese","qty":150,"unit":"g","have":false},{"name":"smoked salmon","plural":"smoked salmon","qty":4,"unit":"slices","have":false},{"name":"red onion","plural":"red onions","qty":0.5,"unit":"","have":false},{"name":"dill","plural":"dill","qty":null,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":0.5,"unit":"","have":false}],"steps":[{"text":"Cut the bagels in half and toast them.","timer":null},{"text":"Spread with cream cheese.","timer":null},{"text":"Add the salmon, sliced onion and dill.","timer":null},{"text":"Squeeze over a little lemon juice and close up.","timer":null}],"makes":{"n":4,"one":"bagel","many":"bagels"},"variant":"The classic","change":""},{"title":"Chicken and salad bagels","intro":"A filling chicken bagel for lunch.","minutes":15,"calories":450,"difficulty":"Facile","imageSearch":"chicken bagel sandwich","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"bagel","plural":"bagels","qty":4,"unit":"","have":false},{"name":"cooked chicken breast","plural":"cooked chicken breasts","qty":2,"unit":"","have":false},{"name":"lettuce","plural":"lettuce","qty":1,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":2,"unit":"","have":false},{"name":"greek yoghurt","plural":"greek yoghurts","qty":1,"unit":"","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Mix the yoghurt and mustard.","timer":null},{"text":"Cut the bagels in half and spread with the sauce.","timer":null},{"text":"Add the lettuce, sliced tomato and sliced chicken.","timer":null},{"text":"Close up.","timer":null}],"makes":{"n":4,"one":"bagel","many":"bagels"},"variant":"Chicken","change":"With chicken, lettuce and a yoghurt sauce."},{"title":"Vegetarian bagels","intro":"A vegetarian bagel with avocado and egg.","minutes":15,"calories":430,"difficulty":"Facile","imageSearch":"avocado egg bagel","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"bagel","plural":"bagels","qty":4,"unit":"","have":false},{"name":"avocado","plural":"avocados","qty":2,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"cream cheese","plural":"cream cheese","qty":100,"unit":"g","have":false},{"name":"rocket","plural":"rocket","qty":40,"unit":"g","have":false}],"steps":[{"text":"Boil the eggs for 9 min and slice them.","timer":{"label":"Cooking","min":9}},{"text":"Spread the toasted bagels with cream cheese.","timer":null},{"text":"Add the sliced avocado, egg and rocket.","timer":null},{"text":"Season with salt and pepper and close up.","timer":null}],"makes":{"n":4,"one":"bagel","many":"bagels"},"variant":"Vegetarian","change":"With avocado, egg and cream cheese."}]$r$::jsonb, 'claude')
