insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:poutine', 'Poutine', array['en:quebec poutine', 'en:chip with cheese and gravy']::text[], 'dish', $r$[{"title":"Poutine","intro":"The Quebec dish: chips, cheese curds and piping hot brown gravy.","minutes":50,"calories":750,"difficulty":"Facile","imageSearch":"poutine","veg":false,"oven":false,"cold":false,"missing":"","origin":"Quebec recipe","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"frying oil","plural":"frying oil","qty":100,"unit":"cl","have":false},{"name":"cheddar","plural":"cheddar","qty":200,"unit":"g","have":false},{"name":"beef stock cube","plural":"beef stock cubes","qty":2,"unit":"","have":false},{"name":"cornflour","plural":"cornflour","qty":2,"unit":"tbsp","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false}],"steps":[{"text":"Cut the potatoes into chips and fry them twice: 6 min at 160 °C, then 3 min at 180 °C.","timer":{"label":"Frying","min":9}},{"text":"Heat 40 cl of water with the stock cubes and butter.","timer":null},{"text":"Add the cornflour mixed with a little water and leave to thicken.","timer":{"label":"Cooking","min":3}},{"text":"Cut the cheddar into small pieces.","timer":null},{"text":"Put the chips on plates, add the cheese and pour over the boiling gravy.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Oven-baked poutine","intro":"A slightly lighter poutine with oven-baked chips.","minutes":50,"calories":620,"difficulty":"Facile","imageSearch":"oven fries poutine","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"cheddar","plural":"cheddar","qty":200,"unit":"g","have":false},{"name":"beef stock cube","plural":"beef stock cubes","qty":2,"unit":"","have":false},{"name":"cornflour","plural":"cornflour","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Preheat the oven to 220 °C. Cut the potatoes into chips and toss them with the oil.","timer":null},{"text":"Bake for 35 min, turning them over halfway.","timer":{"label":"Oven","min":35}},{"text":"Make the gravy with the stock and cornflour.","timer":{"label":"Cooking","min":3}},{"text":"Top the chips with cheese and pour over the gravy.","timer":null}],"kids":true,"variant":"Oven chips","change":"With oven chips."},{"title":"Chicken poutine","intro":"Poutine as a full meal, with chicken.","minutes":55,"calories":800,"difficulty":"Facile","imageSearch":"chicken poutine","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"frying oil","plural":"frying oil","qty":100,"unit":"cl","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"cheddar","plural":"cheddar","qty":200,"unit":"g","have":false},{"name":"chicken stock cube","plural":"chicken stock cubes","qty":2,"unit":"","have":false},{"name":"cornflour","plural":"cornflour","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the chicken for 15 min in the stock cubes dissolved in 40 cl of water, then shred it.","timer":{"label":"Cooking","min":15}},{"text":"Thicken the stock with the cornflour.","timer":{"label":"Cooking","min":3}},{"text":"Fry the chips in two stages.","timer":{"label":"Frying","min":9}},{"text":"Top the chips with the chicken and cheese, and pour over the gravy.","timer":null}],"variant":"Chicken","change":"With shredded chicken."}]$r$::jsonb, 'claude')
