insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:goulash', 'Goulash', array['en:goulasch', 'en:paprika beef stew']::text[], 'dish', $r$[{"title":"Goulash","intro":"The Hungarian beef stew with paprika, onions and peppers.","minutes":150,"calories":520,"difficulty":"Facile","imageSearch":"hungarian goulash","veg":false,"oven":false,"cold":false,"missing":"","origin":"Hungarian recipe","serves":4,"items":[{"name":"braising beef","plural":"braising beef","qty":1000,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":3,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":2,"unit":"","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"paprika","plural":"paprika","qty":3,"unit":"tbsp","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"potato","plural":"potatoes","qty":4,"unit":"","have":false}],"steps":[{"text":"Cut the beef into cubes and brown it in a casserole dish.","timer":{"label":"Cooking","min":10}},{"text":"Add the sliced onions and soften for 5 min.","timer":null},{"text":"Add the paprika, cumin, tomatoes and 50 cl of water.","timer":null},{"text":"Cover and simmer for 1 h 30.","timer":{"label":"Cooking","min":90}},{"text":"Add the peppers and diced potatoes, and cook for another 30 min.","timer":{"label":"Cooking","min":30}}],"variant":"The classic","change":""},{"title":"Pork goulash","intro":"A more tender goulash made with pork shoulder.","minutes":90,"calories":540,"difficulty":"Facile","imageSearch":"pork goulash","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pork shoulder","plural":"pork shoulder","qty":800,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":3,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":2,"unit":"","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"paprika","plural":"paprika","qty":3,"unit":"tbsp","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false}],"steps":[{"text":"Brown the cubed pork with the onions.","timer":{"label":"Cooking","min":10}},{"text":"Add the paprika, tomatoes and 30 cl of water.","timer":null},{"text":"Simmer for 50 min.","timer":{"label":"Cooking","min":50}},{"text":"Add the peppers and cook for 20 min, then stir in the crème fraîche.","timer":{"label":"Cooking","min":20}}],"variant":"Pork","change":"With pork shoulder."},{"title":"Vegetarian goulash","intro":"A comforting vegetarian goulash.","minutes":50,"calories":380,"difficulty":"Facile","imageSearch":"vegetarian goulash","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":6,"unit":"","have":false},{"name":"kidney beans","plural":"kidney beans","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":2,"unit":"","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"paprika","plural":"paprika","qty":3,"unit":"tbsp","have":false}],"steps":[{"text":"Fry the onions and peppers.","timer":null},{"text":"Add the paprika, diced potatoes, tomatoes and 40 cl of water.","timer":null},{"text":"Simmer for 30 min.","timer":{"label":"Cooking","min":30}},{"text":"Add the beans and cook for 5 min.","timer":{"label":"Cooking","min":5}}],"variant":"Vegetarian","change":"With potatoes and kidney beans."}]$r$::jsonb, 'claude')
