insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:boeuf stroganoff', 'Beef Stroganoff', array['en:beef stroganoff', 'en:stroganoff', 'en:beef stroganov']::text[], 'dish', $r$[{"title":"Beef Stroganoff","intro":"Strips of beef seared in a creamy mushroom and paprika sauce.","minutes":30,"calories":560,"difficulty":"Facile","imageSearch":"beef stroganoff","veg":false,"oven":false,"cold":false,"missing":"","origin":"Russian recipe","serves":4,"items":[{"name":"fondue beef","plural":"fondue beef","qty":600,"unit":"g","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":250,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tsp","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"tagliatelle","plural":"tagliatelle","qty":300,"unit":"g","have":false}],"steps":[{"text":"Cook the tagliatelle.","timer":{"label":"Cooking","min":10}},{"text":"Cut the beef into strips and sear for 2 min over a high heat. Take it out.","timer":{"label":"Pan","min":2}},{"text":"Fry the sliced onion and mushrooms for 6 min.","timer":{"label":"Pan","min":6}},{"text":"Add the crème fraîche, mustard and paprika.","timer":null},{"text":"Put the beef back for 1 min and serve with the tagliatelle.","timer":null}],"variant":"The classic","change":""},{"title":"Chicken Stroganoff","intro":"A milder, cheaper chicken Stroganoff.","minutes":30,"calories":500,"difficulty":"Facile","imageSearch":"chicken stroganoff","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":250,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Brown the chicken strips for 6 min.","timer":{"label":"Pan","min":6}},{"text":"Add the onion and mushrooms, and cook for 6 min.","timer":{"label":"Pan","min":6}},{"text":"Add the crème fraîche and paprika, and cook for 2 min.","timer":null}],"kids":true,"variant":"Chicken","change":"Chicken instead of beef."},{"title":"Mushroom Stroganoff","intro":"A rich vegetarian Stroganoff.","minutes":25,"calories":400,"difficulty":"Facile","imageSearch":"mushroom stroganoff","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"button mushroom","plural":"button mushrooms","qty":600,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tsp","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"tagliatelle","plural":"tagliatelle","qty":300,"unit":"g","have":false}],"steps":[{"text":"Cook the tagliatelle.","timer":{"label":"Cooking","min":10}},{"text":"Brown the quartered mushrooms for 8 min over a high heat.","timer":{"label":"Pan","min":8}},{"text":"Add the onion, then the crème fraîche, mustard and paprika.","timer":null},{"text":"Cook for 2 min and serve over the pasta.","timer":null}],"variant":"Vegetarian","change":"Mushrooms only."}]$r$::jsonb, 'claude')
