insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:shawarma', 'Shawarma', array['en:chicken shawarma', 'en:shawarma wrap']::text[], 'dish', $r$[{"title":"Chicken shawarma","intro":"Chicken marinated in Middle Eastern spices and rolled in pitta bread with garlic sauce.","minutes":50,"calories":520,"difficulty":"Facile","imageSearch":"chicken shawarma wrap","veg":false,"oven":false,"cold":false,"missing":"","origin":"Lebanese inspired","serves":4,"items":[{"name":"boneless chicken thigh","plural":"boneless chicken thighs","qty":6,"unit":"","have":false},{"name":"pitta bread","plural":"pitta breads","qty":4,"unit":"","have":false},{"name":"greek yoghurt","plural":"greek yoghurts","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":2,"unit":"","have":false},{"name":"lettuce","plural":"lettuce","qty":1,"unit":"","have":false}],"steps":[{"text":"Marinate the chicken for 30 min with 1 yoghurt, 2 cloves of garlic, the spices and the lemon juice.","timer":{"label":"Rest","min":30}},{"text":"Brown it in a pan for 10 min, then slice it.","timer":{"label":"Pan","min":10}},{"text":"Mix the other yoghurt with the remaining crushed garlic.","timer":null},{"text":"Fill the warm pittas with chicken, lettuce, tomatoes and sauce.","timer":null}],"makes":{"n":4,"one":"pita","many":"pitas"},"variant":"The classic","change":""},{"title":"Chicken shawarma plate","intro":"Shawarma served on a plate, with rice and hummus.","minutes":50,"calories":560,"difficulty":"Facile","imageSearch":"chicken shawarma plate","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"boneless chicken thigh","plural":"boneless chicken thighs","qty":6,"unit":"","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false},{"name":"hummus","plural":"hummus","qty":200,"unit":"g","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":1,"unit":"","have":false}],"steps":[{"text":"Marinate the chicken with the spices and lemon for 30 min.","timer":{"label":"Rest","min":30}},{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Brown the chicken for 10 min and slice it.","timer":{"label":"Pan","min":10}},{"text":"Serve with the rice, hummus and cucumber.","timer":null}],"variant":"On a plate","change":"Served with rice and salad."},{"title":"Cauliflower shawarma","intro":"The vegetarian shawarma, with roasted cauliflower.","minutes":45,"calories":380,"difficulty":"Facile","imageSearch":"cauliflower shawarma","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cauliflower","plural":"cauliflowers","qty":1,"unit":"","have":false},{"name":"pitta bread","plural":"pitta breads","qty":4,"unit":"","have":false},{"name":"greek yoghurt","plural":"greek yoghurts","qty":1,"unit":"","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false}],"steps":[{"text":"Preheat the oven to 210 °C.","timer":null},{"text":"Toss the cauliflower florets with the oil and spices, and bake for 30 min.","timer":{"label":"Oven","min":30}},{"text":"Mix the yoghurt with the crushed garlic.","timer":null},{"text":"Fill the pittas with cauliflower and sauce.","timer":null}],"makes":{"n":4,"one":"pita","many":"pitas"},"variant":"Vegetarian","change":"Roasted cauliflower with shawarma spices."}]$r$::jsonb, 'claude')
