insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:coquillette au jambon', 'Macaroni with ham', array['en:macaroni with ham', 'en:ham macaroni', 'en:macaroni ham and cheese', 'en:ham pasta']::text[], 'dish', $r$[{"title":"Macaroni with ham","intro":"The childhood comfort dish: buttery macaroni with ham and grated cheese.","minutes":15,"calories":480,"difficulty":"Facile","imageSearch":"macaroni ham cheese","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"macaroni","plural":"macaroni","qty":400,"unit":"g","have":false},{"name":"cooked ham","plural":"cooked ham","qty":4,"unit":"slices","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"grated emmental","plural":"grated emmental","qty":80,"unit":"g","have":false}],"steps":[{"text":"Cook the macaroni in salted water.","timer":{"label":"Cooking","min":9}},{"text":"Cut the ham into small pieces.","timer":null},{"text":"Drain the pasta and toss with the butter and ham.","timer":null},{"text":"Sprinkle with emmental and serve straight away.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Creamy ham macaroni","intro":"Creamy macaroni with ham and mushrooms.","minutes":20,"calories":560,"difficulty":"Facile","imageSearch":"creamy ham pasta mushrooms","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"macaroni","plural":"macaroni","qty":400,"unit":"g","have":false},{"name":"cooked ham","plural":"cooked ham","qty":4,"unit":"slices","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":150,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":15,"unit":"cl","have":false},{"name":"grated emmental","plural":"grated emmental","qty":60,"unit":"g","have":false}],"steps":[{"text":"Cook the macaroni.","timer":{"label":"Cooking","min":9}},{"text":"Fry the sliced mushrooms for 5 min.","timer":{"label":"Pan","min":5}},{"text":"Add the crème fraîche and the chopped ham.","timer":null},{"text":"Toss with the pasta and emmental.","timer":null}],"kids":true,"variant":"Creamy","change":"With cream and mushrooms."},{"title":"Risotto-style macaroni","intro":"The creamy bistro macaroni, cooked in stock.","minutes":25,"calories":500,"difficulty":"Facile","imageSearch":"pasta risotto ham parmesan","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"macaroni","plural":"macaroni","qty":400,"unit":"g","have":false},{"name":"cooked ham","plural":"cooked ham","qty":4,"unit":"slices","have":false},{"name":"chicken stock","plural":"chicken stock","qty":1,"unit":"","have":false},{"name":"parmesan","plural":"parmesan","qty":60,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"shallot","plural":"shallots","qty":1,"unit":"","have":false}],"steps":[{"text":"Fry the shallot in the butter, add the macaroni and stir for 1 min.","timer":null},{"text":"Add the hot stock a ladle at a time, stirring, as for a risotto.","timer":{"label":"Cooking","min":12}},{"text":"Add the parmesan and diced ham.","timer":null},{"text":"Serve nice and creamy.","timer":null}],"kids":true,"variant":"Risotto-style","change":"Cooked like a risotto, in stock, with parmesan."}]$r$::jsonb, 'claude')
