insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:oeuf a la coque', 'Soft-boiled eggs', array['en:soft boiled egg', 'en:egg and soldier', 'en:boiled egg with soldier']::text[], 'dish', $r$[{"title":"Soft-boiled eggs and soldiers","intro":"Runny-yolk eggs with buttered toast soldiers for dipping.","minutes":10,"calories":250,"difficulty":"Facile","imageSearch":"soft boiled eggs soldiers","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"egg","plural":"eggs","qty":8,"unit":"","have":false},{"name":"sliced white bread","plural":"sliced white bread","qty":6,"unit":"slices","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Bring a pan of water to the boil.","timer":null},{"text":"Gently lower in the eggs and time for 3 min.","timer":{"label":"Cooking","min":3}},{"text":"Meanwhile, toast the bread, butter it and cut into fingers.","timer":null},{"text":"Serve the eggs in egg cups with the soldiers.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Soft-boiled eggs and asparagus","intro":"A spring version, with asparagus for dipping.","minutes":15,"calories":200,"difficulty":"Facile","imageSearch":"soft boiled eggs asparagus","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"egg","plural":"eggs","qty":8,"unit":"","have":false},{"name":"green asparagus","plural":"green asparagus","qty":500,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":15,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the asparagus for 6 min in salted water.","timer":{"label":"Cooking","min":6}},{"text":"Lower the eggs into boiling water for 3 min.","timer":{"label":"Cooking","min":3}},{"text":"Serve the eggs with the buttered asparagus.","timer":null},{"text":"Add salt just before dipping.","timer":null}],"variant":"Asparagus","change":"Green asparagus instead of soldiers."},{"title":"Soft-boiled eggs and ham soldiers","intro":"Tastier soldiers, wrapped in cured ham.","minutes":10,"calories":300,"difficulty":"Facile","imageSearch":"eggs soldiers prosciutto","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"egg","plural":"eggs","qty":8,"unit":"","have":false},{"name":"sliced white bread","plural":"sliced white bread","qty":6,"unit":"slices","have":false},{"name":"cured ham","plural":"cured ham","qty":6,"unit":"slices","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false}],"steps":[{"text":"Toast the bread, butter it and cut into fingers.","timer":null},{"text":"Wrap half a slice of cured ham around each soldier.","timer":null},{"text":"Lower the eggs into boiling water for 3 min.","timer":{"label":"Cooking","min":3}},{"text":"Serve straight away.","timer":null}],"variant":"With ham","change":"Soldiers wrapped in cured ham."}]$r$::jsonb, 'claude')
