insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:galette complete', 'Buckwheat galette', array['en:buckwheat galette', 'en:breton galette', 'en:savoury crepe']::text[], 'dish', $r$[{"title":"Galette complète","intro":"The Breton buckwheat galette with ham, egg and emmental.","minutes":80,"calories":450,"difficulty":"Facile","imageSearch":"galette complete buckwheat crepe","veg":false,"oven":false,"cold":false,"missing":"","origin":"Breton speciality","serves":4,"items":[{"name":"buckwheat flour","plural":"buckwheat flour","qty":250,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":5,"unit":"","have":false},{"name":"cooked ham","plural":"cooked ham","qty":4,"unit":"slices","have":false},{"name":"grated emmental","plural":"grated emmental","qty":120,"unit":"g","have":false},{"name":"salted butter","plural":"salted butter","qty":40,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Mix the flour, 1 egg, a pinch of salt and 60 cl of cold water. Leave to rest for 1 h.","timer":{"label":"Rest","min":60}},{"text":"Cook a galette for 2 min in a buttered pan.","timer":{"label":"Pan","min":2}},{"text":"Turn it over, add the emmental and ham, and break an egg into the middle.","timer":null},{"text":"Fold the edges into a square and cook until the white is set.","timer":{"label":"Pan","min":3}}],"kids":true,"makes":{"n":8,"one":"galette","many":"galettes"},"variant":"The classic","change":""},{"title":"Sausage galette","intro":"The galette-saucisse from the Breton markets.","minutes":80,"calories":520,"difficulty":"Facile","imageSearch":"galette saucisse","veg":false,"oven":false,"cold":false,"missing":"","origin":"Breton speciality","serves":4,"items":[{"name":"buckwheat flour","plural":"buckwheat flour","qty":250,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"toulouse sausage","plural":"toulouse sausages","qty":4,"unit":"","have":false},{"name":"salted butter","plural":"salted butter","qty":30,"unit":"g","have":false},{"name":"mustard","plural":"mustard","qty":4,"unit":"tsp","have":false}],"steps":[{"text":"Make the batter and leave to rest for 1 h.","timer":{"label":"Rest","min":60}},{"text":"Grill the sausages for 15 min.","timer":{"label":"Pan","min":15}},{"text":"Cook the galettes.","timer":{"label":"Pan","min":2}},{"text":"Spread with mustard and roll each galette around a sausage.","timer":null}],"kids":true,"makes":{"n":8,"one":"galette","many":"galettes"},"variant":"Sausage","change":"Rolled around a grilled sausage."},{"title":"Goat's cheese and spinach galette","intro":"A vegetarian galette with melting goat's cheese.","minutes":80,"calories":420,"difficulty":"Facile","imageSearch":"goat cheese spinach galette","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"buckwheat flour","plural":"buckwheat flour","qty":250,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"goat's cheese log","plural":"goat's cheese logs","qty":1,"unit":"","have":false},{"name":"baby spinach","plural":"baby spinach","qty":150,"unit":"g","have":false},{"name":"honey","plural":"honey","qty":2,"unit":"tbsp","have":false},{"name":"salted butter","plural":"salted butter","qty":30,"unit":"g","have":false}],"steps":[{"text":"Make the batter and leave to rest for 1 h.","timer":{"label":"Rest","min":60}},{"text":"Wilt the spinach for 2 min.","timer":{"label":"Pan","min":2}},{"text":"Cook a galette and top with spinach and slices of goat's cheese.","timer":null},{"text":"Fold in the edges, leave to melt for 2 min and drizzle with honey.","timer":{"label":"Pan","min":2}}],"makes":{"n":8,"one":"galette","many":"galettes"},"variant":"Vegetarian","change":"With goat's cheese, spinach and honey."}]$r$::jsonb, 'claude')
