insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:steak hache puree', 'Burger steak with mash', array['en:burger steak with mash', 'en:homemade burger steak', 'en:burger steak and mash', 'en:steak and mash']::text[], 'dish', $r$[{"title":"Burger steak with mash","intro":"Pan-fried minced beef steaks with homemade mashed potato.","minutes":30,"calories":560,"difficulty":"Facile","imageSearch":"burger patty mashed potatoes","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"minced beef steak","plural":"minced beef steaks","qty":4,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Boil the potatoes for 20 min in salted water.","timer":{"label":"Cooking","min":20}},{"text":"Mash them with the warm milk and butter.","timer":null},{"text":"Cook the steaks for 2 to 4 min on each side, depending on how you like them.","timer":{"label":"Pan","min":6}},{"text":"Season with salt and pepper and serve with the mash.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Homemade herby beef patties","intro":"Tasty homemade beef patties.","minutes":25,"calories":450,"difficulty":"Facile","imageSearch":"homemade beef patties herbs","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"minced beef","plural":"minced beef","qty":500,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"green bean","plural":"green beans","qty":500,"unit":"g","have":false}],"steps":[{"text":"Chop the onion and parsley and mix them with the beef and egg.","timer":null},{"text":"Shape into 4 patties.","timer":null},{"text":"Boil the green beans for 8 min.","timer":{"label":"Cooking","min":8}},{"text":"Brown the patties for 3 min on each side.","timer":{"label":"Pan","min":6}}],"kids":true,"variant":"Homemade","change":"Shaped by hand with herbs and onion."},{"title":"Burger steak with pepper sauce","intro":"The bistro burger steak with pepper sauce.","minutes":25,"calories":560,"difficulty":"Facile","imageSearch":"patty pepper sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"minced beef steak","plural":"minced beef steaks","qty":4,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":15,"unit":"cl","have":false},{"name":"crushed pepper","plural":"crushed pepper","qty":1,"unit":"tsp","have":false},{"name":"shallot","plural":"shallots","qty":1,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":800,"unit":"g","have":false}],"steps":[{"text":"Steam the potato wedges for 20 min.","timer":{"label":"Cooking","min":20}},{"text":"Cook the steaks and take them out of the pan.","timer":{"label":"Pan","min":6}},{"text":"Fry the shallot, add the crème fraîche and pepper, and reduce for 2 min.","timer":null},{"text":"Pour the sauce over the steaks.","timer":null}],"variant":"Pepper sauce","change":"With a creamy pepper sauce."}]$r$::jsonb, 'claude')
