insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:veloute de tomate', 'Cream of tomato soup', array['en:cream of tomato soup', 'en:tomato soup', 'en:creamy tomato soup']::text[], 'dish', $r$[{"title":"Cream of tomato soup","intro":"A smooth, mild tomato soup with basil and a swirl of cream.","minutes":35,"calories":160,"difficulty":"Facile","imageSearch":"tomato soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"tomato","plural":"tomatoes","qty":8,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":2,"unit":"tbsp","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Fry the onion and garlic.","timer":null},{"text":"Add the quartered tomatoes, sugar, stock cube and 40 cl of water.","timer":null},{"text":"Cook for 20 min.","timer":{"label":"Cooking","min":20}},{"text":"Blend with the crème fraîche and basil.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Roasted tomato soup","intro":"A more intense tomato soup, with oven-roasted tomatoes.","minutes":50,"calories":170,"difficulty":"Facile","imageSearch":"roasted tomato soup","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"tomato","plural":"tomatoes","qty":10,"unit":"","have":false},{"name":"red onion","plural":"red onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Put the halved tomatoes, onion and garlic in a dish with the oil and thyme.","timer":null},{"text":"Bake for 35 min.","timer":{"label":"Oven","min":35}},{"text":"Blend with the stock cube and 30 cl of hot water.","timer":null}],"variant":"Roasted","change":"The tomatoes are roasted before blending."},{"title":"Tomato soup and cheese toasties","intro":"Tomato soup and its melting cheese sandwich.","minutes":35,"calories":420,"difficulty":"Facile","imageSearch":"tomato soup grilled cheese","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":800,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"sliced white bread","plural":"sliced white bread","qty":8,"unit":"slices","have":false},{"name":"cheddar","plural":"cheddar","qty":8,"unit":"slices","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false}],"steps":[{"text":"Fry the onion, add the tomatoes, stock cube and 30 cl of water, and cook for 20 min.","timer":{"label":"Cooking","min":20}},{"text":"Blend the soup.","timer":null},{"text":"Fill the bread with cheddar, butter the outside and brown in a pan for 3 min on each side.","timer":{"label":"Pan","min":6}},{"text":"Cut into fingers and serve with the soup.","timer":null}],"kids":true,"variant":"With toasties","change":"Served with little cheese toasties for dipping."}]$r$::jsonb, 'claude')
