insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:pate a la sauce tomate', 'Pasta with tomato sauce', array['en:pasta with tomato sauce', 'en:tomato sauce', 'en:tomato pasta', 'en:spaghetti with tomato sauce', 'en:homemade tomato sauce']::text[], 'dish', $r$[{"title":"Pasta with homemade tomato sauce","intro":"Pasta with a proper homemade tomato sauce, with garlic and basil.","minutes":25,"calories":450,"difficulty":"Facile","imageSearch":"pasta tomato sauce","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pasta","plural":"pasta","qty":400,"unit":"g","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":800,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false},{"name":"parmesan","plural":"parmesan","qty":40,"unit":"g","have":false}],"steps":[{"text":"Fry the onion and garlic in the oil.","timer":null},{"text":"Add the tomatoes, season and simmer for 20 min.","timer":{"label":"Cooking","min":20}},{"text":"Cook the pasta.","timer":{"label":"Cooking","min":10}},{"text":"Toss with the sauce, basil and parmesan.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Pasta with hidden-veg tomato sauce","intro":"A tomato sauce full of vegetables that kids can't see.","minutes":35,"calories":430,"difficulty":"Facile","imageSearch":"hidden veggie pasta sauce","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pasta","plural":"pasta","qty":400,"unit":"g","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":800,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Fry the diced onion, carrot, courgette and pepper for 5 min.","timer":null},{"text":"Add the tomatoes and simmer for 25 min.","timer":{"label":"Cooking","min":25}},{"text":"Blend the sauce.","timer":null},{"text":"Cook the pasta and toss with the sauce.","timer":{"label":"Cooking","min":10}}],"kids":true,"variant":"Hidden veg","change":"With vegetables blended into the sauce."},{"title":"Tuna and tomato pasta","intro":"A tomato sauce enriched with tuna.","minutes":25,"calories":500,"difficulty":"Facile","imageSearch":"tuna tomato pasta","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pasta","plural":"pasta","qty":400,"unit":"g","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":800,"unit":"g","have":false},{"name":"tuna in water","plural":"tuna in water","qty":200,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"capers","plural":"capers","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Fry the garlic, add the tomatoes and cook for 15 min.","timer":{"label":"Cooking","min":15}},{"text":"Add the tuna and capers.","timer":null},{"text":"Cook the pasta.","timer":{"label":"Cooking","min":10}},{"text":"Toss with the sauce.","timer":null}],"kids":true,"variant":"Tuna","change":"With tuna and capers."}]$r$::jsonb, 'claude')
