insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:gratin de poisson', 'Fish gratin', array['en:fish gratin', 'en:white fish gratin', 'en:baked fish', 'en:cod gratin']::text[], 'dish', $r$[{"title":"Fish gratin","intro":"White fish in a béchamel sauce, topped with emmental and served with potatoes.","minutes":50,"calories":450,"difficulty":"Facile","imageSearch":"fish gratin","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"white fish fillet","plural":"white fish fillets","qty":600,"unit":"g","have":false},{"name":"potato","plural":"potatoes","qty":600,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"flour","plural":"flour","qty":40,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"grated emmental","plural":"grated emmental","qty":100,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Boil the sliced potatoes for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Make a béchamel sauce with the butter, flour and milk.","timer":null},{"text":"Arrange the potatoes and the fish pieces in a dish.","timer":null},{"text":"Pour over the béchamel and top with emmental.","timer":null},{"text":"Bake for 25 min.","timer":{"label":"Oven","min":25}}],"kids":true,"variant":"The classic","change":""},{"title":"Fish and spinach gratin","intro":"A green fish gratin, with spinach.","minutes":40,"calories":400,"difficulty":"Facile","imageSearch":"fish spinach gratin","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"white fish fillet","plural":"white fish fillets","qty":600,"unit":"g","have":false},{"name":"frozen spinach","plural":"frozen spinach","qty":500,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"parmesan","plural":"parmesan","qty":50,"unit":"g","have":false},{"name":"nutmeg","plural":"nutmeg","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Defrost the spinach and squeeze out the water.","timer":null},{"text":"Mix it with the crème fraîche and nutmeg.","timer":null},{"text":"Put the fish in a dish and cover with the spinach.","timer":null},{"text":"Sprinkle with parmesan and bake for 25 min.","timer":{"label":"Oven","min":25}}],"variant":"Spinach","change":"With creamy spinach."},{"title":"Fish and tomato gratin","intro":"An Italian-style fish gratin.","minutes":40,"calories":380,"difficulty":"Facile","imageSearch":"fish tomato mozzarella bake","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"white fish fillet","plural":"white fish fillets","qty":600,"unit":"g","have":false},{"name":"chopped tomatoes","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarella","qty":1,"unit":"","have":false},{"name":"black olive","plural":"black olives","qty":50,"unit":"g","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Spread the tomatoes in a dish and lay the fish on top.","timer":null},{"text":"Add the olives and sliced mozzarella.","timer":null},{"text":"Bake for 25 min and sprinkle with basil.","timer":{"label":"Oven","min":25}}],"variant":"Tomato","change":"With tomato sauce and mozzarella."}]$r$::jsonb, 'claude')
