insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:feuillete a la saucisse', 'Sausage rolls', array['en:sausage roll', 'en:puff pastry sausage roll', 'en:pig in blanket', 'en:party sausage roll']::text[], 'dish', $r$[{"title":"Sausage rolls","intro":"Little sausages rolled in puff pastry, perfect for nibbles.","minutes":30,"calories":280,"difficulty":"Facile","imageSearch":"sausage rolls","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"puff pastry","plural":"puff pastries","qty":1,"unit":"","have":false},{"name":"cocktail sausage","plural":"cocktail sausages","qty":24,"unit":"","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tbsp","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Spread the pastry with mustard and cut into strips.","timer":null},{"text":"Roll each sausage in a strip of pastry.","timer":null},{"text":"Brush with beaten egg and bake for 18 min.","timer":{"label":"Oven","min":18}}],"makes":{"n":24,"one":"pastry","many":"pastries"},"variant":"The classic","change":""},{"title":"Meat puff pastry parcels","intro":"The bakery-style parcels, made at home.","minutes":45,"calories":380,"difficulty":"Moyen","imageSearch":"meat puff pastry friands","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"puff pastry","plural":"puff pastries","qty":2,"unit":"","have":false},{"name":"sausage meat","plural":"sausage meat","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Mix the sausage meat with the chopped onion and parsley.","timer":null},{"text":"Cut out rectangles of pastry, fill them, fold over and seal.","timer":null},{"text":"Brush with egg and bake for 25 min.","timer":{"label":"Oven","min":25}}],"makes":{"n":8,"one":"sausage roll","many":"sausage rolls"},"variant":"Parcels","change":"Puff pastry parcels filled with sausage meat."},{"title":"Cheese twists","intro":"Cheese twists for nibbles.","minutes":25,"calories":220,"difficulty":"Facile","imageSearch":"cheese straws puff pastry","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"puff pastry","plural":"puff pastries","qty":1,"unit":"","have":false},{"name":"grated emmental","plural":"grated emmental","qty":80,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Brush the pastry with egg and sprinkle with emmental and paprika.","timer":null},{"text":"Cut into strips and twist each strip.","timer":null},{"text":"Bake for 12 min.","timer":{"label":"Oven","min":12}}],"makes":{"n":20,"one":"pastry","many":"pastries"},"variant":"Vegetarian","change":"Cheesy puff pastry twists."}]$r$::jsonb, 'claude')
