insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:muffin sale', 'Savoury muffins', array['en:savoury muffin', 'en:ham and cheese muffin', 'en:party muffin']::text[], 'dish', $r$[{"title":"Ham and cheese savoury muffins","intro":"Soft muffins with ham and emmental, for nibbles or a picnic.","minutes":35,"calories":250,"difficulty":"Facile","imageSearch":"ham cheese savory muffins","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"milk","plural":"milk","qty":10,"unit":"cl","have":false},{"name":"oil","plural":"oil","qty":8,"unit":"cl","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"cooked ham","plural":"cooked ham","qty":3,"unit":"slices","have":false},{"name":"grated emmental","plural":"grated emmental","qty":100,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Mix the flour, baking powder, eggs, milk and oil.","timer":null},{"text":"Add the diced ham and emmental.","timer":null},{"text":"Fill muffin tins and bake for 20 min.","timer":{"label":"Oven","min":20}}],"kids":true,"makes":{"n":12,"one":"muffin","many":"muffins"},"variant":"The classic","change":""},{"title":"Vegetable savoury muffins","intro":"Savoury muffins with grated vegetables.","minutes":35,"calories":220,"difficulty":"Facile","imageSearch":"vegetable savory muffins","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"milk","plural":"milk","qty":10,"unit":"cl","have":false},{"name":"oil","plural":"oil","qty":8,"unit":"cl","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"grated emmental","plural":"grated emmental","qty":80,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Mix the flour, baking powder, eggs, milk and oil.","timer":null},{"text":"Add the grated carrots and emmental.","timer":null},{"text":"Fill the tins and bake for 20 min.","timer":{"label":"Oven","min":20}}],"kids":true,"makes":{"n":12,"one":"muffin","many":"muffins"},"variant":"Vegetable","change":"With carrots and cheese."},{"title":"Chorizo and pepper savoury muffins","intro":"Spicy muffins with chorizo.","minutes":35,"calories":270,"difficulty":"Facile","imageSearch":"chorizo savory muffins","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"milk","plural":"milk","qty":10,"unit":"cl","have":false},{"name":"olive oil","plural":"olive oil","qty":8,"unit":"cl","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"chorizo","plural":"chorizo","qty":80,"unit":"g","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Mix the flour, baking powder, eggs, milk and oil.","timer":null},{"text":"Add the chorizo and pepper, cut into small dice.","timer":null},{"text":"Fill the tins and bake for 20 min.","timer":{"label":"Oven","min":20}}],"makes":{"n":12,"one":"muffin","many":"muffins"},"variant":"Chorizo","change":"With chorizo and pepper."}]$r$::jsonb, 'claude')
