insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:bouillon de poulet', 'Chicken broth', array['en:chicken broth', 'en:chicken soup', 'en:chicken noodle soup', 'en:chicken stock soup']::text[], 'dish', $r$[{"title":"Chicken noodle soup","intro":"The comforting chicken broth with carrots and vermicelli, for cold-sniffle evenings.","minutes":50,"calories":280,"difficulty":"Facile","imageSearch":"chicken noodle soup","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken thigh","plural":"chicken thighs","qty":2,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"leek","plural":"leeks","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"vermicelli","plural":"vermicelli","qty":80,"unit":"g","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false}],"steps":[{"text":"Put the chicken, onion and bouquet garni in 1.5 litres of salted water and simmer for 30 min.","timer":{"label":"Cooking","min":30}},{"text":"Take out the chicken and shred it.","timer":null},{"text":"Add the sliced carrots and leek, and cook for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Add the vermicelli and chicken, and cook for 4 min.","timer":{"label":"Cooking","min":4}},{"text":"Sprinkle with parsley.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Ginger chicken broth","intro":"An Asian-style fragrant broth.","minutes":45,"calories":240,"difficulty":"Facile","imageSearch":"ginger chicken broth","veg":false,"oven":false,"cold":false,"missing":"","origin":"Asian inspired","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"fresh ginger","plural":"fresh ginger","qty":1,"unit":"","have":false},{"name":"lemongrass","plural":"lemongrass","qty":1,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":2,"unit":"tbsp","have":false},{"name":"rice noodle","plural":"rice noodles","qty":100,"unit":"g","have":false},{"name":"spring onion","plural":"spring onions","qty":2,"unit":"","have":false}],"steps":[{"text":"Put the chicken, sliced ginger and lemongrass in 1.5 litres of water and simmer for 25 min.","timer":{"label":"Cooking","min":25}},{"text":"Take out the chicken and shred it.","timer":null},{"text":"Add the soy sauce and noodles, and cook for 4 min.","timer":{"label":"Cooking","min":4}},{"text":"Put the chicken back and sprinkle with spring onion.","timer":null}],"variant":"Ginger","change":"With ginger and lemongrass."},{"title":"Chicken and rice soup","intro":"A gentle chicken soup with rice and lemon.","minutes":45,"calories":290,"difficulty":"Facile","imageSearch":"chicken rice soup lemon","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken thigh","plural":"chicken thighs","qty":2,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"rice","plural":"rice","qty":80,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false}],"steps":[{"text":"Put the chicken and onion in 1.5 litres of salted water and simmer for 30 min.","timer":{"label":"Cooking","min":30}},{"text":"Take out the chicken and shred it.","timer":null},{"text":"Add the carrots and rice, and cook for 15 min.","timer":{"label":"Cooking","min":15}},{"text":"Put the chicken back, then add the lemon juice and parsley.","timer":null}],"kids":true,"variant":"With rice","change":"Rice instead of vermicelli."}]$r$::jsonb, 'claude')
