insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:tartare de boeuf', 'Steak tartare', array['en:steak tartare', 'en:tartare', 'en:beef tartare']::text[], 'dish', $r$[{"title":"Steak tartare","intro":"Raw beef chopped by hand and seasoned with capers, gherkins, shallot and egg yolk.","minutes":20,"calories":380,"difficulty":"Moyen","imageSearch":"steak tartare","veg":false,"oven":false,"cold":true,"missing":"","origin":"French bistro dish","serves":4,"items":[{"name":"extra-fresh beef","plural":"extra-fresh beef","qty":500,"unit":"g","have":false},{"name":"shallot","plural":"shallots","qty":1,"unit":"","have":false},{"name":"capers","plural":"capers","qty":1,"unit":"tbsp","have":false},{"name":"gherkin","plural":"gherkins","qty":4,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tbsp","have":false},{"name":"worcestershire sauce","plural":"worcestershire sauce","qty":1,"unit":"tsp","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false}],"steps":[{"text":"Chop the beef with a knife as finely as you can. Keep it cold.","timer":null},{"text":"Chop the shallot, capers, gherkins and parsley.","timer":null},{"text":"Mix the beef with the mustard, Worcestershire sauce and chopped extras, then season with salt and pepper.","timer":null},{"text":"Shape into 4 portions and top each with an egg yolk.","timer":null},{"text":"Serve straight away, nice and cold, with chips or a salad.","timer":null}],"variant":"The classic","change":""},{"title":"Italian-style steak tartare","intro":"A fresh Italian-style tartare, with basil and parmesan.","minutes":20,"calories":400,"difficulty":"Moyen","imageSearch":"italian beef tartare","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"extra-fresh beef","plural":"extra-fresh beef","qty":500,"unit":"g","have":false},{"name":"parmesan","plural":"parmesan","qty":40,"unit":"g","have":false},{"name":"sun-dried tomato","plural":"sun-dried tomatoes","qty":40,"unit":"g","have":false},{"name":"pesto","plural":"pesto","qty":2,"unit":"tbsp","have":false},{"name":"rocket","plural":"rocket","qty":50,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Chop the beef with a knife.","timer":null},{"text":"Chop the sun-dried tomatoes.","timer":null},{"text":"Mix the beef with the pesto, tomatoes, oil, salt and pepper.","timer":null},{"text":"Serve with the rocket and shavings of parmesan.","timer":null}],"variant":"Italian-style","change":"With parmesan, pesto and sun-dried tomatoes."},{"title":"Seared steak tartare","intro":"The tartare that is just seared on the outside.","minutes":20,"calories":400,"difficulty":"Moyen","imageSearch":"seared beef tartare","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"extra-fresh beef","plural":"extra-fresh beef","qty":500,"unit":"g","have":false},{"name":"shallot","plural":"shallots","qty":1,"unit":"","have":false},{"name":"capers","plural":"capers","qty":1,"unit":"tbsp","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tbsp","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false}],"steps":[{"text":"Chop the beef with a knife and mix with the shallot, capers, mustard and parsley.","timer":null},{"text":"Shape into 4 thick patties.","timer":null},{"text":"Sear for 30 seconds on each side in very hot butter.","timer":{"label":"Pan","min":1}},{"text":"Serve straight away.","timer":null}],"variant":"Seared","change":"Seared for 30 seconds on each side."}]$r$::jsonb, 'claude')
