insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:carpaccio de boeuf', 'Beef carpaccio', array['en:beef carpaccio', 'en:carpaccio', 'en:beef carpaccio with parmesan']::text[], 'dish', $r$[{"title":"Beef carpaccio","intro":"Very thin slices of raw beef with olive oil, lemon, parmesan and rocket.","minutes":20,"calories":280,"difficulty":"Moyen","imageSearch":"beef carpaccio","veg":false,"oven":false,"cold":true,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"beef fillet","plural":"beef fillet","qty":400,"unit":"g","have":false},{"name":"parmesan","plural":"parmesan","qty":50,"unit":"g","have":false},{"name":"rocket","plural":"rocket","qty":60,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"capers","plural":"capers","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Put the beef in the freezer for 1 h so it is easy to slice.","timer":null},{"text":"Cut it into the thinnest slices you can.","timer":null},{"text":"Spread them out on plates.","timer":null},{"text":"Drizzle with the oil and lemon juice, and season with salt and pepper.","timer":null},{"text":"Add the rocket, capers and shavings of parmesan.","timer":null}],"variant":"The classic","change":""},{"title":"Salmon carpaccio","intro":"A fresh salmon carpaccio with lime and dill.","minutes":20,"calories":260,"difficulty":"Moyen","imageSearch":"salmon carpaccio","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"fresh salmon","plural":"fresh salmon","qty":400,"unit":"g","have":false},{"name":"lime","plural":"limes","qty":2,"unit":"","have":false},{"name":"dill","plural":"dill","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"pink peppercorn","plural":"pink peppercorns","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Put the salmon in the freezer for 1 h.","timer":null},{"text":"Cut it into very thin slices and spread them out on plates.","timer":null},{"text":"Drizzle with the oil and lime juice.","timer":null},{"text":"Sprinkle with dill and pink peppercorns.","timer":null}],"variant":"Salmon","change":"With fresh salmon."},{"title":"Courgette carpaccio","intro":"A fresh, light vegetarian carpaccio of courgettes.","minutes":15,"calories":150,"difficulty":"Facile","imageSearch":"zucchini carpaccio","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":3,"unit":"","have":false},{"name":"parmesan","plural":"parmesan","qty":40,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"fresh mint","plural":"fresh mint","qty":null,"unit":"","have":false}],"steps":[{"text":"Slice the courgettes into very thin ribbons with a peeler.","timer":null},{"text":"Spread them out on plates.","timer":null},{"text":"Drizzle with the oil and lemon juice, and season with salt and pepper.","timer":null},{"text":"Sprinkle with parmesan and mint.","timer":null}],"variant":"Vegetarian","change":"Raw courgettes in thin ribbons."}]$r$::jsonb, 'claude')
